/* Trigger structure for table `d009` */

DELIMITER $$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'%' */ /*!50003 TRIGGER `D009_trigger_estoque_principal` AFTER INSERT ON `d009` FOR EACH ROW BEGIN
  DECLARE xT066_Id INTEGER(10);
  DECLARE xD048_Id INTEGER(10);
  SET xD048_Id = 1;
  SELECT T066_Id INTO xT066_Id FROM T066 WHERE T066_D048_Id=xD048_Id AND T066_D009_Id=NEW.D009_Id;
  IF xT066_Id IS NULL THEN
     INSERT INTO T066 (T066_D048_Id,T066_D009_Id) VALUES (xD048_Id,NEW.D009_Id);
  END IF;
END */$$


DELIMITER ;

/* Trigger structure for table `d009` */

DELIMITER $$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'%' */ /*!50003 TRIGGER `D009_trigger_estoque_real` BEFORE UPDATE ON `d009` FOR EACH ROW BEGIN
  SET NEW.D009_Quantidade_Estoque_Real=NEW.D009_Quantidade_Estoque,
      NEW.D009_Quantidade_Estoque_Liquido=NEW.D009_Quantidade_Estoque_Real-D009_Quantidade_Pedido(NEW.D009_Id,1)-D009_Saldo_DF(NEW.D009_Id);
END */$$


DELIMITER ;

/* Trigger structure for table `d085` */

DELIMITER $$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'%' */ /*!50003 TRIGGER `D085_atualiza_D024` AFTER INSERT ON `d085` FOR EACH ROW BEGIN
    UPDATE D024 SET D024_D085_Id = NEW.D085_Id WHERE D024_Id=NEW.D085_D024_Id;
    UPDATE D024 SET D024_Flag_Comercial = 'A', D024_C007_Vendedor_Interno=NEW.D085_C007_Id, D024_Classe='', D024_D021_Id=NEW.D085_D021_Id, D024_Data_Ativo=curdate() WHERE D024_Id=NEW.D085_D024_Id and D024_Flag_Comercial='I';
END */$$


DELIMITER ;

/* Trigger structure for table `t001` */

DELIMITER $$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'%' */ /*!50003 TRIGGER `T001_trigger_atualiza_estoque` BEFORE INSERT ON `t001` FOR EACH ROW BEGIN

  DECLARE xD009_Saldo_Atual DECIMAL(20,3);

  DECLARE xCount INT;

  UPDATE D009 SET D009_Quantidade_Estoque=IF(NEW.T001_Flag_Operacao='S',D009_Quantidade_Estoque-NEW.T001_Quantidade,IF(NEW.T001_Flag_Operacao='E',D009_Quantidade_Estoque+NEW.T001_Quantidade,IF(NEW.T001_Flag_Operacao='B',NEW.T001_Quantidade,D009_Quantidade_Estoque))),

                  D009_Quantidade_Estoque_Real=D009_Quantidade_Estoque-D009_Quantidade_Pedido(D009_Id,2)-D009_Quantidade_Pendencia(D009_Id),

                  D009_Quantidade_Estoque_Liquido=D009_Quantidade_Estoque_Real-D009_Quantidade_Pedido(D009_Id,1),

                  D009_Valor_Custo_Unitario=IF(NEW.T001_Flag_Atualiza_Custo='S',NEW.T001_Valor_Custo_Unitario,D009_Valor_Custo_Unitario),

                  D009_Valor_Custo_Medio_Unitario=IF(NEW.T001_Flag_Atualiza_Custo='S',NEW.T001_Valor_Custo_Medio_Unitario,D009_Valor_Custo_Medio_Unitario)

   WHERE D009_Id=NEW.T001_D009_Id;

  SELECT D009_Quantidade_Estoque INTO xD009_Saldo_Atual FROM D009 WHERE D009_Id=NEW.T001_D009_Id;

  IF xD009_Saldo_Atual IS NULL THEN

    SET xD009_Saldo_Atual=0;

  END IF;

  SET NEW.T001_Quantidade_Saldo=xD009_Saldo_Atual;

  SET NEW.T001_Data_Hora_Insercao=NOW();

  -- o T066 será atualizar na trigger da tabela T186 (T186_T001_Id)

  -- -- se tiver T185 é sistema de estoque novo (multi-locação), o T066 será atualizar na trigger da tabela T186 (T186_T001_Id)

  -- SELECT COUNT(*) INTO xCount FROM T185 WHERE T185_T006_Id = NEW.T001_T006_Id;

  -- IF xCount IS NULL OR xCount = 0 THEN

  --	-- senão será sempre utilizada a primeira locação (código antigo)

  --	UPDATE T066 SET T066_Quantidade_Estoque=IF(NEW.T001_Flag_Operacao='S',T066_Quantidade_Estoque-NEW.T001_Quantidade,IF(NEW.T001_Flag_Operacao='E',T066_Quantidade_Estoque+NEW.T001_Quantidade,IF(NEW.T001_Flag_Operacao='B',NEW.T001_Quantidade,T066_Quantidade_Estoque))) WHERE T066_Id=NEW.T001_T066_Id;

  -- END IF;

END */$$


DELIMITER ;

/* Trigger structure for table `t002` */

DELIMITER $$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'%' */ /*!50003 TRIGGER `T002_Trigger_Gravar_Totais_Before_Insert` BEFORE INSERT ON `t002` FOR EACH ROW BEGIN
  SET NEW.T002_Valor_Total=ifnull(NEW.T002_Valor_Duplicata,0)+ifnull(NEW.T002_Valor_Juros,0)-ifnull(NEW.T002_Valor_Desconto,0),
      NEW.T002_Valor_Saldo=ifnull(NEW.T002_Valor_Duplicata,0)+ifnull(NEW.T002_Valor_Juros,0)-ifnull(NEW.T002_Valor_Desconto,0)-ifnull(NEW.T002_Valor_Recebido,0);
END */$$


DELIMITER ;

/* Trigger structure for table `t002` */

DELIMITER $$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'%' */ /*!50003 TRIGGER `T002_Trigger_Gravar_Totais_Before_Update` BEFORE UPDATE ON `t002` FOR EACH ROW BEGIN
	SET NEW.T002_Valor_Total=ifnull(NEW.T002_Valor_Duplicata,0)+ifnull(NEW.T002_Valor_Juros,0)-ifnull(NEW.T002_Valor_Desconto,0),
		NEW.T002_Valor_Saldo=ifnull(NEW.T002_Valor_Duplicata,0)+ifnull(NEW.T002_Valor_Juros,0)-ifnull(NEW.T002_Valor_Desconto,0)-ifnull(NEW.T002_Valor_Recebido,0);
END */$$


DELIMITER ;

/* Trigger structure for table `t006` */

DELIMITER $$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'%' */ /*!50003 TRIGGER `T006_trigger_before_delete` BEFORE DELETE ON `t006` FOR EACH ROW BEGIN

	DELETE FROM T185 WHERE T185_T006_Id = OLD.T006_Id;

	UPDATE T066 SET 

  		T066_Quantidade_Estoque_Real=T066_Quantidade_Estoque-T066_Quantidade_Separado(T066_Id),

  		T066_Quantidade_Estoque_Liquido=T066_Quantidade_Estoque-T066_Quantidade_Liquido(T066_Id)

  	WHERE T066_D009_Id=OLD.T006_D009_Id;

END */$$


DELIMITER ;

