  		UPDATE T066 SET 
  			T066_Quantidade_Estoque_Real=T066_Quantidade_Estoque-T066_Quantidade_Separado(OLD.T185_T066_Id),
  			T066_Quantidade_Estoque_Liquido=T066_Quantidade_Estoque-T066_Quantidade_Liquido(OLD.T185_T066_Id)
  		WHERE T066_Id=OLD.T185_T066_Id;
