/* Function  structure for function  `Alinha` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `Alinha`(xVar text,xTamanho int,xChar text) RETURNS text CHARSET latin1
begin

return concat(rtrim(left(xVar,xTamanho)),'',repeat(xChar,xTamanho-length(rtrim(left(xVar,xTamanho)))));

end */$$
DELIMITER ;

/* Function  structure for function  `C009_Grupo` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `C009_Grupo`(xGrupo varchar(10)) RETURNS varchar(30) CHARSET utf8
BEGIN

    DECLARE xDescricao VARCHAR(25);

       IF xGrupo=99 THEN

          SET xDescricao = 'Acessos diversos';

       END IF;

       IF xGrupo=2 THEN

          SET xDescricao = 'Cadastros';

       END IF;

       IF xGrupo=3 THEN

          SET xDescricao = 'Vendas';

       END IF;

       IF xGrupo=4 THEN

          SET xDescricao = 'Financeiro';

       END IF;

       IF xGrupo=5 THEN

          SET xDescricao = 'Estoque';

       END IF;

       IF xGrupo=6 THEN

          SET xDescricao = 'Relatórios';

       END IF;

       IF xGrupo=7 THEN

          SET xDescricao = 'Fiscal';

       END IF;

       IF xGrupo=8 THEN

          SET xDescricao = 'Configurações';

       END IF;

       IF xGrupo=9 THEN

          SET xDescricao = 'Site';

       END IF;

       IF xGrupo=10 THEN

          SET xDescricao = 'NF-e';

       END IF;

       IF xGrupo=11 THEN

          SET xDescricao = 'Importação';

       END IF;

    RETURN xDescricao;

END */$$
DELIMITER ;

/* Function  structure for function  `D001_Quantidade_Estoque` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D001_Quantidade_Estoque`(xD001_Id INT(11)) RETURNS decimal(14,3)
BEGIN

     DECLARE xRetorno DECIMAL(14,3);

      SELECT SUM(D009_Quantidade_Estoque)

        INTO xRetorno

        FROM D009

   LEFT JOIN D049 on D049_Id=D009_D049_Id

       WHERE D049_D001_Id=xD001_Id;

   IF xRetorno IS NULL THEN

      SET xRetorno = 0;

   END IF;

   RETURN xRetorno;

END */$$
DELIMITER ;

/* Function  structure for function  `D002_Grupo` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D002_Grupo`(xD002_Id int(11)) RETURNS varchar(30) CHARSET latin1
BEGIN

  DECLARE xGrupo VARCHAR(30);

  SELECT grupo.D002_Descricao_Produto

    INTO xGrupo

    FROM D002 as sub_grupo

    LEFT JOIN D002 as grupo ON grupo.D002_Grupo=sub_grupo.D002_Grupo and grupo.D002_Codigo=''

   WHERE sub_grupo.D002_Id=xD002_Id

   LIMIT 1;

  RETURN xGrupo;

END */$$
DELIMITER ;

/* Function  structure for function  `D005_IPI` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D005_IPI`(xD005_Id int(11),xC004_Id int(11), xD009_Id int(11), xD024_Id int(11), xD006_Id int(11),xDocumento INT(1)) RETURNS decimal(5,2)
BEGIN
    DECLARE xAliquota_IPI DECIMAL(5,2);
    DECLARE xC004_Flag_Isento_IPI INT(1);
    DECLARE xD006_Flag_Isento_IPI VARCHAR(1);
    DECLARE xD024_Flag_Isento_IPI INT(1);
    DECLARE xD009_Aliquota_IPI DECIMAL(6,2);
    DECLARE xD009_Flag_Isento_IPI INT(1);
    DECLARE xD005_Aliquota_IPI DECIMAL(5,2);
    DECLARE xD005_Flag_Isento_IPI INT(1);
    DECLARE xD020_Flag_IPI VARCHAR(1);
    DECLARE xD049_Flag_Nacional_Importado VARCHAR(1);
    DECLARE xD001_Flag_Tipo varchar(10);
    
    SELECT C004_Flag_Isento_IPI INTO xC004_Flag_Isento_IPI FROM C004 WHERE C004_Id=xC004_Id;
    
    SELECT D006_Flag_Isento_IPI INTO xD006_Flag_Isento_IPI FROM D006 WHERE D006_Id=xD006_Id;
    
    SELECT D020_Flag_IPI,
           D024_Flag_Isento_IPI
      INTO xD020_Flag_IPI,
           xD024_Flag_Isento_IPI
           FROM D024
           LEFT JOIN D020 on D020_Id=D024_D020_Id
           WHERE D024_Id=xD024_Id;

    SELECT D005_Aliquota_IPI,
           D005_Flag_Isento_IPI
      INTO xD005_Aliquota_IPI,
           xD005_Flag_Isento_IPI
      FROM D005
      WHERE D005_Id=xD005_Id;

    SELECT D009_Aliquota_IPI,
           D009_Flag_Isento_IPI,
           D049_Flag_Nacional_Importado,
           D001_Flag_Tipo
      INTO xD009_Aliquota_IPI,
           xD009_Flag_Isento_IPI,
           xD049_Flag_Nacional_Importado,
           xD001_Flag_Tipo
      FROM D009
      LEFT JOIN D049 ON D049_Id=D009_D049_Id
      LEFT JOIN D001 ON D001_Id=D049_D001_Id      
      WHERE D009_Id=xD009_Id;
      
   IF xD009_Aliquota_IPI>0 THEN
      SET xAliquota_IPI=xD009_Aliquota_IPI;
   ELSE
      SET xAliquota_IPI=xD005_Aliquota_IPI;
   END IF;
   
   IF xDocumento=3 OR xC004_Flag_Isento_IPI=1 OR xD006_Flag_Isento_IPI='S' OR xD020_Flag_IPI='S' OR xD024_Flag_Isento_IPI=1 OR xD009_Flag_Isento_IPI=1 OR xD005_Flag_Isento_IPI=1 THEN
      SET xAliquota_IPI=0;
   END IF;

   IF xD009_Id >0 AND xD049_Flag_Nacional_Importado!='I' AND xD001_Flag_Tipo!='PRODUZIDO' THEN
      SET xAliquota_IPI=0;
   END IF;

  RETURN xAliquota_IPI;

END */$$
DELIMITER ;

/* Function  structure for function  `D007_Tipo_Registro` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D007_Tipo_Registro`(xD007_Flag_Tipo_Registro int(1)) RETURNS varchar(20) CHARSET latin1
BEGIN
    IF xD007_Flag_Tipo_Registro = 1 THEN
       RETURN 'COM REGISTRO';
    END IF;   
    IF xD007_Flag_Tipo_Registro = 2 THEN
       RETURN 'SEM REGISTRO';
    END IF;
    IF xD007_Flag_Tipo_Registro = 3 THEN
       RETURN 'DDA';
    END IF;
    RETURN '';   
END */$$
DELIMITER ;

/* Function  structure for function  `D009_Classificacao_Fiscal` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_Classificacao_Fiscal`(xD009_Id int(11)) RETURNS varchar(12) CHARSET latin1
BEGIN
    DECLARE xD005_Classificacao_Fiscal VARCHAR(12);
       SELECT D005_Classificacao_Fiscal
         INTO xD005_Classificacao_Fiscal
         FROM D009
    LEFT JOIN D049 on D049_Id=D009_D049_Id
    LEFT JOIN D001 on D001_Id=D049_D001_Id
    LEFT JOIN D005 on D005_Id=D001_D005_Id
        WHERE D009_Id=xD009_Id
        LIMIT 1;
    IF xD005_Classificacao_Fiscal is null OR xD005_Classificacao_Fiscal='' THEN
          SELECT D005_Classificacao_Fiscal
            INTO xD005_Classificacao_Fiscal
            FROM D009
       LEFT JOIN D049 on D049_Id=D009_D049_Id
       LEFT JOIN D001 on D001_Id=D049_D001_Id
       LEFT JOIN T025 on T025_D015_Id=D001_D015_Id AND T025_D002_Id=D001_D002_Id AND T025_D024_Id=D049_D024_Id
       LEFT JOIN D005 on D005_Id=T025_D005_Id
           WHERE D009_Id=xD009_Id
           LIMIT 1;
    END IF;
    IF xD005_Classificacao_Fiscal is null OR xD005_Classificacao_Fiscal='' THEN
          SELECT D005_Classificacao_Fiscal
            INTO xD005_Classificacao_Fiscal
            FROM D009
       LEFT JOIN D049 on D049_Id=D009_D049_Id
       LEFT JOIN D001 on D001_Id=D049_D001_Id
       LEFT JOIN T025 on T025_D015_Id=D001_D015_Id AND T025_D002_Id=D001_D002_Id AND (T025_D024_Id<=0 OR T025_D024_Id is null)
       LEFT JOIN D005 on D005_Id=T025_D005_Id
           WHERE D009_Id=xD009_Id
           LIMIT 1;
    END IF;
    RETURN xD005_Classificacao_Fiscal;
END */$$
DELIMITER ;

/* Function  structure for function  `D009_Custo_Unitario` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_Custo_Unitario`(xD009_Id int(11)) RETURNS decimal(10,2)
BEGIN

  DECLARE xValor_Custo_Unitario DECIMAL(10,2);

  SELECT if(D049_Flag_Nacional_Importado='I',D009_Valor_Custo_Unitario*D016_Dolar(''),D009_Valor_Custo_Unitario)

         INTO xValor_Custo_Unitario

    FROM D009

    LEFT JOIN D049 ON D009_D049_Id=D049_Id

   WHERE D009_Id=xD009_Id

   LIMIT 1;

  RETURN xValor_Custo_Unitario;

END */$$
DELIMITER ;

/* Function  structure for function  `D009_D005_Id` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_D005_Id`(xD009_Id int(11)) RETURNS int(11)
BEGIN
    DECLARE xD005_Id INT(11);
       SELECT D005_Id
         INTO xD005_Id
         FROM D009
    LEFT JOIN D049 on D049_Id=D009_D049_Id
    LEFT JOIN D001 on D001_Id=D049_D001_Id
    LEFT JOIN D005 on D005_Id=D001_D005_Id
        WHERE D009_Id=xD009_Id
        LIMIT 1;
    IF xD005_Id is null OR xD005_Id <= 0 THEN
          SELECT D005_Id
           INTO xD005_Id
            FROM D009
       LEFT JOIN D049 on D049_Id=D009_D049_Id
       LEFT JOIN D001 on D001_Id=D049_D001_Id
       LEFT JOIN T025 on T025_D015_Id=D001_D015_Id AND T025_D002_Id=D001_D002_Id
       LEFT JOIN D005 on D005_Id=T025_D005_Id
           WHERE D009_Id=xD009_Id
           LIMIT 1;
    END IF;

    RETURN xD005_Id;

END */$$
DELIMITER ;

/* Function  structure for function  `D009_Estoque_Conjunto` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_Estoque_Conjunto`(xD009_Id int(10)) RETURNS varchar(255) CHARSET utf8
BEGIN



   DECLARE xQuantidade_Estoque_Padrao DECIMAL(10,2) DEFAULT 0;

   DECLARE xQuantidade_Estoque_Origem DECIMAL(10,2) DEFAULT 0;

   DECLARE xD001_Id_Origem DECIMAL(10,2) DEFAULT 0;

   DECLARE xC004_Id DECIMAL(10,2) DEFAULT 0;

   DECLARE xRetorno VARCHAR(50) DEFAULT 0;

   DECLARE xD049_Flag_Tipo VARCHAR(2) DEFAULT 0;



    SELECT D009_Quantidade_Estoque_Liquido,

           D001_D001_Id,

           D009_C004_Id,

           D049_Flag_Tipo

        INTO 

           xQuantidade_Estoque_Padrao,

           xD001_Id_Origem,

           xC004_Id,

           xD049_Flag_Tipo

    FROM D009 

        LEFT JOIN D049 ON D049_Id=D009_D049_Id

        LEFT JOIN D001 ON D001_Id=D049_D001_Id

    WHERE D009_Id=xD009_Id;



    SELECT D009_Quantidade_Estoque_Liquido 

        INTO

            xQuantidade_Estoque_Origem

    FROM D001

        LEFT JOIN D049 ON D049_D001_Id=D001_Id 

        LEFT JOIN D009 ON D009_D049_Id=D049_Id

    WHERE D001_Id=xD001_Id_Origem AND D009_C004_Id=xC004_Id;



    IF xD049_Flag_Tipo = 'CP' THEN

        SET xRetorno=IFNULL(REPLACE(REPLACE(REPLACE(FORMAT(xQuantidade_Estoque_Padrao, 2), '.', '|'), ',', '.'), '|', ','), 0);

    ELSE 

        SET xRetorno=CONCAT(IFNULL(REPLACE(REPLACE(REPLACE(FORMAT(xQuantidade_Estoque_Padrao, 2), '.', '|'), ',', '.'), '|', ','),0), ' / ', IFNULL(REPLACE(REPLACE(REPLACE(FORMAT(xQuantidade_Estoque_Origem, 2), '.', '|'), ',', '.'), '|', ','),0));

    END IF;

    



    RETURN xRetorno;



END */$$
DELIMITER ;

/* Function  structure for function  `D009_Flag_Preco_Tabelado` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_Flag_Preco_Tabelado`(xD009_Id INT(11)) RETURNS varchar(1) CHARSET latin1
BEGIN

    DECLARE xRetorno VARCHAR(1);

    SELECT ifnull(D009_Flag_Preco_Tabelado,'N')

      INTO xRetorno

      FROM D009

     WHERE D009_Id=xD009_Id;

    RETURN xRetorno;

END */$$
DELIMITER ;

/* Function  structure for function  `D009_Frequencia` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_Frequencia`(xD009_Id INT(10)) RETURNS int(10)
BEGIN
   DECLARE xFrequencia INT(10) DEFAULT 0;
    SELECT IFNULL(count(*),0)
      INTO xFrequencia
      FROM T001
     WHERE T001_D009_Id=xD009_Id
       AND T001_Flag_MMF='S'
       AND T001_Data_Lancamento>=date_sub(current_date(),interval 6 month)
  GROUP BY T001_D009_Id;
    RETURN xFrequencia;
END */$$
DELIMITER ;

/* Function  structure for function  `D009_ICMS_Venda` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_ICMS_Venda`(xD009_Id INT(11),xD024_Id INT(11),xC004_Id INT(11),xFlag_Venda_Compra_Outros VARCHAR(1),xCampo VARCHAR(30)) RETURNS varchar(30) CHARSET latin1
BEGIN
    DECLARE xD067_Id INT(11) DEFAULT 0;
    DECLARE xD049_Id INT(11) DEFAULT 0;
    DECLARE xD009_RS_Id INT(11) DEFAULT 0;
    DECLARE xD067_Aliquota_ICMS DECIMAL(5,2) DEFAULT 0;
    DECLARE xD067_Simbolo VARCHAR(3);
    DECLARE xD049_Flag_Substituicao_Tributaria VARCHAR(3);
    DECLARE xD067_Descricao VARCHAR(35);
    DECLARE xRetorno VARCHAR(35);
    DECLARE xEstado VARCHAR(2);
    DECLARE xFlag_Revenda_Consumidor VARCHAR(1);
       SELECT D049_Flag_Substituicao_Tributaria,
              D049_Id
         INTO xD049_Flag_Substituicao_Tributaria,
              xD049_Id
         FROM D009
    LEFT JOIN D049 ON D049_Id=D009_D049_Id 
        WHERE D009_Id=xD009_Id
        LIMIT 1;
    IF xD024_Id!='' THEN
       SELECT D018_UF,
              D024_Flag_Revenda_Consumidor
         INTO xEstado,
              xFlag_Revenda_Consumidor
         FROM D024
        LEFT JOIN D020 ON D020_Id=D024_D020_Id
        LEFT JOIN D018 ON D018_Id=D020_D018_Id
        WHERE D024_Id=xD024_Id;
    END IF;
    IF xEstado='RS' AND xC004_Id!=2 AND xFlag_Venda_Compra_Outros='T' THEN
       SELECT D009_Id
         INTO xD009_RS_Id
         FROM D009
        WHERE D009_D049_Id=xD049_Id 
          AND D009_C004_Id='2';
       IF xD009_RS_Id IS NOT NULL THEN
          SET xD009_Id = xD009_RS_Id;
       END IF;
    END IF;
       SELECT IFNULL(D067_Id,0),
              D067_Aliquota_ICMS,
              D067_Simbolo,
              D067_Descricao,
              D049_Flag_Substituicao_Tributaria
         INTO xD067_Id,
              xD067_Aliquota_ICMS,
              xD067_Simbolo,
              xD067_Descricao,
              xD049_Flag_Substituicao_Tributaria
         FROM D009
    LEFT JOIN D049 ON D049_Id=D009_D049_Id 
    LEFT JOIN D001 ON D001_Id=D049_D001_Id 
    LEFT JOIN T025 ON T025_D015_Id=D001_D015_Id AND T025_D002_Id=D001_D002_Id 
    LEFT JOIN D068 ON D068_D005_Id=T025_D005_Id
    LEFT JOIN D067 ON D067_Id=D068_D067_Id AND D068_C004_Id=D009_C004_Id
        WHERE D009_Id=xD009_Id
          AND D068_C004_Id=D009_C004_Id
        LIMIT 1;
    IF xD067_Id = 0 THEN
       SET xD067_Id = 0;
       SET xD067_Simbolo = '';
       SET xD067_Aliquota_ICMS = 0;
       SET xD067_Descricao = '';
    END IF;
    IF xEstado='RS' AND xC004_Id!=2 AND xFlag_Venda_Compra_Outros='T' AND xD067_Simbolo='ST' AND xCampo='Simbolo2' THEN
       SET xD067_Simbolo='STC';
    END IF;
    IF xD049_Flag_Substituicao_Tributaria='S' THEN
       SET xD067_Id = 0;
       SET xD067_Simbolo = 'ST';
       SET xD067_Aliquota_ICMS = 0;
       SET xD067_Descricao = 'SUBSTITUIÇÃO TRIBUTARIA';
    END IF;
    IF xCampo = 'Id' THEN 
       SET xRetorno = xD067_Id;
    END IF;
    IF xCampo = 'Aliquota_ICMS' THEN 
       SET xRetorno = xD067_Aliquota_ICMS;
    END IF;
    IF xCampo = 'Simbolo' THEN 
       SET xRetorno = xD067_Simbolo;
    END IF;
    IF xCampo = 'Simbolo2' THEN 
       SET xRetorno = xD067_Simbolo;
    END IF;
    IF xCampo = 'Descricao' THEN 
       SET xRetorno = xD067_Descricao;
    END IF;
  RETURN xRetorno;
END */$$
DELIMITER ;

/* Function  structure for function  `D009_IPI` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_IPI`(xC004_Id int(11), xD009_Id int(11), xD024_Id int(11), xD006_Id int(11),xTipo INT(1),xDocumento INT(1)) RETURNS decimal(5,2)
BEGIN
    DECLARE xAliquota_IPI DECIMAL(5,2);
    DECLARE xPercentual_Reducao_IPI decimal(5,2);
    DECLARE xC004_Flag_Isento_IPI INT(1);
    DECLARE xD006_Flag_Isento_IPI VARCHAR(1);
    DECLARE xD024_Flag_Isento_IPI INT(1);
    DECLARE xD009_Aliquota_IPI DECIMAL(6,2);
    DECLARE xD009_Percentual_Reducao_IPI DECIMAL(6,2);
    DECLARE xD009_Flag_Isento_IPI INT(1);
    DECLARE xD005_Aliquota_IPI DECIMAL(5,2);
    DECLARE xD005_Percentual_Reducao_IPI DECIMAL(5,2);
    DECLARE xD005_Flag_Isento_IPI INT(1);
    DECLARE xD020_Flag_IPI VARCHAR(1);
    DECLARE xD049_Flag_Nacional_Importado VARCHAR(1);
    DECLARE xD001_Flag_Tipo varchar(10);
    
    SELECT C004_Flag_Isento_IPI INTO xC004_Flag_Isento_IPI FROM C004 WHERE C004_Id=xC004_Id;
    SELECT D006_Flag_Isento_IPI INTO xD006_Flag_Isento_IPI FROM D006 WHERE D006_Id=xD006_Id;
    SELECT D020_Flag_IPI,
           D024_Flag_Isento_IPI
      INTO xD020_Flag_IPI,
           xD024_Flag_Isento_IPI
           FROM D024
           LEFT JOIN D020 on D020_Id=D024_D020_Id
           WHERE D024_Id=xD024_Id;
    SELECT D005_Aliquota_IPI,
           D005_Percentual_Reducao_IPI,
           D005_Flag_Isento_IPI,
           D009_Aliquota_IPI,
           D009_Percentual_Reducao_IPI,
           D009_Flag_Isento_IPI,
           D049_Flag_Nacional_Importado,
           D001_Flag_Tipo
      INTO xD005_Aliquota_IPI,
           xD005_Percentual_Reducao_IPI,
           xD005_Flag_Isento_IPI,
           xD009_Aliquota_IPI,
           xD009_Percentual_Reducao_IPI,
           xD009_Flag_Isento_IPI,
           xD049_Flag_Nacional_Importado,
           xD001_Flag_Tipo
      FROM D009
      LEFT JOIN D049 ON D049_Id=D009_D049_Id
      LEFT JOIN D001 ON D001_Id=D049_D001_Id      
      LEFT JOIN D005 ON D005_Id=D009_D005_Id(D009_Id)
      WHERE D009_C004_Id=xC004_Id
      AND D009_Id=xD009_Id;
   IF xD009_Aliquota_IPI>0 THEN
      SET xAliquota_IPI=xD009_Aliquota_IPI;
      SET xPercentual_Reducao_IPI=xD009_Percentual_Reducao_IPI;
   ELSE
      SET xAliquota_IPI=xD005_Aliquota_IPI;
      SET xPercentual_Reducao_IPI=xD005_Percentual_Reducao_IPI;
   END IF;
   IF xDocumento=3 OR xC004_Flag_Isento_IPI=1 OR xD006_Flag_Isento_IPI='S' OR xD020_Flag_IPI='S' OR xD024_Flag_Isento_IPI=1 OR xD009_Flag_Isento_IPI=1 OR xD005_Flag_Isento_IPI=1 THEN
      SET xAliquota_IPI=0;
      SET xPercentual_Reducao_IPI=0;
   END IF;
   IF xD049_Flag_Nacional_Importado!='I' AND xD001_Flag_Tipo!='PRODUZIDO' THEN
      SET xAliquota_IPI=0;
      SET xPercentual_Reducao_IPI=0;
   END IF;
   IF xTipo=1 THEN
       RETURN xAliquota_IPI;
   ELSEIF xTipo=2 THEN
       RETURN xPercentual_Reducao_IPI;
   END IF;
END */$$
DELIMITER ;

/* Function  structure for function  `D009_IPV_ICMS` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_IPV_ICMS`(xC004_Id int(11), xD024_Id int(11), xD009_Id int(11), xD006_Id int(11), xD018_Id int(11), xFlag_Revenda_Consumidor varchar(1), xComissao decimal(10,2), xDocumento int(1), xTipo int(1)) RETURNS decimal(10,4)
BEGIN

    DECLARE xFlag_IPV_Cliente VARCHAR(1);

    DECLARE xAliquota_ICMS DECIMAL(10,4);

    DECLARE xPercentual_Reducao_ICMS DECIMAL(10,4);

    DECLARE xAliquota_IPV_Cliente DECIMAL(10,4);

    DECLARE xAliquota_IPV_Utilizado DECIMAL(10,4);

    DECLARE xC004_Flag_Isento_ICMS INT(1);

    DECLARE xC004_UF varchar(2);

    DECLARE xD009_Aliquota_ICMS_Venda DECIMAL(6,2);

    DECLARE xD009_Percentual_Reducao_ICMS_Venda DECIMAL(6,2);

    DECLARE xD009_Flag_Isento_ICMS_Venda INT(1);

    DECLARE xD006_Flag_Isento_ICMS VARCHAR(1);

    DECLARE xD006_Flag_Venda_Compra_Outros VARCHAR(1);

    DECLARE xD006_Percentual_Reducao_ICMS DECIMAL(6,2) DEFAULT 0;

    DECLARE xD024_Inscricao_Estadual VARCHAR(20);

    DECLARE xD024_Flag_Pessoa_Fisica_Juridica CHAR(1);

    DECLARE xD024_Valor_IPV DECIMAL(10,4);

    DECLARE xD024_Flag_Revenda_Consumidor VARCHAR(1);

    DECLARE xD018_UF VARCHAR(2);

    DECLARE xD018_Aliquota_ICMS_1 DECIMAL(5,2);

    DECLARE xD018_Percentual_Reducao_ICMS_1 DECIMAL(5,2);

    DECLARE xD018_Aliquota_ICMS_2 DECIMAL(5,2);

    DECLARE xD018_Percentual_Reducao_ICMS_2 DECIMAL(5,2);

    DECLARE xD018_Aliquota_ICMS_Revenda DECIMAL(5,2);

    DECLARE xD018_Percentual_Reducao_ICMS_Revenda DECIMAL(5,2);

    DECLARE xD018_Aliquota_ICMS_Consumidor DECIMAL(5,2);

    DECLARE xD018_Percentual_Reducao_ICMS_Consumidor DECIMAL(5,2);

    DECLARE xD020_Flag_ICMS VARCHAR(1);

    DECLARE xD019_IPV_Maximo DECIMAL(10,4);

    DECLARE xD024_Percentual_IPV_Consumidor DECIMAL(8,4);

    DECLARE xD024_Percentual_IPV_Fornecedor_1 DECIMAL(8,4);

    DECLARE xD024_Percentual_IPV_Fornecedor_2 DECIMAL(8,4);

    DECLARE xD024_Percentual_IPV_Fornecedor_3 DECIMAL(8,4);

    DECLARE xD024_Flag_Isento_ICMS INT(1);

    DECLARE xD024_Flag_Isento_ICMS_Venda ENUM('S','N');

    DECLARE xD024_Percentual_Reducao_ICMS DECIMAL(5,2);

    DECLARE xD024_Aliquota_ICMS DECIMAL(5,2);

    DECLARE xD019_Tipo_1 DECIMAL(10,2);

    DECLARE xD019_Tipo_2 DECIMAL(10,2);

    DECLARE xD019_Percentual_Desconto_ACP DECIMAL(10,2);

    DECLARE xTabelado int(10);

    DECLARE xD049_Id int(10);

    SET xAliquota_ICMS=0;

    SET xPercentual_Reducao_ICMS=0;

    SET xAliquota_IPV_Cliente=0;

    SET xAliquota_IPV_Utilizado=0;

    SET xD024_Inscricao_Estadual='';

    SET xD024_Flag_Pessoa_Fisica_Juridica='';

    SET xD024_Valor_IPV=0;

    SET xD024_Flag_Isento_ICMS='';

    SET xD024_Flag_Isento_ICMS_Venda='N';

    SET xD024_Percentual_Reducao_ICMS=0;

    SET xD024_Aliquota_ICMS=0;

    SET xD020_Flag_ICMS='';

    SET xD006_Flag_Isento_ICMS='';

    SET xD049_Id=0;

    SELECT C004_Uf,

           C004_Flag_Isento_ICMS

      INTO xC004_UF,

           xC004_Flag_Isento_ICMS

      FROM C004

     WHERE C004_Id=xC004_Id;

    IF xD024_Id>0 THEN

        SELECT D024_Inscricao_Estadual,

              D024_Flag_Pessoa_Fisica_Juridica,

              D024_Valor_IPV,

              D024_Flag_Revenda_Consumidor,

              D024_Flag_Isento_ICMS,

              D024_Flag_Isento_ICMS_Venda,

              D024_Percentual_Reducao_ICMS,

              D024_Aliquota_ICMS,

              D053_Aliquota_ICMS_1,

              D053_Percentual_Reducao_ICMS_1,

              D053_Aliquota_ICMS_2,

              D053_Percentual_Reducao_ICMS_2,

              D053_Aliquota_ICMS_Revenda,

              D053_Percentual_Reducao_ICMS_Revenda,

              D053_Aliquota_ICMS_Consumidor,

              D053_Percentual_Reducao_ICMS_Consumidor,

              D020_Flag_ICMS,

              D018_UF

         INTO xD024_Inscricao_Estadual,

              xD024_Flag_Pessoa_Fisica_Juridica,

              xD024_Valor_IPV,

              xD024_Flag_Revenda_Consumidor,

              xD024_Flag_Isento_ICMS,

              xD024_Flag_Isento_ICMS_Venda,

              xD024_Percentual_Reducao_ICMS,

              xD024_Aliquota_ICMS,

              xD018_Aliquota_ICMS_1,

              xD018_Percentual_Reducao_ICMS_1,

              xD018_Aliquota_ICMS_2,

              xD018_Percentual_Reducao_ICMS_2,

              xD018_Aliquota_ICMS_Revenda,

              xD018_Percentual_Reducao_ICMS_Revenda,

              xD018_Aliquota_ICMS_Consumidor,

              xD018_Percentual_Reducao_ICMS_Consumidor,

              xD020_Flag_ICMS,

              xD018_UF

              FROM D024

              LEFT JOIN D020 on D020_Id=D024_D020_Id

              LEFT JOIN D018 on D018_Id=D024_D018_Id

              LEFT JOIN D053 on D053_D018_Id=D018_Id and D053_C004_Id=xC004_Id

              WHERE D024_Id=xD024_Id limit 1;

    ELSEIF xD018_Id>0 THEN

        SET xD024_Flag_Revenda_Consumidor=xFlag_Revenda_Consumidor;

        SELECT D053_Aliquota_ICMS_1,

              D053_Percentual_Reducao_ICMS_1,

              D053_Aliquota_ICMS_2,

              D053_Percentual_Reducao_ICMS_2,

              D053_Aliquota_ICMS_Revenda,

              D053_Percentual_Reducao_ICMS_Revenda,

              D053_Aliquota_ICMS_Consumidor,

              D053_Percentual_Reducao_ICMS_Consumidor,

              D018_UF

          INTO xD018_Aliquota_ICMS_1,

              xD018_Percentual_Reducao_ICMS_1,

              xD018_Aliquota_ICMS_2,

              xD018_Percentual_Reducao_ICMS_2,

              xD018_Aliquota_ICMS_Revenda,

              xD018_Percentual_Reducao_ICMS_Revenda,

              xD018_Aliquota_ICMS_Consumidor,

              xD018_Percentual_Reducao_ICMS_Consumidor,

              xD018_UF

              FROM D018

              LEFT JOIN D053 on D053_D018_Id=D018_Id and D053_C004_Id=xC004_Id

              WHERE D018_Id=xD018_Id

              LIMIT 1;

    END IF;

    IF xD006_Id>0 THEN

       SELECT D006_Flag_Isento_ICMS,

              D006_Flag_Venda_Compra_Outros,

              D006_Percentual_Reducao_ICMS

         INTO xD006_Flag_Isento_ICMS,

              xD006_Flag_Venda_Compra_Outros,

              xD006_Percentual_Reducao_ICMS

         FROM D006

        WHERE D006_Id=xD006_Id;

    END IF;

    IF xD009_Id>0 THEN

       SELECT D009_Aliquota_ICMS_Venda,

              D009_Percentual_Reducao_ICMS_Venda,

              D009_Flag_Isento_ICMS_Venda,

              D009_D049_Id

         INTO xD009_Aliquota_ICMS_Venda,

              xD009_Percentual_Reducao_ICMS_Venda,

              xD009_Flag_Isento_ICMS_Venda,

              xD049_Id

              FROM D049

              LEFT JOIN D009 on D009_D049_Id=D049_Id

              WHERE D009_Id=xD009_Id

              AND D009_C004_Id=xC004_Id;

       IF xD006_Flag_Venda_Compra_Outros!='T' THEN

          SELECT T046_Id

            INTO xTabelado

            FROM T046

            LEFT JOIN T016 ON T016_Id=T046_T016_Id

            WHERE T046_D049_Id=xD049_Id

              AND current_date()>=T016_Data_Inicio

              AND current_date()<=T016_Data_Final

            LIMIT 1;

            IF xTabelado is null then

              SELECT D041_Id

                      INTO xTabelado

                FROM D041

                WHERE D041_D049_Id=xD049_Id

                LIMIT 1;

            END IF;

        END IF;

    END IF;



       IF xC004_Flag_Isento_ICMS=1 OR xD006_Flag_Isento_ICMS='S' OR xD020_Flag_ICMS='S' OR xD009_Flag_Isento_ICMS_Venda=1 THEN

          SET xAliquota_ICMS=0;

          SET xPercentual_Reducao_ICMS=0;

       ELSEIF xD006_Flag_Venda_Compra_Outros='V' AND xD024_Flag_Isento_ICMS_Venda='S' THEN

          SET xAliquota_ICMS=0;

          SET xPercentual_Reducao_ICMS=0;

       ELSEIF xD006_Flag_Venda_Compra_Outros='C' AND xD024_Flag_Isento_ICMS='1' THEN

          SET xAliquota_ICMS=0;

          SET xPercentual_Reducao_ICMS=0;

       ELSEIF xD009_Aliquota_ICMS_Venda>0 THEN

          SET xAliquota_ICMS=xD009_Aliquota_ICMS_Venda;

          SET xPercentual_Reducao_ICMS=xD009_Percentual_Reducao_ICMS_Venda;

       ELSEIF xD024_Aliquota_ICMS>0 THEN

          SET xAliquota_ICMS=xD024_Aliquota_ICMS;

          SET xPercentual_Reducao_ICMS=xD024_Percentual_Reducao_ICMS;

       ELSEIF xD024_Flag_Revenda_Consumidor='1' AND xD018_Aliquota_ICMS_Revenda>0 THEN

          SET xAliquota_ICMS=xD018_Aliquota_ICMS_Revenda;

          SET xPercentual_Reducao_ICMS=xD018_Percentual_Reducao_ICMS_Revenda;

       ELSEIF xD024_Flag_Revenda_Consumidor!='1' AND xD018_Aliquota_ICMS_Consumidor>0 THEN

          SET xAliquota_ICMS=xD018_Aliquota_ICMS_Consumidor;

          SET xPercentual_Reducao_ICMS=xD018_Percentual_Reducao_ICMS_Consumidor;

       ELSEIF xD024_Id<=0 AND xD024_Flag_Revenda_Consumidor='1' THEN

          SET xAliquota_ICMS=xD018_Aliquota_ICMS_2;

          SET xPercentual_Reducao_ICMS=xD018_Percentual_Reducao_ICMS_1;

       ELSEIF xD024_Id<=0 AND xD024_Flag_Revenda_Consumidor!='1' THEN

          SET xAliquota_ICMS=xD018_Aliquota_ICMS_1;

          SET xPercentual_Reducao_ICMS=xD018_Percentual_Reducao_ICMS_2;

       ELSEIF xD024_Inscricao_Estadual='' OR xD024_Inscricao_Estadual='ISENTO' OR  xD024_Flag_Pessoa_Fisica_Juridica='F' THEN

          SET xAliquota_ICMS=xD018_Aliquota_ICMS_1;

          SET xPercentual_Reducao_ICMS=xD018_Percentual_Reducao_ICMS_2;

       ELSEIF (xD024_Inscricao_Estadual!='' AND xD024_Inscricao_Estadual!='ISENTO') OR  xD024_Flag_Pessoa_Fisica_Juridica='J' THEN

          SET xAliquota_ICMS=xD018_Aliquota_ICMS_2;

          SET xPercentual_Reducao_ICMS=xD018_Percentual_Reducao_ICMS_1;

       END IF;

       IF xD024_Valor_IPV>0 THEN

          SET xAliquota_IPV_Cliente=xD024_Valor_IPV;

          SET xFlag_IPV_Cliente='S';

          SELECT D019_Tipo_1,D019_Percentual_Desconto_ACP

            INTO xD019_Tipo_1,xD019_Percentual_Desconto_ACP

            FROM D019

           WHERE D019_Aliquota_ICMS=xAliquota_ICMS;

       ELSE

          IF xD024_Flag_Revenda_Consumidor!='1' THEN

             SELECT D019_IPV_Maximo,D019_Tipo_1,D019_Percentual_Desconto_ACP

               INTO xD019_IPV_Maximo,xD019_Tipo_1,xD019_Percentual_Desconto_ACP

               FROM D019

              WHERE D019_Aliquota_ICMS=0;

          ELSE

             SELECT D019_IPV_Maximo,D019_Tipo_1,D019_Percentual_Desconto_ACP

               INTO xD019_IPV_Maximo,xD019_Tipo_1,xD019_Percentual_Desconto_ACP

               FROM D019

              WHERE D019_Aliquota_ICMS=xAliquota_ICMS;

          END IF;

          SET xAliquota_IPV_Cliente=xD019_IPV_Maximo;

          SET xFlag_IPV_Cliente='N';

       END IF;

       IF xDocumento=3 THEN

          SET xAliquota_ICMS=0;

          SET xPercentual_Reducao_ICMS=0;

       END IF;

       IF xD009_Id>0 THEN

          SELECT D024_Percentual_IPV_Consumidor,

                 D024_Percentual_IPV_Fornecedor_1,

                 D024_Percentual_IPV_Fornecedor_2,

                 D024_Percentual_IPV_Fornecedor_3

            INTO xD024_Percentual_IPV_Consumidor,

                 xD024_Percentual_IPV_Fornecedor_1,

                 xD024_Percentual_IPV_Fornecedor_2,

                 xD024_Percentual_IPV_Fornecedor_3

                 FROM D009

                 LEFT JOIN D049 on D009_D049_Id=D049_Id

                 LEFT JOIN D024 on D049_D024_Id=D024_Id

                 WHERE D009_Id=xD009_Id

                 AND D009_C004_Id=xC004_Id;

          IF xFlag_IPV_Cliente='N' THEN

             IF xD024_Flag_Revenda_Consumidor!='1' THEN

                 SET xAliquota_IPV_Utilizado=xD024_Percentual_IPV_Consumidor;

             ELSEIF xAliquota_ICMS=7 THEN

                 SET xAliquota_IPV_Utilizado=xD024_Percentual_IPV_Fornecedor_1;

             ELSEIF xAliquota_ICMS=12 THEN

                 SET xAliquota_IPV_Utilizado=xD024_Percentual_IPV_Fornecedor_2;

             ELSEIF xAliquota_ICMS=17 OR xAliquota_ICMS=18 THEN

                 SET xAliquota_IPV_Utilizado=xD024_Percentual_IPV_Fornecedor_3;

             END IF;

          END IF;

          IF xAliquota_IPV_Utilizado=0 THEN

             SET xAliquota_IPV_Utilizado=xAliquota_IPV_Cliente;

          END IF;

       ELSE

           SET xAliquota_IPV_Utilizado=xAliquota_IPV_Cliente;

       END IF;

       IF xComissao>0 THEN

          SET xD019_Tipo_2 = xAliquota_IPV_Utilizado / ( 100 / (100 - xD019_Tipo_1) );

          SET xD019_Tipo_2 = ((xD019_Tipo_2 - 1) * 100) / xD019_Tipo_2;

          SET xD019_Tipo_2 = ( 100 / ( 100 - ( xD019_Tipo_2 + xComissao) ) );

          SET xD019_Tipo_1 = ( 100 / ( 100 - ( xD019_Tipo_1 ) ) );

          SET xAliquota_IPV_Utilizado = round(xD019_Tipo_1 * xD019_Tipo_2,4);

       END IF;

       IF xDocumento=3 THEN

          SET xAliquota_IPV_Utilizado = xAliquota_IPV_Utilizado - (xAliquota_IPV_Utilizado * ((xD019_Percentual_Desconto_ACP*2)/100));

       ELSE

          IF xD006_Percentual_Reducao_ICMS>0 THEN

             SET xPercentual_Reducao_ICMS=xD006_Percentual_Reducao_ICMS;

          END IF;

          IF xC004_Flag_Isento_ICMS=1 OR xD006_Flag_Isento_ICMS='S' OR xD020_Flag_ICMS='S' OR xD009_Flag_Isento_ICMS_Venda=1 THEN

             SET xAliquota_ICMS=0;

             SET xPercentual_Reducao_ICMS=0;

          END IF;

          IF xTipo=1 and xTabelado>0 THEN

              IF xD024_Flag_Revenda_Consumidor!='1' THEN

                SELECT D019_IPV_Maximo

                  INTO xAliquota_IPV_Utilizado

                  FROM D019

                  WHERE D019_Aliquota_ICMS=0;

              ELSE

                SELECT D019_IPV_Maximo

                  INTO xAliquota_IPV_Utilizado

                  FROM D019

                  WHERE D019_Aliquota_ICMS=xAliquota_ICMS;

              END IF;

          END IF;

       END IF;

       IF xTipo=1 THEN

           RETURN xAliquota_IPV_Utilizado;

       ELSEIF xTipo=2 THEN

          RETURN xAliquota_ICMS;

       ELSEIF xTipo=3 THEN

          RETURN xPercentual_Reducao_ICMS;

       END IF;

END */$$
DELIMITER ;

/* Function  structure for function  `D009_Local` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_Local`(xD009_Id int(11),xD048_Id int(11)) RETURNS varchar(6) CHARSET latin1
BEGIN
    DECLARE xD004_Local VARCHAR(6);
    SELECT D004_Local
      INTO xD004_Local
      FROM D009
      LEFT JOIN T066 on T066_D009_Id=D009_Id and T066_D048_Id=xD048_Id
      LEFT JOIN D004 on D004_Id=T066_D004_Id
     WHERE D009_Id=xD009_Id
     LIMIT 1;
  RETURN xD004_Local;
END */$$
DELIMITER ;

/* Function  structure for function  `D009_Marca_Padrao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_Marca_Padrao`(xD009_Id INT(11),xC004_Id INT(11)) RETURNS int(11)
BEGIN

     DECLARE xD001_Id INT(11);

     DECLARE xRETORNO INT(11);

     SELECT D001_Id

       INTO xD001_Id

       FROM D001

  LEFT JOIN D049 ON D049_D001_Id=D001_Id

  LEFT JOIN D009 ON D009_D049_Id=D049_Id

      WHERE D009_Id=xD009_Id

        AND D049_Flag_Tipo='MD'

      LIMIT 1;

     SELECT D009_Id

       INTO xRETORNO

       FROM D009

  LEFT JOIN D049 ON D049_Id=D009_D049_Id

      WHERE D049_D001_Id=xD001_Id

        AND D009_C004_Id=xC004_Id

        AND D049_Flag_Tipo='CP'

      LIMIT 1;

     RETURN xRETORNO;

END */$$
DELIMITER ;

/* Function  structure for function  `D009_Minimo_Maximo` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_Minimo_Maximo`(xD009_Id INT(10),xTipo int(1)) RETURNS int(10)
BEGIN
   DECLARE xMinimo INT(10) DEFAULT 0;
   DECLARE xMaximo INT(10) DEFAULT 0;
    SELECT IFNULL((sum(T001_Quantidade)/6)*2,0),
           IFNULL((sum(T001_Quantidade)/6)*4,0)
      INTO xMinimo,
           xMaximo
      FROM T001
     WHERE T001_D009_Id=xD009_Id
       AND T001_Flag_MMF='S'
       AND T001_Data_Lancamento>=date_sub(current_date(),interval 6 month)
  GROUP BY T001_D009_Id;
    IF xTipo=1 THEN
       RETURN xMinimo;
    ELSE
       RETURN xMaximo;
    END IF;
END */$$
DELIMITER ;

/* Function  structure for function  `D009_Origem_Preco` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_Origem_Preco`(xD009_Id int(11),xD024_Id int(11), xTipo INT(1)) RETURNS varchar(1) CHARSET latin1
BEGIN
  DECLARE xFlag_Origem_Preco VARCHAR(1) DEFAULT " ";
  DECLARE xT046_Valor_Base DECIMAL(14,2) DEFAULT 0;
  DECLARE xD041_Valor_Preco_Consumidor DECIMAL(14,2) DEFAULT 0;
  DECLARE xT046_Flag_Ignorar_Promocao_Consumidor varchar(1) default 'N';
  DECLARE xD041_Valor_Base DECIMAL(14,2) DEFAULT 0;
  DECLARE xD024_Flag_Empresas_Grupo VARCHAR(1) default 'N';
  SELECT D024_Flag_Empresas_Grupo
    INTO xD024_Flag_Empresas_Grupo
    from D024
  WHERE D024_Id=xD024_Id;
  IF xD024_Flag_Empresas_Grupo!='S' THEN
     SELECT T046_Valor_Base,
            T046_Flag_Ignorar_Promocao_Consumidor
       INTO XT046_Valor_Base,
            xT046_Flag_Ignorar_Promocao_Consumidor
       FROM T046 
       LEFT JOIN T016 ON T016_Id=T046_T016_Id
       LEFT JOIN D049 ON D049_Id=T046_D049_Id
       LEFT JOIN D009 ON D049_Id=D009_D049_Id
      WHERE D009_Id=xD009_Id
        AND current_date()>=T016_Data_Inicio
        AND current_date()<=T016_Data_Final
      limit 1;
     SELECT D041_Valor_Preco_Consumidor,
            D041_Valor_Base
       INTO xD041_Valor_Preco_Consumidor,
            xD041_Valor_Base
       FROM D009
       LEFT JOIN D049 ON D049_Id=D009_D049_Id
       LEFT JOIN D041 ON D049_Id=D041_D049_Id
      WHERE D009_Id=xD009_Id
      LIMIT 1;
     IF xT046_Flag_Ignorar_Promocao_Consumidor='S' AND xTipo=1 THEN
        SET xT046_Valor_Base=0;
     END IF;
     IF xD041_Valor_Preco_Consumidor > 0 AND xTipo=1 THEN
        SET xFlag_Origem_Preco='T';
     ELSEIF xT046_Valor_Base > 0 THEN
        SET xFlag_Origem_Preco='O';
     ELSEIF xD041_Valor_Base > 0 THEN
        SET xFlag_Origem_Preco='T';
     END IF;
  END IF;
  RETURN xFlag_Origem_Preco;
END */$$
DELIMITER ;

/* Function  structure for function  `D009_Preco_Unitario` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_Preco_Unitario`(xD009_Id INT(11), xD024_Id INT(11), xIPV DECIMAL(10,4), xTipo INT(1),xD006_Id INT(11)) RETURNS decimal(10,2)
BEGIN
  DECLARE xD041_Valor_Preco_Consumidor_Atacado DECIMAL(10,2);
  DECLARE xD041_Valor_Preco_Consumidor_Varejo DECIMAL(10,2);
  DECLARE xD041_Valor_Preco_Revenda DECIMAL(10,2);
  SELECT D041_Valor_Preco_Consumidor,
         D041_Valor_Base,
         D041_Valor_Preco_Revenda
    INTO xD041_Valor_Preco_Consumidor_Varejo,
         xD041_Valor_Preco_Consumidor_Atacado,
         xD041_Valor_Preco_Revenda
    FROM D009
    LEFT JOIN D049 ON D049_Id=D009_D049_Id
    LEFT JOIN D041 ON D049_Id=D041_D049_Id
   WHERE D009_Id=xD009_Id
     AND D041_D024_Id=xD024_Id
   LIMIT 1;
  IF xD041_Valor_Preco_Consumidor_Varejo IS NULL THEN
     SELECT D041_Valor_Preco_Consumidor,
            D041_Valor_Base,
            D041_Valor_Preco_Revenda
       INTO xD041_Valor_Preco_Consumidor_Varejo,
            xD041_Valor_Preco_Consumidor_Atacado,
            xD041_Valor_Preco_Revenda
       FROM D009
       LEFT JOIN D049 ON D049_Id=D009_D049_Id
       LEFT JOIN D041 ON D049_Id=D041_D049_Id
      WHERE D009_Id=xD009_Id
      LIMIT 1;
  END IF;
  IF XTipo=1 THEN
     RETURN xD041_Valor_Preco_Revenda;
  ELSEIF XTipo=2 THEN
     RETURN xD041_Valor_Preco_Consumidor_Atacado;
  ELSEIF XTipo=3 THEN
     RETURN xD041_Valor_Preco_Consumidor_Varejo;
  ELSE
     RETURN 0;
  END IF;
END */$$
DELIMITER ;

/* Function  structure for function  `D009_Quantidade_Comprar` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_Quantidade_Comprar`(xD009_Id INT(11), xTipo INT(1)) RETURNS decimal(14,3)
BEGIN
     DECLARE xT006_Quantidade DECIMAL(14,3);
      SELECT SUM(T006_Quantidade)
        INTO xT006_Quantidade
        FROM T006
   LEFT JOIN T005 ON T006_T005_Id=T005_Id
       WHERE T006_D009_Id=xD009_Id
  	     AND T006_Flag_Tipo_Produto='CP'
  	     AND T006_Flag_Status!='3';
   IF xT006_Quantidade IS NULL THEN
