/* Function  structure for function  `D009_Quantidade_Montagem` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_Quantidade_Montagem`(xD009_Id INT(11)) RETURNS int(11)
BEGIN
  DECLARE xQuantidade_Montagem decimal(10,2);
  DECLARE xD049_Id INT(11);
  DECLARE xC004_Id INT(11);
     SELECT D009_D049_Id,
            D009_C004_Id
       INTO xD049_Id,
            xC004_Id
       FROM D009
      WHERE D009_Id=xD009_Id limit 1;
     SELECT floor(D009_Quantidade_Estoque_Real/D042_Quantidade) Quantidade_Minima
       INTO xQuantidade_Montagem
       FROM D042
  LEFT JOIN D009 on D009_D049_Id=D042_D049_Id_Itens and D009_C004_Id=xC004_Id
      WHERE D042_D049_Id=xD049_Id
        AND D042_C004_Id=xC004_Id
   ORDER BY Quantidade_Minima
      LIMIT 1;
  IF xQuantidade_Montagem IS NULL OR xQuantidade_Montagem<0 THEN
     SET xQuantidade_Montagem=0;
  END IF;
  RETURN xQuantidade_Montagem;
END */$$
DELIMITER ;

/* Function  structure for function  `D009_Quantidade_OC` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_Quantidade_OC`(xD009_Id INT(11)) RETURNS decimal(10,3)
BEGIN
   DECLARE xQuantidade decimal(10,3);
   DECLARE xNacImp varchar(1);
      SELECT D049_Flag_Nacional_Importado
        INTO xNacImp
        FROM D009
   LEFT JOIN D049 ON D049_Id=D009_D049_Id
       WHERE D009_Id=xD009_Id;
 
   IF xNacImp='I' THEN
        SELECT sum(T053_Quantidade-ifnull((select ifnull(sum(T055_Quantidade),0) from T055 left join T054 on T054_Id=T055_T054_Id where T055_T053_Id=T053_Id and T054_Data_Transferencia_Estoque!='0000-00-00 00:00:00'),0))
          INTO xQuantidade 
          FROM T053 
     LEFT JOIN T052 ON T052_Id=T053_T052_Id
         WHERE T052_Data_Emissao>=DATE_SUB(current_date(), interval 6 month)
           AND T053_D009_Id=xD009_Id
           AND T053_Flag_Cancelada!='S'
           AND T053_Flag_Cancelada!='S';
   ELSE 
        SELECT sum(T012_Quantidade-ifnull((select ifnull(sum(T014_Quantidade),0) from T014 left join T013 on T013_Id=T014_T013_Id where T014_T012_Id=T012_Id and T013_Flag_Travar_Nota='S' and T013_Flag_Cancelada!='S'),0))
          INTO xQuantidade 
          FROM T012 
     LEFT JOIN T011 ON T011_Id=T012_T011_Id
         WHERE T011_Data_Emissao>=DATE_SUB(current_date(), interval 6 month)
           AND T012_D009_Id=xD009_Id
           AND T012_Flag_Cancelada!='S'
           AND T011_Flag_Cancelada!='S';
   END IF;
   IF xQuantidade IS NULL or xQuantidade<0 THEN
      SET xQuantidade = 0;
   END IF;
   RETURN xQuantidade;
END */$$
DELIMITER ;

/* Function  structure for function  `D009_Quantidade_OC_3` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_Quantidade_OC_3`(xD009_Id int(10), xT075_Id int(10)) RETURNS varchar(10) CHARSET utf8
BEGIN



     DECLARE xQuantidade_OC DECIMAL(10,2);

     DECLARE xQuantidade_Pedidos DECIMAL(10,2);

     DECLARE xRetorno DECIMAL(10,2);

      

      SELECT SUM(T055_Quantidade)

        INTO xQuantidade_OC

        FROM T055

   		LEFT JOIN T075 ON T075_Id=T055_T075_Id

   		LEFT JOIN D009 ON D009_Id=T055_D009_Id

       WHERE T055_T075_Id=xT075_Id

  	     AND T055_D009_Id=xD009_Id;

  	       	     

      SELECT SUM(T006_Quantidade)

        INTO xQuantidade_Pedidos

        FROM T006

        LEFT JOIN D009 on D009_Id=T006_D009_Id

        LEFT JOIN T075 on T075_Id=T006_T075_Id        

       WHERE T006_T075_Id=xT075_Id

      	 AND T006_D009_Id=xD009_Id

         AND T006_Flag_Status!='3';

      

      SET xRetorno=xQuantidade_OC;	 

       IF xQuantidade_Pedidos>0 THEN

          SET xRetorno = xQuantidade_OC-xQuantidade_Pedidos;

       END IF;           

      	   	     

   RETURN xRetorno;

   

END */$$
