/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `D009_Quantidade_OS`(xD009_Id INT(11)) RETURNS decimal(10,3)
BEGIN
   DECLARE xQuantidade decimal(10,3);
        SELECT sum(T129_Quantidade-ifnull((select ifnull(sum(T014_Quantidade),0) from T013,T014 where T014_T129_Id=T129_Id and T013_Id=T014_T013_Id and T013_Flag_Cancelada='N' and T013_Flag_Travar_Nota='S'),0))
          INTO xQuantidade 
          FROM T129
         WHERE T129_D009_Id=xD009_Id
           AND T129_Flag_Cancelada!='S'
           group by T129_D009_Id;
   IF xQuantidade IS NULL or xQuantidade<0 THEN
      SET xQuantidade = 0;
   END IF;
   RETURN xQuantidade;
END */$$
