     	D137_D024_Flag_Contribuinte,
			D137_Produzido_Adquirido,
			D137_Estados_Especificos,
			D137_Dentro_Fora_Estado,
			D137_UF_Tem_ST,
			D137_D005_Id,
			D137_NCM_Tem_ST,
			D137_Pessoa_Fisica_Juridica,
      D137_Flag_UF_Convenio_NCM_ST,
			D137_Flag_Cabecalho_Item,
			D137_Flag_Inativar
	   INTO xD137_C004_Id,
      xD137_Empresas,
      xD137_Flag_Revenda_Consumidor,
      xD137_C004_Codigo_Regime_Tributario,   
	   	xD137_D024_Flag_Contribuinte,
			xD137_Produzido_Adquirido,
			xD137_Estados_Especificos,
			xD137_Dentro_Fora_Estado,
			xD137_UF_Tem_ST,
			xD137_D005_Id,
			xD137_NCM_Tem_ST,
			xD137_Pessoa_Fisica_Juridica,
      xD137_Flag_UF_Convenio_NCM_ST,
      xD137_Flag_Cabecalho_Item,
      xD137_Flag_Inativar
       FROM D137
      WHERE D137_Id=xD137_Id;
   IF xD137_Empresas != "" THEN
      SET D137_Quantidade = D137_Quantidade + 10;
   END IF;
   IF xD137_C004_Id > 0 THEN
      SET D137_Quantidade = D137_Quantidade + 1;
   END IF;
   IF xD137_Flag_Revenda_Consumidor != "" THEN
      SET D137_Quantidade = D137_Quantidade + 1;
   END IF;
   IF xD137_Flag_UF_Convenio_NCM_ST != "" THEN
      SET D137_Quantidade = D137_Quantidade + 1;
   END IF;
 	 IF xD137_C004_Codigo_Regime_Tributario != 0 THEN
      SET D137_Quantidade = D137_Quantidade + 1;
   END IF;
   IF xD137_D024_Flag_Contribuinte != 0 THEN
      SET D137_Quantidade = D137_Quantidade + 1;
   END IF;
   IF xD137_Produzido_Adquirido != "" THEN
      SET D137_Quantidade = D137_Quantidade + 1;
   END IF;
   IF xD137_Estados_Especificos != "" THEN
      SET D137_Quantidade = D137_Quantidade + 1;
   END IF;
   IF xD137_Dentro_Fora_Estado != "" THEN
      SET D137_Quantidade = D137_Quantidade + 1;
   END IF;
   IF xD137_UF_Tem_ST != "" THEN
      SET D137_Quantidade = D137_Quantidade + 1;
   END IF;
   IF xD137_D005_Id != 0 THEN
      SET D137_Quantidade = D137_Quantidade + 1;
   END IF;
   IF xD137_NCM_Tem_ST != "" THEN
      SET D137_Quantidade = D137_Quantidade + 1;
   END IF;
   IF xD137_Pessoa_Fisica_Juridica != "" THEN
      SET D137_Quantidade = D137_Quantidade + 1;
   END IF;
   RETURN D137_Quantidade;
END */$$
DELIMITER ;

/* Function  structure for function  `formata_cnpj` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `formata_cnpj`(cnpj varchar(20)) RETURNS varchar(18) CHARSET latin1
BEGIN  
 	DECLARE retorno varchar(18);  
 	-- Retirando possiveis formatacoes no valor recebido.  
 	SET retorno = cnpj;
 	SET retorno = REPLACE(retorno,'.','');  
 	SET retorno = REPLACE(retorno,'-','');  
 	SET retorno = REPLACE(retorno,'/','');  
 	SET retorno = REPLACE(retorno,' ','');  
 	SET retorno = TRIM(retorno);  
 	-- Armazenando o valor recebido em uma variavel interna  
 	IF LENGTH(retorno)<14 THEN
	    return '';
 	END IF;
 	-- Montando a formatacao  
 	SET retorno = concat(mid(retorno,1,2),'.',mid(retorno,3,3),'.',mid(retorno,6,3),'/',mid(retorno,9,4),'-',mid(retorno,13,2));  
 	-- Retornando o resultado  
 	return retorno;  
 END */$$
DELIMITER ;

/* Function  structure for function  `formata_cpf` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `formata_cpf`(cpf varchar(20)) RETURNS varchar(14) CHARSET latin1
BEGIN  
 	DECLARE retorno varchar(14);  
 	-- Retirando possiveis formatacoes no valor recebido.  
 	SET retorno = cpf;
 	SET retorno = REPLACE(retorno,'.','');  
 	SET retorno = REPLACE(retorno,'-','');  
 	SET retorno = REPLACE(retorno,' ','');  
 	SET retorno = TRIM(retorno);  
 	-- Armazenando o valor recebido em uma variavel interna  
 	IF LENGTH(retorno)>11 or LENGTH(retorno)<11 THEN
	    return '';
 	END IF;
 	-- Montando a formatacao  
 	SET retorno = concat(mid(retorno,1,3),'.',mid(retorno,4,3),'.',mid(retorno,7,3),'-',mid(retorno,10,2));  
 	-- Retornando o resultado  
 	return retorno;  
 END */$$
DELIMITER ;

/* Function  structure for function  `ICMS_Inter_Estadual` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `ICMS_Inter_Estadual`(xC004_Id int(11), xD024_Id int(11), xD018_Id int(11), xFlag_Revenda_Consumidor varchar(1), xDocumento int(1), xTipo int(1)) RETURNS decimal(10,2)
BEGIN

    DECLARE xAliquota_ICMS DECIMAL(10,2);

    DECLARE xPercentual_Reducao_ICMS DECIMAL(10,4);

    DECLARE xC004_UF varchar(2);

    DECLARE xD024_Inscricao_Estadual VARCHAR(20);

    DECLARE xD024_Flag_Pessoa_Fisica_Juridica CHAR(1);

    DECLARE xD024_Flag_Revenda_Consumidor VARCHAR(1);

    DECLARE xD018_UF VARCHAR(2);

    DECLARE xD018_Aliquota_ICMS_1 DECIMAL(5,2);

    DECLARE xD018_Percentual_Reducao_ICMS_1 DECIMAL(5,2);

    DECLARE xD018_Aliquota_ICMS_2 DECIMAL(5,2);

    DECLARE xD018_Percentual_Reducao_ICMS_2 DECIMAL(5,2);

    SET xAliquota_ICMS=0;

    SET xPercentual_Reducao_ICMS=0;

    SET xD024_Inscricao_Estadual='';

    SET xD024_Flag_Pessoa_Fisica_Juridica='';

    SELECT C004_Uf

      INTO xC004_UF

      FROM C004

     WHERE C004_Id=xC004_Id;

     IF xD024_Id>0 THEN

        SELECT D024_Inscricao_Estadual,

              D024_Flag_Pessoa_Fisica_Juridica,

              D024_Flag_Revenda_Consumidor,

              D018_Id

         INTO xD024_Inscricao_Estadual,

              xD024_Flag_Pessoa_Fisica_Juridica,

              xD024_Flag_Revenda_Consumidor,

              xD018_Id

              FROM D024

              LEFT JOIN D018 ON D018_Id=D024_D018_Id

              WHERE D024_Id=xD024_Id limit 1;

    END IF;

    IF xD018_Id>0 THEN

        SET xD024_Flag_Revenda_Consumidor=xFlag_Revenda_Consumidor;

        SELECT D053_Aliquota_ICMS_1,

              D053_Percentual_Reducao_ICMS_1,

              D053_Aliquota_ICMS_2,

              D053_Percentual_Reducao_ICMS_2,

              D018_UF

          INTO xD018_Aliquota_ICMS_1,

              xD018_Percentual_Reducao_ICMS_1,

              xD018_Aliquota_ICMS_2,

              xD018_Percentual_Reducao_ICMS_2,

              xD018_UF

              FROM D018

              LEFT JOIN D053 on D053_D018_Id=D018_Id and D053_C004_Id=xC004_Id

              WHERE D018_Id=xD018_Id

              LIMIT 1;

    END IF;

    IF xD024_Id<=0 AND xD024_Flag_Revenda_Consumidor='R' THEN

       SET xAliquota_ICMS=xD018_Aliquota_ICMS_2;

       SET xPercentual_Reducao_ICMS=xD018_Percentual_Reducao_ICMS_1;

    ELSEIF xD024_Id<=0 AND xD024_Flag_Revenda_Consumidor='C' THEN

       SET xAliquota_ICMS=xD018_Aliquota_ICMS_1;

       SET xPercentual_Reducao_ICMS=xD018_Percentual_Reducao_ICMS_2;

    ELSEIF xD024_Inscricao_Estadual='' OR xD024_Inscricao_Estadual='ISENTO' OR  xD024_Flag_Pessoa_Fisica_Juridica='F' THEN

       SET xAliquota_ICMS=xD018_Aliquota_ICMS_1;

       SET xPercentual_Reducao_ICMS=xD018_Percentual_Reducao_ICMS_2;

    ELSEIF (xD024_Inscricao_Estadual!='' AND xD024_Inscricao_Estadual!='ISENTO') OR  xD024_Flag_Pessoa_Fisica_Juridica='J' THEN

       SET xAliquota_ICMS=xD018_Aliquota_ICMS_2;

       SET xPercentual_Reducao_ICMS=xD018_Percentual_Reducao_ICMS_1;

    END IF;

    IF xC004_UF='PR' and xD018_UF='PR' and xD024_Flag_Revenda_Consumidor='R' THEN

       SET xAliquota_ICMS=12;

    END IF;



    IF xTipo=1 THEN

       RETURN xAliquota_ICMS;

    ELSEIF xTipo=2 THEN

       RETURN xPercentual_Reducao_ICMS;

    END IF;



END */$$
DELIMITER ;

/* Function  structure for function  `Quantidade` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `Quantidade`(xQuantidade decimal(10,3), xUnidade varchar(3), xPeso_Unitario decimal(10,3), xPeso_Pacote decimal(10,3), xQuantidade_Pacote int(10), xUnidade_Retorno varchar(3)) RETURNS decimal(10,3)
BEGIN
   declare xQte_KLG decimal(10,3);
   declare xQte_PCT decimal(10,3);
   declare xQte_UND decimal(10,3);
   if xUnidade='KLG' THEN
       set xQte_KLG = xQuantidade;
       set xQte_PCT = xQuantidade/xPeso_Pacote;
       set xQte_UND = xQuantidade/xPeso_Unitario;
   elseif xUnidade='PCT' THEN
       set xQte_KLG = xQuantidade*xPeso_Pacote;
       set xQte_PCT = xQuantidade;
       set xQte_UND = xQuantidade*xQuantidade_Pacote;
   elseif xUnidade='UND' THEN
       set xQte_KLG = xQuantidade*xPeso_Unitario;
       set xQte_PCT = xQuantidade/xQuantidade_Pacote;
       set xQte_UND = xQuantidade;
   elseif xUnidade!='XXX' THEN
       set xQte_KLG = xQuantidade*xPeso_Unitario;
       set xQte_PCT = xQuantidade/xQuantidade_Pacote;
       set xQte_UND = xQuantidade;
   end if;
   if xUnidade_Retorno='KLG' THEN
      return xQte_KLG;
   elseif xUnidade_Retorno='PCT' THEN
      return xQte_PCT;
   elseif xUnidade_Retorno='UND' THEN
      return xQte_UND;
   elseif xUnidade_Retorno!='XXX' THEN
      return xQte_UND;
   end if;
END */$$
DELIMITER ;

/* Function  structure for function  `T003_IPV_Medio` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `T003_IPV_Medio`(xT003_Id int(11),xTipo int(1)) RETURNS decimal(10,4)
BEGIN

    DECLARE xTotal_IPV DECIMAL(10,4);

    DECLARE xTotal_Itens INT(10);

    DECLARE xIPV_Medio DECIMAL(10,4);

    IF xTipo=1 THEN

       SELECT SUM(T004_Valor_Total_Preco)/SUM(T004_Valor_Total_Custo),

              SUM(1)

         INTO xTotal_IPV,

              xTotal_Itens

         FROM T004

    LEFT JOIN T003 on T003_Id=T004_T003_Id

    LEFT JOIN D009 on D009_Id=T004_D009_Id

        WHERE T004_T003_Id=xT003_Id

          AND T004_Quantidade>0

          AND T004_Flag_Cancelado!='S'

          AND ifnull(D009_Flag_Preco_Tabelado,'N')!='S'

          AND T004_Id NOT IN (SELECT T004_Id FROM T006 LEFT JOIN T004 ON T004_Id=T006_T004_Id WHERE T004_T003_Id=xT003_Id)

        GROUP BY T004_T003_Id;

    ELSEIF xTipo=2 THEN

       SELECT SUM(T004_Valor_Total_Preco_Confirmado)/SUM(T004_Valor_Total_Custo_Confirmado),

              SUM(1)

         INTO xTotal_IPV,

              xTotal_Itens

         FROM T004

    LEFT JOIN T003 on T003_Id=T004_T003_Id

    LEFT JOIN D009 on D009_Id=T004_D009_Id

        WHERE T004_T003_Id=xT003_Id

          AND T004_Quantidade_Confirmada>0

          AND T004_Flag_Cancelado!='S'

          AND ifnull(D009_Flag_Preco_Tabelado,'N')!='S'

          AND T004_Id NOT IN (SELECT T004_Id FROM T006 LEFT JOIN T004 ON T004_Id=T006_T004_Id WHERE T004_T003_Id=xT003_Id)

        GROUP BY T004_T003_Id;

    ELSEIF xTipo=3 THEN

       SELECT SUM(T004_Valor_Total_Preco)/SUM(T004_Valor_Total_Custo),

              SUM(1)

         INTO xTotal_IPV,

              xTotal_Itens

         FROM T004

    LEFT JOIN T003 on T003_Id=T004_T003_Id

    LEFT JOIN D009 on D009_Id=T004_D009_Id

        WHERE T004_T003_Id=xT003_Id

          AND T004_Quantidade>0

          AND T004_Flag_Cancelado!='S'

          AND ifnull(D009_Flag_Preco_Tabelado,'N')!='S'

        GROUP BY T004_T003_Id;

    ELSEIF xTipo=4 THEN

       SELECT SUM(T004_Valor_Total_Preco_Confirmado)/SUM(T004_Valor_Total_Custo_Confirmado),

              SUM(1)

         INTO xTotal_IPV,

              xTotal_Itens

         FROM T004

    LEFT JOIN T003 on T003_Id=T004_T003_Id

    LEFT JOIN D009 on D009_Id=T004_D009_Id

        WHERE T004_T003_Id=xT003_Id

          AND T004_Quantidade_Confirmada>0

          AND T004_Flag_Cancelado!='S'

          AND ifnull(D009_Flag_Preco_Tabelado,'N')!='S'

        GROUP BY T004_T003_Id;

    END IF;

    IF xTotal_Itens>0 THEN

       SET xIPV_Medio=xTotal_IPV;

    ELSE

       SET xIPV_Medio=0;

    END IF;

    RETURN xIPV_Medio;

END */$$
DELIMITER ;

/* Function  structure for function  `T003_Prazos` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `T003_Prazos`(xT003_Id int(11)) RETURNS varchar(255) CHARSET latin1
BEGIN

    DECLARE xTotal_Parcelas INT(2) DEFAULT 0;

    DECLARE xTotal_Prazos VARCHAR(255);

    DECLARE xRetorno VARCHAR(255) DEFAULT '';

    DECLARE xPrazos_Dias INT(5) DEFAULT 0;

    DECLARE xNumero_Parcela  INT(3) DEFAULT 0;

    DECLARE xFlag_ACP VARCHAR(1) DEFAULT ' ';

    DECLARE xFlag_Gera_Contas VARCHAR(1) DEFAULT ' ';



    SELECT T003_Flag_ACP,

           D006_Flag_Gera_Contas

      INTO xFlag_ACP,

           xFlag_Gera_Contas

      FROM T003

      LEFT JOIN D006 ON D006_Id=T003_D006_Id

     WHERE T003_Id=xT003_Id;

    IF xFlag_ACP!=2 AND xFlag_Gera_Contas!='N' THEN



       SELECT SUM(1),

              CONCAT(GROUP_CONCAT(T089_Prazos_Dias SEPARATOR ' / '),' Dias'),

              T089_Prazos_Dias,

              T089_Numero_Parcela

         INTO xTotal_Parcelas,

              xTotal_Prazos,

              xPrazos_Dias,

              xNumero_Parcela

         FROM T089

         WHERE T089_T003_Id=xT003_Id

         GROUP BY T089_T003_Id;

         IF xTotal_Parcelas > 0 THEN

            IF xTotal_Parcelas = 1 AND xPrazos_Dias = 0 THEN

               SET xRetorno = 'A VISTA';

            ELSE

               SET xRetorno = xTotal_Prazos;

            END IF;

         ELSE

            SET xRetorno = 'A COMBINAR';

         END IF;

    END IF;

    RETURN xRetorno;

END */$$
DELIMITER ;

/* Function  structure for function  `T004_Ultimo_Preco` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `T004_Ultimo_Preco`(xD001_Id INT(11), xD024_Id INT(11), xT003_Id INT(11), xTipo varchar(1)) RETURNS varchar(94) CHARSET latin1
BEGIN

    DECLARE xRetorno VARCHAR(94);

    if xTipo=2 then

       SELECT concat(concat('R$ ',format(T008_Valor_Preco_Unitario,2),' - Qte: ',format(T008_Quantidade,2),' - ',date_format(T007_Data_Emissao,'%d/%m/%Y'),' ( ',datediff(current_date(),T007_Data_Emissao),' ) ',' - ',left(D024_Nome_Empresa,15)),' - NF: ',T007_Numero_Nota_Fiscal,' - ',C007_Primeiro_Nome)

         INTO xRetorno

         FROM T008

    LEFT JOIN T007 on T007_Id=T008_T007_Id

    LEFT JOIN D009 on D009_Id=T008_D009_Id

    LEFT JOIN D049 on D049_Id=D009_D049_Id

    LEFT JOIN D024 on D024_Id=T007_D024_Id

    LEFT JOIN C007 on C007_Id=T007_C007_Id_Vendedor_Interno

        WHERE T007_D024_Id=xD024_Id

          AND D009_D001_Id=xD001_Id

     ORDER BY T007_Data_Emissao desc

        LIMIT 0,1;

    else

       SELECT concat(concat('R$ ',format(T004_Valor_Preco_Unitario,2),' - Qte: ',format(T004_Quantidade,2),' - ',date_format(T003_Data_Emissao,'%d/%m/%Y'),' ( ',datediff(current_date(),T003_Data_Emissao),' ) ',' - ',left(D024_Nome_Empresa,15)),' - Orc: ',format(T003_Id,0),' - ',C007_Primeiro_Nome)

         INTO xRetorno

         FROM T004

    LEFT JOIN T003 on T003_Id=T004_T003_Id

    LEFT JOIN D009 on D009_Id=T004_D009_Id

    LEFT JOIN D049 on D049_Id=D009_D049_Id

    LEFT JOIN D024 on D024_Id=T003_D024_Id

    LEFT JOIN C007 on C007_Id=T003_C007_Id_Vendedor_Interno

        WHERE T003_D024_Id=xD024_Id

          AND D009_D001_Id=xD001_Id

          AND T003_Id!=xT003_Id

          AND T004_Valor_Preco_Unitario>0

     ORDER BY T003_Data_Emissao desc

        LIMIT 0,1;

    end if;

    RETURN xRetorno;

END */$$
DELIMITER ;

/* Function  structure for function  `T005_IPV_Medio` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `T005_IPV_Medio`(xT005_Id int(11),xTipo int(1)) RETURNS decimal(10,4)
BEGIN

    DECLARE xTotal_IPV DECIMAL(10,4);

    DECLARE xTotal_Itens INT(10);

    DECLARE xIPV_Medio DECIMAL(10,4);

    SELECT SUM(T006_Valor_Total_Preco)/sum(T006_Valor_Total_Custo),

           SUM(1)

      INTO xTotal_IPV,

           xTotal_Itens

           FROM T006

      LEFT JOIN T005 ON T005_Id=T006_T005_Id

           WHERE T006_T005_Id=xT005_Id

            GROUP BY T006_T005_Id;

    IF xTotal_Itens>0 THEN

       SET xIPV_Medio=xTotal_IPV;

    ELSE

       SET xIPV_Medio=0;

    END IF;

    RETURN xIPV_Medio;

END */$$
DELIMITER ;

