/* Function  structure for function  `T005_Status_Pedido` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `T005_Status_Pedido`(xStatus int(2),xTipo int(1)) RETURNS varchar(30) CHARSET latin1
BEGIN

    DECLARE xDescricao VARCHAR(25);

    SET xDescricao = '';

    IF xTipo=1 THEN

       IF xStatus=1 THEN

          SET xDescricao = 'Imprimir Pedido';

       END IF;

