/* Function  structure for function  `T007_IPV_Medio` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `T007_IPV_Medio`(xT007_Id int(11),xTipo int(1)) RETURNS decimal(10,4)
BEGIN

    DECLARE xTotal_IPV DECIMAL(10,4);

    DECLARE xFalta_IPV INT(3);

    SET xTotal_IPV=0;

    SET xFalta_IPV=0;



    SELECT IFNULL(SUM(1),0)

           INTO xFalta_IPV

           FROM T008

           WHERE T008_T007_Id=xT007_Id

           AND (T008_Valor_Total_Preco<=0

           OR T008_Valor_Total_Custo<=0);



    IF xFalta_IPV<=0 THEN





        IF xTipo=2 THEN

             SELECT (SUM(T008_Valor_Total_Preco)-SUM(T008_Valor_ICMS))/SUM(T008_Valor_Total_Custo)

                    INTO xTotal_IPV

                    FROM T008

                    WHERE T008_T007_Id=xT007_Id

                    GROUP BY T008_T007_Id;

        END IF;

        IF xTipo = 1 THEN

             SELECT SUM(T008_Valor_Total_Preco)/SUM(T008_Valor_Total_Custo)

                    INTO xTotal_IPV

                    FROM T008

                    WHERE T008_T007_Id=xT007_Id

                    GROUP BY T008_T007_Id;

        END IF;

        IF xTipo = 3 THEN

             SELECT SUM(T008_Valor_Total_Preco)/SUM(T008_Valor_Custo_Compra_Unitario*T008_Quantidade)

                    INTO xTotal_IPV

                    FROM T008

                    WHERE T008_T007_Id=xT007_Id

                    GROUP BY T008_T007_Id;

        END IF;

    END IF;

    RETURN xTotal_IPV;

END */$$
DELIMITER ;

/* Function  structure for function  `T007_Prazos` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `T007_Prazos`(xT007_Id int(11)) RETURNS varchar(255) CHARSET latin1
BEGIN

    DECLARE xTotal_Parcelas INT(2) DEFAULT 0;

    DECLARE xTotal_Prazos VARCHAR(255);

    DECLARE xRetorno VARCHAR(255) DEFAULT 'A COMBINAR';

    DECLARE xPrazos_Dias INT(5) DEFAULT 0;

    DECLARE xNumero_Parcela  INT(3) DEFAULT 0;

    DECLARE xFlag_ACP VARCHAR(1) DEFAULT ' ';

    DECLARE xFlag_Gera_Contas VARCHAR(1) DEFAULT ' ';

    SELECT T007_Flag_ACP,

           D006_Flag_Gera_Contas

      INTO xFlag_ACP,

           xFlag_Gera_Contas

      FROM T007

      LEFT JOIN D006 ON D006_Id=T007_D006_Id

     WHERE T007_Id=xT007_Id;

    IF xFlag_ACP!=2 AND xFlag_Gera_Contas!='N' THEN

       SELECT SUM(1),

              CONCAT(GROUP_CONCAT(T118_Prazos_Dias SEPARATOR ' / '),' Dias'),

              T118_Prazos_Dias,

              T118_Numero_Parcela

         INTO xTotal_Parcelas,

              xTotal_Prazos,

              xPrazos_Dias,

              xNumero_Parcela

         FROM T118

        WHERE T118_T007_Id=xT007_Id

        GROUP BY T118_T007_Id;



        IF xTotal_Parcelas > 0 THEN

           IF xTotal_Parcelas = 1 AND xPrazos_Dias = 0 THEN

              SET xRetorno = 'A VISTA';

           ELSE

              SET xRetorno = xTotal_Prazos;

           END IF;

        ELSE

           SET xRetorno = 'A COMBINAR';

        END IF;

    END IF;

    RETURN xRetorno;

END */$$
DELIMITER ;

/* Function  structure for function  `T007_Primeira_Ultima_Compra` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `T007_Primeira_Ultima_Compra`(xTipo int(1), xD024_Id integer) RETURNS varchar(10) CHARSET latin1
BEGIN

	Declare xRetorno VARCHAR(10);





	if xTipo=1 then

		select T007_Data_Emissao

		into xRetorno

                     from T007

                left join D006 on D006_Id=T007_D006_Id

                    where T007_D024_Id = xD024_Id

                      and D006_Flag_Entrada_Saida='S'

                      and T007_Flag_Cancelada <> 'S'

                      and D006_Flag_Gera_Contas='R'

                      and D006_Flag_Devolucao<>'S'

                      and D006_Flag_Venda_Compra_Outros = 'V'

                 order by T007_Data_Emissao asc

		limit 1;

		IF xRetorno is null THEN

			SET xRetorno = '0000-00-00';

		END if;

	elseif xTipo=2 then

		select T007_Data_Emissao

		into xRetorno

                     from T007

                left join D006 on D006_Id=T007_D006_Id

                    where T007_D024_Id = xD024_Id

                      and D006_Flag_Entrada_Saida='S'

                      and T007_Flag_Cancelada <> 'S'

                      and D006_Flag_Gera_Contas='R'

                      and D006_Flag_Devolucao<>'S'

                      and D006_Flag_Venda_Compra_Outros = 'V'

                 order by T007_Data_Emissao desc

		limit 1;

		IF xRetorno is null THEN

			SET xRetorno = '0000-00-00';

		END if;

	elseif xTipo=3 then

		select T007_C004_Id

		into xRetorno

                     from T007

                left join D006 on D006_Id=T007_D006_Id

                    where T007_D024_Id = xD024_Id

                      and D006_Flag_Entrada_Saida='S'

                      and T007_Flag_Cancelada <> 'S'

                      and D006_Flag_Gera_Contas='R'

                      and D006_Flag_Devolucao<>'S'

                      and D006_Flag_Venda_Compra_Outros = 'V'

                 order by T007_Data_Emissao desc

		limit 1;

		IF xRetorno is null THEN

			SET xRetorno = '0';

		END if;

	end if;



     Return xRetorno;

END */$$
DELIMITER ;

/* Function  structure for function  `T008_Quantidade_Falta_Lancar` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `T008_Quantidade_Falta_Lancar`(xT008_Id INT(11),xT086_Id INT(11)) RETURNS decimal(15,3)
BEGIN

     DECLARE xQuantidade_Falta_Lancar DECIMAL(15,3);

     SELECT IFNULL(T008_Quantidade,0)-IFNULL(SUM(IF(T013_Flag_Cancelada!='S',T014_Quantidade,0)),0)-IFNULL(SUM(T086_Quantidade),0)

       INTO xQuantidade_Falta_Lancar

       FROM T008

  LEFT JOIN T086 on T086_T008_Id=T008_Id and T086_Id!=xT086_Id

  LEFT JOIN T014 on T014_T008_Id=T008_Id

  LEFT JOIN T013 on T013_Id=T014_T013_Id

      WHERE T008_Id=xT008_Id;

     IF xQuantidade_Falta_Lancar IS NULL or xQuantidade_Falta_Lancar<0 THEN

        SET xQuantidade_Falta_Lancar = 0;

     END IF;

     RETURN xQuantidade_Falta_Lancar;

END */$$
DELIMITER ;

/* Function  structure for function  `T008_ST_Cupom` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `T008_ST_Cupom`(xT008_Id int(10)) RETURNS char(2) CHARSET latin1
BEGIN

    DECLARE xRetorno CHAR(2) default NULL;

    DECLARE xAliquota_ICMS decimal(5,2) default 0;

	DECLARE xFlag_ST char(1) default 'N';

	DECLARE xD059_Id int(10) default 0;	   

    

    select T008_Aliquota_ICMS,

    	   T008_Flag_ST,

    	   T008_D059_Id

      into xAliquota_ICMS,

           xFlag_ST,

           xD059_Id	   

   	  from T008 

   	  left join D006 on D006_Id=T008_D006_Id

   	 where T008_Id=xT008_Id;

   	

   	

   	 IF xFlag_ST='S' THEN

   	 

  	    select D090_Codigo_Impressora

          into xRetorno

		  from D090

	     where D090_Flag_ST=xFlag_ST;

	     

     ELSEIF xAliquota_ICMS>0 THEN

   	 

  	    select D090_Codigo_Impressora

          into xRetorno  	    

		  from D090

	     where D090_Aliquota_Icms=xAliquota_ICMS;

	     

	 ELSEIF xAliquota_ICMS=0 THEN 

	 

  	    select D090_Codigo_Impressora

          into xRetorno  	    

		  from D090

	     where D090_D059_Id=xD059_Id;

	     

     END IF;   

     

 	 IF xRetorno IS NULL THEN

   	 	SET xRetorno='NN'; -- Isenção

     END IF;	   		

  	 

    RETURN xRetorno;

END */$$
DELIMITER ;

