/* Function  structure for function  `T054_Status_Importacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `T054_Status_Importacao`(xStatus int(2),xTipo int(1)) RETURNS varchar(25) CHARSET latin1
BEGIN

    DECLARE xDescricao VARCHAR(25);

    IF xTipo=1 THEN

       IF xStatus=1 THEN

          SET xDescricao = 'Imprimir Pedido';

       END IF;

       IF xStatus=2 THEN

          SET xDescricao = 'Conferindo Pe?as';

       END IF;

       IF xStatus=3 THEN

          SET xDescricao = 'Emitindo Nota Fiscal';

       END IF;

       IF xStatus=4 THEN

          SET xDescricao = 'Finalizado';

       END IF;

    END IF;

    IF xTipo=2 THEN

       IF xStatus=1 THEN

          SET xDescricao = 'Imprima o Pedido';

       END IF;

       IF xStatus=2 THEN

          SET xDescricao = 'Confira a Mercadoria';

       END IF;

       IF xStatus=3 THEN

          SET xDescricao = 'Emitir Nota Fiscal';

       END IF;

       IF xStatus=4 THEN

          SET xDescricao = 'Finalizado';

       END IF;

    END IF;

    RETURN xDescricao;

END */$$
