/* Function  structure for function  `T055_Converte_Custo` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` FUNCTION `T055_Converte_Custo`(xT054_Id INT(10),xT052_D044_Id INT(10),xT053_Valor_Custo_Unitario DECIMAL(10,2)) RETURNS decimal(19,5)
BEGIN

    DECLARE xT054_Valor_Cambio_Dolar DECIMAL(10,4);

    DECLARE xT054_Valor_Cambio_Euro  DECIMAL(10,4);

    DECLARE xT054_D044_Id INTEGER;

    DECLARE xValor_Custo DECIMAL(19,5);

    DECLARE xValor_Custo_Real DECIMAL(19,5);

    SELECT T054_Valor_Cambio_Dolar,

           T054_Valor_Cambio_Euro,

           T054_D044_Id

      INTO

           xT054_Valor_Cambio_Dolar,

           xT054_Valor_Cambio_Euro,

           xT054_D044_Id

      FROM T054

       WHERE T054_Id=xT054_Id;

    IF xT052_D044_Id=xT054_D044_Id THEN

        SET xValor_Custo = xT053_Valor_Custo_Unitario;

    ELSE

        IF xT054_D044_Id=2 AND xT052_D044_Id=3 THEN

           SET xValor_Custo_Real = xT053_Valor_Custo_Unitario * xT054_Valor_Cambio_Euro;

           SET xValor_Custo = xValor_Custo_Real / xT054_Valor_Cambio_Dolar;

        END IF;

        IF xT054_D044_Id=3 AND xT052_D044_Id=2 THEN

           SET xValor_Custo_Real = xT053_Valor_Custo_Unitario * xT054_Valor_Cambio_Dolar;

           SET xValor_Custo = xValor_Custo_Real / xT054_Valor_Cambio_Euro;

        END IF;

    END IF;

    RETURN xValor_Custo;

END */$$
DELIMITER ;

