       IF xStatus=25 THEN

          SET xDescricao = 'NF CANCELADA';

       END IF;

       IF xStatus=10 THEN

          SET xDescricao = 'Confer?cia Pedido';

       END IF;

       IF xStatus=11 THEN

          SET xDescricao = 'Pago';

       END IF;

       IF xStatus=3 THEN

          SET xDescricao = 'Emitir Nota Fiscal';

       END IF;

       IF xStatus=4 THEN

          SET xDescricao = 'Aguardando Entrega';

       END IF;

       IF xStatus=5 THEN

          SET xDescricao = 'Pedido Finalizado';

       END IF;

       IF xStatus=6 THEN

          SET xDescricao = 'Aguardando Liberacao';

       END IF;

       IF xStatus=7 THEN

          SET xDescricao = 'Romaneio';

       END IF;

       IF xStatus=8 THEN

          SET xDescricao = 'Cancelado';

       END IF;

       IF xStatus=9 THEN

          SET xDescricao = 'Nao Liberado';

       END IF;

       IF xStatus=20 THEN

          SET xDescricao = 'Aguardando Liberacao';

       END IF;

       IF xStatus=21 THEN

          SET xDescricao = 'Aguardando Pecas';

       END IF;

       IF xStatus=22 THEN

          SET xDescricao = 'Disponivel p/Faturar';

       END IF;

       IF xStatus=23 THEN

          SET xDescricao = 'Aguard.Prod/Compra';

