/* Procedure structure for procedure `D069_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `D069_Gravar_Totalizacao`(xD069_Id int(11))
BEGIN

    UPDATE D069
    LEFT JOIN D070 ON D070_Id=D069_D070_Id
    SET D069_Preco_Unitario_Liquido   = D069_Preco_Unitario - (D069_Preco_Unitario * ( D069_Percentual_Desconto/100 ) ),
        D069_Valor_Frete              = D069_Preco_Unitario_Liquido * ( D069_Percentual_Frete / 100 ),
        D069_Valor_Financeiro         = D069_Preco_Unitario_Liquido * ( D069_Percentual_Financeiro / 100 ),
        D069_Valor_Outros             = D069_Preco_Unitario_Liquido * ( D069_Percentual_Outros / 100 ),
        D069_Valor_Base_IPI           = D069_Preco_Unitario_Liquido + D069_Valor_Financeiro + D069_Valor_Frete,
        D069_Valor_IPI                = D069_Valor_Base_IPI * ( D069_Aliquota_IPI / 100 ),
        D069_Valor_Base_ICM           = D069_Preco_Unitario_Liquido + D069_Valor_Financeiro + D069_Valor_Frete,
        D069_Valor_ICM                = D069_Valor_Base_ICM * ( D069_Aliquota_ICMS / 100 ),
        D069_MVA_Ajustada             = IF( D070_Flag_Ajustar_MVA = 'S', ( ( (1+(D069_MVA/100)) *   ( ( 1 - ( D069_Aliquota_ICM_Inter_Estadual / 100 ) ) / ( 1 - ( D069_Aliquota_ICM_Interno / 100 ) ) ) ) - 1 ) * 100, D069_MVA ),
        D069_Valor_Base_ST            = IF( D069_Flag_ST = 'S' , ( D069_Preco_Unitario_Liquido+D069_Valor_IPI+D069_Valor_Financeiro+D069_Valor_Frete ) * ( ( D069_MVA_Ajustada / 100 ) + 1 ) , 0 ),
        D069_Valor_ST                 = IF( D069_Flag_ST = 'S' , ( D069_Valor_Base_ST * ( D069_Aliquota_ICM_Interno / 100 ) ) - ( D069_Preco_Unitario_Liquido * ( D069_Aliquota_ICM_Inter_Estadual / 100 ) ) , 0 ),
        D069_Valor_ST                 = IF( D069_Valor_ST < 0 , 0 , D069_Valor_ST ),
        D069_Valor_Custo_Unitario     = D069_Preco_Unitario_Liquido + D069_Valor_IPI + D069_Valor_ST + D069_Valor_Frete + D069_Valor_Financeiro + D069_Valor_Outros
       WHERE D069_Id=xD069_Id;
END */$$
DELIMITER ;

/* Procedure structure for procedure `T002_Baixar_Titulo` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T002_Baixar_Titulo`(xT002_Id int(11),xData date)
BEGIN
     DECLARE xT002_Valor_Saldo decimal(10,2);
     DECLARE xT002_Data_Recebimento date;
     UPDATE T002
        SET T002_Valor_Juros=(select sum(T020_Valor) from T020 where T020_T002_Id=T002_Id and T020_Flag_Deb_Cred='C' group by T020_T002_Id),
            T002_Valor_Desconto=(select sum(T020_Valor) from T020 where T020_T002_Id=T002_Id and T020_Flag_Deb_Cred='D' group by T020_T002_Id),
            T002_Valor_Recebido=(select sum(T019_Valor_Lancamento) from T019 where T019_T002_Id=T002_Id and T019_Flag_Excluido!='S'),
            T002_Valor_Total=ifnull(T002_Valor_Duplicata,0)+ifnull(T002_Valor_Juros,0)-ifnull(T002_Valor_Desconto,0),
            T002_Valor_Saldo=ifnull(T002_Valor_Duplicata,0)+ifnull(T002_Valor_Juros,0)-ifnull(T002_Valor_Desconto,0)-ifnull(T002_Valor_Recebido,0)
      WHERE T002_Id=xT002_Id;
     SELECT T002_Valor_Saldo,
            T002_Data_Recebimento
       INTO xT002_Valor_Saldo,
            xT002_Data_Recebimento
       FROM T002
      WHERE T002_Id=xT002_Id;
     IF xT002_Valor_Saldo<=0 THEN
        IF xT002_Data_Recebimento='0000-00-00' THEN
           UPDATE T002
              SET T002_Data_Recebimento=xData,
                  T002_Data_Baixa=(select T019_Data_Lancamento from T019 where T019_T002_Id=T002_Id order by T019_Data_Lancamento desc limit 1)
            WHERE T002_Id=xT002_Id;
        END IF;
     ELSE
        UPDATE T002
           SET T002_Data_Recebimento='0000-00-00',
               T002_Data_Baixa='0000-00-00'
         WHERE T002_Id=xT002_Id;
     END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `T002_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T002_Gravar_Totalizacao`(xT002_Id int(11))
BEGIN
     UPDATE T002
        SET T002_Valor_Juros=(select sum(T020_Valor) from T020 where T020_T002_Id=T002_Id and T020_Flag_Deb_Cred='C' group by T020_T002_Id),
            T002_Valor_Desconto=(select sum(T020_Valor) from T020 where T020_T002_Id=T002_Id and T020_Flag_Deb_Cred='D' group by T020_T002_Id),
            T002_Valor_Recebido=(select sum(T019_Valor_Lancamento) from T019 where T019_T002_Id=T002_Id),
            T002_Valor_Total=ifnull(T002_Valor_Duplicata,0)+ifnull(T002_Valor_Juros,0)-ifnull(T002_Valor_Desconto,0)-ifnull(T002_Valor_Recebido,0)
      WHERE T002_Id=xT002_Id;
END */$$
DELIMITER ;

/* Procedure structure for procedure `T003_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T003_Gravar_Totalizacao`(xT003_Id int(11))
BEGIN
    DECLARE xValor_Total_Custo DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Preco DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Produtos DECIMAL(10,2);
    DECLARE xValor_Total_Produtos_Confirmado DECIMAL(10,2);
    DECLARE xValor_ICMS DECIMAL(10,2);
    DECLARE xValor_ICMS_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_ICMS DECIMAL(10,2);
    DECLARE xValor_Base_ICMS_Confirmado DECIMAL(10,2);
    DECLARE xValor_IPI DECIMAL(10,2);
    DECLARE xValor_IPI_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_IPI DECIMAL(10,2);
    DECLARE xValor_Base_IPI_Confirmado DECIMAL(10,2);
    DECLARE xIPV DECIMAL(10,4);
    DECLARE xIPV_Confirmado DECIMAL(10,4);
    DECLARE xPeso_Total DECIMAL(10,3);
    DECLARE xPeso_Total_Confirmado DECIMAL(10,3);
    DECLARE xValor_Total_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Desconto_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_ST DECIMAL(10,2);
    DECLARE xValor_ST DECIMAL(10,2);
    DECLARE xValor_Base_ST_Confirmado DECIMAL(10,2);
    DECLARE xValor_ST_Confirmado DECIMAL(10,2);
    SELECT sum(T004_Valor_Total_Custo),
           sum(T004_Valor_Total_Custo_Confirmado),
           sum(T004_Valor_Total_Preco),
           sum(T004_Valor_Total_Preco_Confirmado),
           sum(T004_Valor_Total_Preco_Sem_Desconto),
           sum(T004_Valor_Total_Preco_Sem_Desconto_Confirmado),
           sum(T004_Valor_Total_Custo_Final),
           sum(T004_Valor_Total_Custo_Final_Confirmado),
           sum(T004_Valor_ICMS),
           sum(T004_Valor_ICMS_Confirmado),
           sum(T004_Valor_Base_ICMS),
           sum(T004_Valor_Base_ICMS_Confirmado),
           sum(T004_Valor_IPI),
           sum(T004_Valor_IPI_Confirmado),
           sum(T004_Valor_Base_IPI),
           sum(T004_Valor_Base_IPI_Confirmado),
           sum(T004_Peso_Total),
           sum(T004_Peso_Total_Confirmado),
           sum(T004_Valor_Total_Desconto),
           sum(T004_Valor_Total_Desconto_Confirmado),
           sum(T004_Valor_Base_ST),
           sum(T004_Valor_ST),
           sum(T004_Valor_Base_ST_Confirmado),
           sum(T004_Valor_ST_Confirmado)
      INTO xValor_Total_Custo,
           xValor_Total_Custo_Confirmado,
           xValor_Total_Preco,
           xValor_Total_Preco_Confirmado,
           xValor_Total_Preco_Sem_Desconto,
           xValor_Total_Preco_Sem_Desconto_Confirmado,
           xValor_Total_Custo_Final,
           xValor_Total_Custo_Final_Confirmado,
           xValor_ICMS,
           xValor_ICMS_Confirmado,
           xValor_Base_ICMS,
           xValor_Base_ICMS_Confirmado,
           xValor_IPI,
           xValor_IPI_Confirmado,
           xValor_Base_IPI,
           xValor_Base_IPI_Confirmado,
           xPeso_Total,
           xPeso_Total_Confirmado,
           xValor_Total_Desconto,
           xValor_Total_Desconto_Confirmado,
           xValor_Base_ST,
           xValor_ST,
           xValor_Base_ST_Confirmado,
           xValor_ST_Confirmado
           FROM T004
           WHERE T004_T003_Id=xT003_Id
             AND T004_Flag_Cancelado!='S';
    UPDATE T003 SET T003_Valor_Total_Produtos=xValor_Total_Preco,
                    T003_Valor_Total_Produtos_Confirmado=xValor_Total_Preco_Confirmado,
                    T003_Valor_Total_Produtos_Sem_Desconto=xValor_Total_Preco_Sem_Desconto,
                    T003_Valor_Total_Produtos_Sem_Desconto_Confirmado=xValor_Total_Preco_Sem_Desconto_Confirmado,
                    T003_Valor_Total_Custo_Final=xValor_Total_Custo_Final,
                    T003_Valor_Total_Custo_Final_Confirmado=xValor_Total_Custo_Final_Confirmado,
                    T003_Valor_Total_Custo=xValor_Total_Custo,
                    T003_Valor_Total_Custo_Confirmado=xValor_Total_Custo_Confirmado,
                    T003_Valor_Total_Base_ICMS=xValor_Base_ICMS,
                    T003_Valor_Total_Base_ICMS_Confirmado=xValor_Base_ICMS_Confirmado,
                    T003_Valor_Total_ICMS=xValor_ICMS,
                    T003_Valor_Total_ICMS_Confirmado=xValor_ICMS_Confirmado,
                    T003_Valor_Total_Base_IPI=xValor_Base_IPI,
                    T003_Valor_Total_Base_IPI_Confirmado=xValor_Base_IPI_Confirmado,
                    T003_Valor_Total_IPI=xValor_IPI,
                    T003_Valor_Total_IPI_Confirmado=xValor_IPI_Confirmado,
                    T003_Valor_ISS=if(T003_Aliquota_ISS>0,T003_Valor_Mao_Obra*(T003_Aliquota_ISS/100),0),
                    T003_Valor_Base_ST=xValor_Base_ST,
                    T003_Valor_ST=xValor_ST,
                    T003_Valor_Base_ST_Confirmado=xValor_Base_ST_Confirmado,
                    T003_Valor_Desconto=xValor_Total_Desconto,
                    T003_Valor_Desconto_Confirmado=xValor_Total_Desconto_Confirmado,
                    T003_Valor_ST_Confirmado=xValor_ST_Confirmado,
                    T003_Valor_Total=T003_Valor_Total_Produtos+
                                     T003_Valor_Mao_Obra+
                                     T003_Valor_Despesas_Acessorias+
                                     T003_Valor_Total_IPI+
                                     T003_Valor_ST+
                                     if (T003_Flag_Frete=1,T003_Valor_Frete,0),
                    T003_Valor_Total_Confirmado=if(T003_Flag_Confirmar_Mao_Obra='S' or ifnull(xValor_Total_Preco_Confirmado,0)>0,
                                     T003_Valor_Total_Produtos_Confirmado+
                                     T003_Valor_Mao_Obra+
                                     T003_Valor_Despesas_Acessorias+
                                     T003_Valor_Total_IPI_Confirmado+
                                     T003_Valor_ST_Confirmado+
                                     if (T003_Flag_Frete=1,T003_Valor_Frete,0),0),
                    T003_Valor_Total_Abertos=(SELECT SUM(T004_Valor_Total_Preco) from T004 WHERE T004_T003_Id=xT003_Id AND T004_Flag_Cancelado!='S' AND T004_Id NOT IN (SELECT T004_Id FROM T006 LEFT JOIN T004 ON T004_Id=T006_T004_Id WHERE T004_T003_Id=xT003_Id)),
                    T003_Valor_Total_Fechados=(SELECT SUM(T004_Valor_Total_Preco) from T004 WHERE T004_T003_Id=xT003_Id AND T004_Flag_Cancelado!='S' AND T004_Id IN (SELECT T004_Id FROM T006 LEFT JOIN T004 ON T004_Id=T006_T004_Id WHERE T004_T003_Id=xT003_Id)),
                    T003_Valor_Total_Cancelados=(SELECT SUM(T004_Valor_Total_Preco) from T004 WHERE T004_T003_Id=xT003_Id AND T004_Flag_Cancelado='S'),
                    T003_IPV=T003_IPV_Medio(xT003_Id,1),
                    T003_IPV_Confirmado=T003_IPV_Medio(xT003_Id,2),
                    T003_IPV_Normal=T003_IPV_Medio(xT003_Id,3),
                    T003_IPV_Normal_Confirmado=T003_IPV_Medio(xT003_Id,4),
                    T003_Peso_Total=xPeso_Total,
                    T003_Peso_Total_Confirmado=xPeso_Total_Confirmado
              WHERE T003_Id=xT003_Id;
END */$$
DELIMITER ;

/* Procedure structure for procedure `T003_Gravar_Totalizacao_3` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T003_Gravar_Totalizacao_3`(xT003_Id int(11))
BEGIN
    DECLARE xValor_Total_Custo DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Preco DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Produtos DECIMAL(10,2);
    DECLARE xValor_Total_Produtos_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Agregados DECIMAL(10,2);
    DECLARE xValor_Total_Servicos DECIMAL(10,2);
    DECLARE xValor_Total_Trocas DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Bruto DECIMAL(10,2);
    DECLARE xValor_ICMS DECIMAL(10,2);
    DECLARE xValor_ICMS_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_ICMS DECIMAL(10,2);
    DECLARE xValor_Base_ICMS_Confirmado DECIMAL(10,2);
    DECLARE xValor_IPI DECIMAL(10,2);
    DECLARE xValor_IPI_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_IPI DECIMAL(10,2);
    DECLARE xValor_Base_IPI_Confirmado DECIMAL(10,2);
    DECLARE xIPV DECIMAL(10,4);
    DECLARE xIPV_Confirmado DECIMAL(10,4);
    DECLARE xPeso_Total DECIMAL(10,3);
    DECLARE xPeso_Bruto_Total DECIMAL(10,3);
    DECLARE xPeso_Total_Confirmado DECIMAL(10,3);
    DECLARE xValor_Total_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Desconto_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_ST DECIMAL(10,2);
    DECLARE xValor_ST DECIMAL(10,2);
    DECLARE xValor_Base_ST_Confirmado DECIMAL(10,2);
    DECLARE xValor_ST_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Cubagem DECIMAL(10,3) default 0;
    DECLARE xValor_Trib_Transparencia DECIMAL(15,2) DEFAULT 0;
    SELECT sum(T004_Valor_Total_Custo),
           sum(T004_Valor_Total_Custo_Confirmado),
           sum(T004_Valor_Total_Preco),
           sum(T004_Valor_Total_Preco_Confirmado),
           sum(T004_Valor_Total_Preco_Sem_Desconto),
           sum(T004_Valor_Total_Preco_Sem_Desconto_Confirmado),
           sum(T004_Valor_Total_Custo_Final),
           sum(T004_Valor_Total_Custo_Final_Confirmado),
           sum(T004_Valor_ICMS),
           sum(T004_Valor_ICMS_Confirmado),
           sum(T004_Valor_Total_Agregados),
           sum(T004_Valor_Base_ICMS),
           sum(T004_Valor_Base_ICMS_Confirmado),
           sum(T004_Valor_IPI),
           sum(T004_Valor_IPI_Confirmado),
           sum(T004_Valor_Base_IPI),
           sum(T004_Valor_Base_IPI_Confirmado),
           sum(T004_Peso_Total),
           sum(T004_Peso_Bruto_Total),
           sum(T004_Peso_Total_Confirmado),
           sum(T004_Valor_Total_Desconto),
           sum(T004_Valor_Total_Desconto_Confirmado),
           sum(T004_Valor_Base_ST),
           sum(T004_Valor_ST),
           sum(T004_Valor_Base_ST_Confirmado),
           sum(T004_Valor_ST_Confirmado),
           sum(T004_Valor_Preco_Bruto),
           sum(T004_Total_Cubagem),
           sum(T004_Valor_Trib_Transparencia)
      INTO xValor_Total_Custo,
           xValor_Total_Custo_Confirmado,
           xValor_Total_Preco,
           xValor_Total_Preco_Confirmado,
           xValor_Total_Preco_Sem_Desconto,
           xValor_Total_Preco_Sem_Desconto_Confirmado,
           xValor_Total_Custo_Final,
           xValor_Total_Custo_Final_Confirmado,
           xValor_ICMS,
           xValor_ICMS_Confirmado,
           xValor_Total_Agregados,
           xValor_Base_ICMS,
           xValor_Base_ICMS_Confirmado,
           xValor_IPI,
           xValor_IPI_Confirmado,
           xValor_Base_IPI,
           xValor_Base_IPI_Confirmado,
           xPeso_Total,
           xPeso_Bruto_Total,
           xPeso_Total_Confirmado,
           xValor_Total_Desconto,
           xValor_Total_Desconto_Confirmado,
           xValor_Base_ST,
           xValor_ST,
           xValor_Base_ST_Confirmado,
           xValor_ST_Confirmado,
           xValor_Total_Preco_Bruto,
           xValor_Total_Cubagem,
           xValor_Trib_Transparencia
           FROM T004
           WHERE T004_T003_Id=xT003_Id
             AND T004_Flag_Cancelado!='S';
    SELECT SUM(T145_Valor_Unitario)
      INTO xValor_Total_Servicos
      FROM T145
     WHERE T145_T003_Id=xT003_Id;           
    SELECT SUM(T138_Valor_Preco_Unitario*T138_Quantidade)
      INTO xValor_Total_Trocas
      FROM T138
     WHERE T138_T003_Id=xT003_Id;           
    UPDATE T003 SET T003_Valor_Total_Servicos=ifnull(xValor_Total_Servicos,0),
                    T003_Valor_Troca=ifnull(xValor_Total_Trocas,0),
                    T003_Valor_Total_Produtos=xValor_Total_Preco,
                    T003_Valor_Total_Produtos_Confirmado=xValor_Total_Preco_Confirmado,
                    T003_Valor_Total_Produtos_Sem_Desconto=xValor_Total_Preco_Sem_Desconto,
                    T003_Valor_Total_Produtos_Sem_Desconto_Confirmado=xValor_Total_Preco_Sem_Desconto_Confirmado,
                    T003_Valor_Total_Custo_Final=xValor_Total_Custo_Final,
                    T003_Valor_Total_Custo_Final_Confirmado=xValor_Total_Custo_Final_Confirmado,
                    T003_Valor_Total_Custo=xValor_Total_Custo,
                    T003_Valor_Total_Custo_Confirmado=xValor_Total_Custo_Confirmado,
                    T003_Valor_Total_Agregados=ifnull(xValor_Total_Agregados,0),
                    T003_Valor_Total_Base_ICMS=xValor_Base_ICMS,
                    T003_Valor_Total_Base_ICMS_Confirmado=xValor_Base_ICMS_Confirmado,
                    T003_Valor_Total_ICMS=xValor_ICMS,
                    T003_Valor_Total_ICMS_Confirmado=xValor_ICMS_Confirmado,
                    T003_Valor_Total_Base_IPI=xValor_Base_IPI,
                    T003_Valor_Total_Base_IPI_Confirmado=xValor_Base_IPI_Confirmado,
                    T003_Valor_Total_IPI=xValor_IPI,
                    T003_Valor_Total_IPI_Confirmado=xValor_IPI_Confirmado,
                    T003_Valor_ISS=if(T003_Aliquota_ISS>0,T003_Valor_Mao_Obra*(T003_Aliquota_ISS/100),0),
                    T003_Valor_Base_ST=xValor_Base_ST,
                    T003_Valor_ST=xValor_ST,
                    T003_Valor_Base_ST_Confirmado=xValor_Base_ST_Confirmado,
                    T003_Valor_Desconto=xValor_Total_Desconto,
                    T003_Valor_Desconto_Confirmado=xValor_Total_Desconto_Confirmado,
                    T003_Valor_ST_Confirmado=xValor_ST_Confirmado,
                    T003_Valor_Total=ifnull(T003_Valor_Total_Produtos,0)+
                                     ifnull(T003_Valor_Mao_Obra,0)+
                                     ifnull(if(xValor_Total_Preco_Bruto>0,0,T003_Valor_Total_Agregados),0)+
                                     ifnull(T003_Valor_Despesas_Acessorias,0)+
                                     ifnull(T003_Valor_Total_IPI,0)+
                                     ifnull(T003_Valor_ST,0)+
                                     ifnull(T003_Valor_Total_Servicos,0)-
                                     ifnull(T003_Valor_Desconto_Manual,0)-
                                     ifnull(T003_Valor_Troca,0)+
                                     ifnull(T003_Valor_Frete,0),
                    T003_Valor_Total_Confirmado=if(T003_Flag_Confirmar_Mao_Obra='S' or ifnull(xValor_Total_Preco_Confirmado,0)>0,
                                     ifnull(T003_Valor_Total_Produtos_Confirmado,0)+
                                     ifnull(T003_Valor_Mao_Obra,0)+
                                     ifnull(T003_Valor_Despesas_Acessorias,0)+
                                     ifnull(T003_Valor_Total_IPI_Confirmado,0)+
                                     ifnull(T003_Valor_ST_Confirmado,0)+
                                     ifnull(T003_Valor_Total_Servicos,0)-
                                     ifnull(T003_Valor_Desconto_Manual_Confirmado,0)-
                                     ifnull(T003_Valor_Troca,0)+
                                     ifnull(T003_Valor_Frete,0),0),
                    T003_IPV=if(T003_Valor_Total_Custo>0,T003_Valor_Total/T003_Valor_Total_Custo,0),
                    T003_IPV_Confirmado=if(T003_Valor_Total_Custo_Confirmado>0,T003_Valor_Total_Confirmado/T003_Valor_Total_Custo_Confirmado,0),
                    T003_IPV_Normal=ifnull(T003_IPV_Medio(xT003_Id,3),0),
                    T003_IPV_Normal_Confirmado=T003_IPV_Medio(xT003_Id,4),
                    T003_Peso_Total=ifnull(xPeso_Total,0),
                    T003_Peso_Bruto_Total=ifnull(xPeso_Bruto_Total,0),
                    T003_Peso_Total_Confirmado=ifnull(xPeso_Total_Confirmado,0),
                    T003_Total_Cubagem=IFNULL(xValor_Total_Cubagem,0),
                    T003_Valor_Total_Trib_Transparencia=xValor_Trib_Transparencia
              WHERE T003_Id=xT003_Id;
END */$$
DELIMITER ;

/* Procedure structure for procedure `T004_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T004_Gravar_Totalizacao`(xT004_Id int(11))
BEGIN

    DECLARE xT003_Id INT;

    DECLARE xPercentual_Desconto DECIMAL(30,20) DEFAULT 0;

    DECLARE xPercentual_Desconto_Bruto DECIMAL(30,20) DEFAULT 0;

    DECLARE xPercentual_Desconto_Confirmado DECIMAL(30,20) DEFAULT 0;

    DECLARE xMultiplicador_Despesa DECIMAL(10,6) DEFAULT 0;

    DECLARE xMultiplicador_Despesa_Confirmado DECIMAL(10,6) DEFAULT 0;

    DECLARE xMultiplicador_Despesas_Acessorias DECIMAL(20,10) DEFAULT 0;

    DECLARE xFlag_Revenda_Consumidor VARCHAR(1);

    DECLARE xD006_Flag_Forma_Calculo_COFINS varchar(1) default 'V';

    DECLARE xD006_Flag_Forma_Calculo_PIS varchar(1) default 'V';

    DECLARE xD006_Flag_Somar_Despesas_Base_ST ENUM('S','N') DEFAULT 'N';

    DECLARE xValor_Total_Agregados DECIMAL(10,2) DEFAULT 0;

    DECLARE xC004_Casas_Decimais_Preco int(2);

    DECLARE xC004_Id int(10);

    DECLARE xD006_Flag_Somar_IPI_Base_ICMS varchar(1);

    DECLARE xValor_Total_Frete DECIMAL(19,2) DEFAULT 0;

    DECLARE xMultiplicador_Frete DECIMAL(20,10) DEFAULT 0;

    DECLARE xTotal_Itens INT(5);

    DECLARE xC004_Flag_Rateio_Frete VARCHAR(1) DEFAULT '1';



      SELECT T004_T003_Id,

           D006_Flag_Forma_Calculo_COFINS,

           D006_Flag_Forma_Calculo_PIS,

           D006_Flag_Somar_IPI_Base_ICMS,

           D006_Flag_Somar_Despesas_Base_ST,

           T004_Percentual_Desconto/100,

           T004_Percentual_Desconto/100,

           T004_Percentual_Desconto_Bruto/100,

           T004_C004_Id

      INTO xT003_Id,

           xD006_Flag_Forma_Calculo_COFINS,

           xD006_Flag_Forma_Calculo_PIS,

           xD006_Flag_Somar_IPI_Base_ICMS,

           xD006_Flag_Somar_Despesas_Base_ST,

           xPercentual_Desconto,

           xPercentual_Desconto_Confirmado,

           xPercentual_Desconto_Bruto,

           xC004_Id

      FROM T004

      LEFT JOIN D006 ON D006_Id=T004_D006_Id

      WHERE T004_Id=xT004_Id;



      SELECT C004_Casas_Decimais_Preco,

      		 C004_Flag_Rateio_Frete

        INTO xC004_Casas_Decimais_Preco,

        	 xC004_Flag_Rateio_Frete

        FROM C004

       WHERE C004_Id=xC004_Id;



      if !(xPercentual_Desconto>0 OR xPercentual_Desconto<0) THEN

         SELECT T003_Percentual_Desconto/100,

                T003_Percentual_Desconto_Confirmado/100

           INTO xPercentual_Desconto,

                xPercentual_Desconto_Confirmado

         FROM T003

         LEFT JOIN C004 ON C004_Id=T003_C004_Id

         WHERE T003_Id=xT003_Id;

      END IF;



      SELECT SUM(T202_Valor_Unitario) INTO xValor_Total_Agregados FROM T202 WHERE T202_T004_Id=xT004_Id;



      IF xPercentual_Desconto IS NULL THEN

         set xPercentual_Desconto = 0;

      END IF;

      IF xPercentual_Desconto_Bruto IS NULL THEN

         set xPercentual_Desconto_Bruto = 0;

      END IF;

       IF xPercentual_Desconto_Confirmado IS NULL THEN

         set xPercentual_Desconto_Confirmado = 0;

      END IF;



      UPDATE T004

                SET T004_Valor_Desconto_Unitario = if(xPercentual_Desconto>0 or xPercentual_Desconto<0,T004_Valor_Preco_Original*xPercentual_Desconto,0),

                	  T004_Valor_Desconto_Unitario_Bruto = if(xPercentual_Desconto_Bruto>0 or xPercentual_Desconto_Bruto<0,T004_Valor_Preco_Original_Bruto*xPercentual_Desconto_Bruto,0),

                    T004_Valor_Desconto_Unitario_Confirmado = if(xPercentual_Desconto_Confirmado>0 or xPercentual_Desconto_Confirmado<0,T004_Valor_Preco_Original*xPercentual_Desconto_Confirmado,0),

                    T004_Valor_Total_Desconto = T004_Valor_Desconto_Unitario*T004_Quantidade,

                    T004_Valor_Total_Desconto_Confirmado = T004_Valor_Desconto_Unitario_Confirmado*T004_Quantidade_Confirmada,

                    T004_Valor_Preco_Unitario = round(T004_Valor_Preco_Original - T004_Valor_Desconto_Unitario,xC004_Casas_Decimais_Preco),

                    T004_Valor_Preco_Bruto = round(T004_Valor_Preco_Original_Bruto - T004_Valor_Desconto_Unitario_Bruto,xC004_Casas_Decimais_Preco),

                    T004_Valor_Preco_Unitario_Confirmado = round(T004_Valor_Preco_Original - T004_Valor_Desconto_Unitario_Confirmado,xC004_Casas_Decimais_Preco),

                    T004_Valor_Total_Preco = T004_Valor_Preco_Unitario*T004_Quantidade,

                    T004_Valor_Total_Preco_Confirmado = T004_Valor_Preco_Unitario_Confirmado * T004_Quantidade_Confirmada,

                    T004_Valor_Total_Preco_Sem_Desconto = T004_Valor_Preco_Original * T004_Quantidade,

                    T004_Valor_Total_Preco_Sem_Desconto_Confirmado = T004_Valor_Preco_Original * T004_Quantidade_Confirmada,

                    T004_Valor_Total_Agregados=xValor_Total_Agregados,

                    T004_Aliquota_PIS=if(T004_Flag_Isento_PIS='S',0,T004_Aliquota_PIS),

                    T004_Aliquota_COFINS=if(T004_Flag_Isento_COFINS='S',0,T004_Aliquota_COFINS),

                    T004_Valor_Base_PIS=if(T004_Flag_Isento_PIS='S',0,if(xD006_Flag_Forma_Calculo_PIS='L',if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado-T004_Valor_Total_Custo_Confirmado,T004_Valor_Total_Preco-T004_Valor_Total_Custo),if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado,T004_Valor_Total_Preco))),

                    T004_Valor_PIS=if(T004_Aliquota_PIS>0,T004_Valor_Base_PIS*(T004_Aliquota_PIS/100),0),

                    T004_Valor_Base_COFINS=if(T004_Flag_Isento_COFINS='S',0,if(xD006_Flag_Forma_Calculo_COFINS='L',if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado-T004_Valor_Total_Custo_Confirmado,T004_Valor_Total_Preco-T004_Valor_Total_Custo),if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado,T004_Valor_Total_Preco))),

                    T004_Valor_COFINS=if(T004_Aliquota_COFINS>0,T004_Valor_Base_COFINS*(T004_Aliquota_COFINS/100),0),

                    T004_Valor_Trib_Transparencia=IFNULL(T004_Valor_Total_Preco,0)*(IFNULL(T004_Percentual_Trib_Transparencia,0)/100)

                 WHERE T004_Id=xT004_Id;

                 SELECT (if (T003_Flag_Frete=1,T003_Valor_Frete,0)+T003_Valor_Despesas_Acessorias)/sum(T004_Valor_Preco_Unitario*T004_Quantidade),

                           (if (T003_Flag_Frete=1,T003_Valor_Frete,0)+T003_Valor_Despesas_Acessorias)/sum(T004_Valor_Preco_Unitario*T004_Quantidade_Confirmada),

                           T003_Flag_Revenda_Consumidor

                  INTO xMultiplicador_Despesa,

                        xMultiplicador_Despesa_Confirmado,

                        xFlag_Revenda_Consumidor

                  FROM T003

                  LEFT JOIN T004 ON T004_T003_Id=T003_Id

                 WHERE T003_Id=xT003_Id

                 GROUP BY T003_Id;

       IF xMultiplicador_Despesa IS NULL THEN

           set xMultiplicador_Despesa = 0;

       END IF;

       IF xMultiplicador_Despesa_Confirmado IS NULL THEN

           set xMultiplicador_Despesa_Confirmado = 0;

       END IF;

       

       	SELECT COUNT(*) INTO xTotal_Itens FROM T004 WHERE T004_T003_Id = xT003_Id;



		SELECT T003_Valor_Frete/SUM(T004_Valor_Preco_Unitario*T004_Quantidade),

				T003_Valor_Frete,

				T003_Valor_Despesas_Acessorias/SUM(T004_Valor_Preco_Unitario*T004_Quantidade)

		INTO xMultiplicador_Frete,

			xValor_Total_Frete,

			xMultiplicador_Despesas_Acessorias

		FROM T003

		LEFT JOIN T004 ON T004_T003_Id=T003_Id

		WHERE T003_Id=xT003_Id

		GROUP BY T003_Id;



		UPDATE T004 SET T004_Valor_Total_Despesas_Acessorias=T004_Valor_Total_Preco*xMultiplicador_Despesas_Acessorias,

				T004_Valor_Despesas_Acessorias_Unitario=T004_Valor_Total_Despesas_Acessorias/T004_Quantidade,

				T004_Valor_Frete_Total=IF(xC004_Flag_Rateio_Frete=1,T004_Valor_Total_Preco*xMultiplicador_Frete,xValor_Total_Frete/xTotal_Itens),

				T004_Valor_Frete_Unitario=T004_Valor_Frete_Total/T004_Quantidade

		WHERE T004_Id=xT004_Id;

       

		UPDATE T004

		SET T004_Valor_Total_Custo=T004_Valor_Custo_Unitario*T004_Quantidade,

                    T004_Valor_Total_Custo_Confirmado=T004_Valor_Custo_Unitario*T004_Quantidade_Confirmada,

                    T004_Peso_Total=T004_Peso_Unitario*T004_Quantidade,

                    T004_Peso_Bruto_Total=T004_Peso_Bruto*T004_Quantidade,

                    T004_Peso_Total_Confirmado=T004_Peso_Unitario*T004_Quantidade_Confirmada,

                    T004_Valor_Total_Despesas=(T004_Valor_Total_Preco*xMultiplicador_Despesa)+xValor_Total_Agregados,

                    T004_Valor_Total_Despesas_Confirmado=T004_Valor_Total_Preco_Confirmado*xMultiplicador_Despesa_Confirmado,

                    T004_Valor_Despesas_Unitario=T004_Valor_Total_Despesas/T004_Quantidade,

                    T004_Valor_Despesas_Unitario_Confirmado=T004_Valor_Total_Despesas_Confirmado/T004_Quantidade_Confirmada,

                    T004_Valor_Base_IPI=IF(T004_Aliquota_IPI>0,(T004_Valor_Total_Preco)*IF(T004_Percentual_Reducao_IPI>0,(T004_Percentual_Reducao_IPI/100),1),0),

                    T004_Valor_Base_IPI_Confirmado=IF(T004_Aliquota_IPI>0,(T004_Valor_Total_Preco_Confirmado)*IF(T004_Percentual_Reducao_IPI,(T004_Percentual_Reducao_IPI/100),1),0),

                    T004_Valor_IPI=T004_Valor_Base_IPI*(T004_Aliquota_IPI/100),

                    T004_Valor_IPI_Confirmado=T004_Valor_Base_IPI_Confirmado*(T004_Aliquota_IPI/100),

                    T004_Valor_Total_Custo_Final=(T004_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T004_Valor_Total_Despesas,0)+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T004_Valor_IPI,0)),

                    T004_Valor_Total_Custo_Final_Confirmado=(T004_Valor_Total_Preco_Confirmado+if(xD006_Flag_Somar_Despesas_Base_ST='S',T004_Valor_Total_Despesas_Confirmado,0)+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T004_Valor_IPI,0)),

                    T004_Valor_Custo_Final_Unitario=T004_Valor_Total_Custo_Final/T004_Quantidade,

                    T004_Valor_Custo_Final_Unitario_Confirmado=T004_Valor_Total_Custo_Final_Confirmado/T004_Quantidade_Confirmada,

                    T004_Valor_Base_ICMS=IF(T004_Aliquota_ICMS>0,T004_Valor_Total_Custo_Final*IF(T004_Percentual_Reducao_ICMS>0,(T004_Percentual_Reducao_ICMS/100),1),0),

                    T004_Valor_Base_ICMS_Confirmado=IF(T004_Aliquota_ICMS>0,T004_Valor_Total_Custo_Final_Confirmado*IF(T004_Percentual_Reducao_ICMS>0,(T004_Percentual_Reducao_ICMS/100),1),0),

                    T004_Valor_ICMS=T004_Valor_Base_ICMS*(T004_Aliquota_ICMS/100),

                    T004_Valor_ICMS_Confirmado=T004_Valor_Base_ICMS_Confirmado*(T004_Aliquota_ICMS/100),

                    T004_Valor_Base_ST=IF(T004_Flag_ST='S',(T004_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T004_Valor_Total_Despesas,0)+T004_Valor_IPI)*((T004_ST_VA/100)+1),0),

                    T004_Valor_ST=IF(T004_Flag_ST='S',((T004_Valor_Base_ST*IF(T004_Percentual_Reducao_ICMS_ST>0,(T004_Percentual_Reducao_ICMS_ST/100),1))*(T004_ST_ICMS_Interno/100))-((T004_Valor_Total_Custo_Final*IF(T004_Percentual_Reducao_ICMS>0,(T004_Percentual_Reducao_ICMS/100),1))*(T004_ICMS_Inter_Estadual/100)),0),

                    T004_Valor_ST=IF(T004_Valor_ST<0,0,T004_Valor_ST),

                    T004_Valor_Base_ST_Confirmado=IF(T004_Flag_ST='S',(T004_Valor_Total_Custo_Final_Confirmado+T004_Valor_Despesas_Unitario_Confirmado+T004_Valor_IPI_Confirmado)*((T004_ST_VA/100)+1),0),

                    T004_Valor_ST_Confirmado=IF(T004_Flag_ST='S',(T004_Valor_Base_ST_Confirmado*(T004_ST_ICMS_Interno/100))-((T004_Valor_Total_Custo_Final_Confirmado*IF(T004_Percentual_Reducao_ICMS>0,(T004_Percentual_Reducao_ICMS/100),1))*(T004_ICMS_Inter_Estadual/100)),0),

                    T004_Valor_ST_Confirmado=IF(T004_Valor_ST_Confirmado<0,0,T004_Valor_ST_Confirmado),

                    T004_IPV=T004_Valor_Preco_Unitario/T004_Valor_Custo_Unitario,

                    T004_Total_Cubagem = IFNULL(T004_Cubagem_Unitaria, 0) * IFNULL(T004_Quantidade,0),

                    T004_Valor_Trib_Transparencia=IFNULL(T004_Valor_Total_Preco,0)*(IFNULL(T004_Percentual_Trib_Transparencia,0)/100)

       WHERE T004_Id=xT004_Id;

       CALL T003_Gravar_Totalizacao(xT003_Id);

END */$$
DELIMITER ;

/* Procedure structure for procedure `T005_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T005_Gravar_Totalizacao`(xT005_Id int(11))
BEGIN

    DECLARE xValor_Total_Custo DECIMAL(10,2);

    DECLARE xValor_Total_Preco DECIMAL(10,2);

    DECLARE xValor_Total_Preco_Sem_Desconto DECIMAL(10,2);

    DECLARE xValor_Total_Custo_Final DECIMAL(10,2);

    DECLARE xValor_Total_Desconto DECIMAL(10,2);

    DECLARE xValor_ICMS DECIMAL(10,2);

    DECLARE xValor_Base_ICMS DECIMAL(10,2);

    DECLARE xValor_IPI DECIMAL(10,2);

    DECLARE xValor_Base_IPI DECIMAL(10,2);

    DECLARE xIPV DECIMAL(10,4);

    DECLARE xPeso_Total DECIMAL(10,3);

    DECLARE xValor_Base_ICMS_Substituicao DECIMAL(10,2) DEFAULT 0;

    DECLARE xValor_ICMS_Substituicao DECIMAL(10,2) DEFAULT 0;

    DECLARE xValor_ICMS_Substituicao_Retencao DECIMAL(10,2) DEFAULT 0;

    DECLARE xValor_Total_PIS decimal(10,2) DEFAULT 0;

    DECLARE xValor_Total_COFINS decimal(10,2) default 0;

    SELECT sum(T006_Valor_Total_Custo),

           sum(T006_Valor_Total_Preco),

           sum(T006_Valor_Total_Preco_Sem_Desconto),

           sum(T006_Valor_Total_Custo_Final),

           sum(T006_Valor_Total_Desconto),

           sum(T006_Valor_ICMS),

           sum(T006_Valor_Base_ICMS),

           sum(T006_Valor_IPI),

           sum(T006_Valor_Base_IPI),

           sum(T006_Peso_Total),

           sum(T006_Valor_Base_ICMS_Substituicao),

           sum(T006_Valor_ICMS_Substituicao),

           sum(T006_Valor_ICMS_Substituicao_Retencao),

           sum(T006_Valor_PIS),

           sum(T006_Valor_COFINS)

      INTO xValor_Total_Custo,

           xValor_Total_Preco,

           xValor_Total_Preco_Sem_Desconto,

           xValor_Total_Custo_Final,

           xValor_Total_Desconto,

           xValor_ICMS,

           xValor_Base_ICMS,

           xValor_IPI,

           xValor_Base_IPI,

           xPeso_Total,

           xValor_Base_ICMS_Substituicao,

           xValor_ICMS_Substituicao,

           xValor_ICMS_Substituicao_Retencao,

           xValor_Total_PIS,

           xValor_Total_COFINS

           FROM T006

           WHERE T006_T005_Id=xT005_Id and T006_Flag_Status!=3;

    UPDATE T005 SET T005_Peso_Total=ifnull(xPeso_Total,0),

                    T005_Valor_Total_Produtos=ifnull(xValor_Total_Preco,0),

                    T005_Valor_Total_Produtos_Sem_Desconto=ifnull(xValor_Total_Preco_Sem_Desconto,0),

                    T005_Valor_Total_Custo_Final=ifnull(xValor_Total_Custo_Final,0)-T005_Valor_Desconto,

                    T005_Valor_Total_Custo=ifnull(xValor_Total_Custo,0),

                    T005_Valor_Total_Base_ICMS=ifnull(xValor_Base_ICMS,0),

                    T005_Valor_Total_ICMS=ifnull(xValor_ICMS,0),

                    T005_Valor_Total_Base_IPI=ifnull(xValor_Base_IPI,0),

                    T005_Valor_Total_IPI=ifnull(xValor_IPI,0),

                    T005_Valor_Total_PIS=ifnull(xValor_Total_PIS,0),

                    T005_Valor_Total_COFINS=ifnull(xValor_Total_COFINS,0),

                    T005_Valor_ISS=if(T005_Aliquota_ISS>0,T005_Valor_Mao_Obra*(T005_Aliquota_ISS/100),0),

                    T005_Valor_Base_ICMS_Substituicao=ifnull(xValor_Base_ICMS_Substituicao,0),

                    T005_Valor_ICMS_Substituicao=ifnull(xValor_ICMS_Substituicao,0),

                    T005_Valor_ICMS_Substituicao_Retencao=ifnull(xValor_ICMS_Substituicao_Retencao,0),

                    T005_Valor_Total=ifnull(T005_Valor_Total_Produtos,0)+

                                     ifnull(T005_Valor_Mao_Obra,0)+

                                     ifnull(T005_Valor_Despesas_Acessorias,0)+

                                     ifnull(T005_Valor_ICMS_Substituicao_Retencao,0)+

                                     ifnull(T005_Valor_Total_IPI,0)+

                                     ifnull(T005_Valor_Frete,0),

                    T005_IPV=T005_IPV_Medio(xT005_Id,1),

                    T005_IPV_Normal=T005_IPV_Medio(xT005_Id,2)

              WHERE T005_Id=xT005_Id;

END */$$
DELIMITER ;

/* Procedure structure for procedure `T005_Gravar_Totalizacao_3` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T005_Gravar_Totalizacao_3`(xT005_Id int(11))
BEGIN
    DECLARE xValor_Total_Custo DECIMAL(10,2);
    DECLARE xValor_Total_Preco DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final DECIMAL(10,2);
    DECLARE xValor_Total_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Servicos DECIMAL(10,2);
    DECLARE xValor_Total_Trocas DECIMAL(10,2);
    DECLARE xValor_ICMS DECIMAL(10,2);
    DECLARE xValor_Base_ICMS DECIMAL(10,2);
    DECLARE xValor_Total_Agregados DECIMAL(10,2);
    DECLARE xValor_IPI DECIMAL(10,2);
    DECLARE xValor_Base_IPI DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Bruto DECIMAL(10,2);
    DECLARE xIPV DECIMAL(10,4);
    DECLARE xPeso_Total DECIMAL(10,3);
    DECLARE xPeso_Bruto_Total DECIMAL(10,3);
    DECLARE xValor_Base_ICMS_Substituicao DECIMAL(10,2) DEFAULT 0;
    DECLARE xValor_ICMS_Substituicao DECIMAL(10,2) DEFAULT 0;
    DECLARE xValor_ICMS_Substituicao_Retencao DECIMAL(10,2) DEFAULT 0;
    DECLARE xValor_Total_PIS decimal(10,2) DEFAULT 0;
    DECLARE xValor_Total_COFINS decimal(10,2) default 0;
    DECLARE xValor_Total_Comissao decimal(14,5) default 0;
    DECLARE xValor_Total_Cubagem DECIMAL(10,3) default 0;
    DECLARE xValor_Trib_Transparencia DECIMAL(15,2) DEFAULT 0;
    SELECT sum(T006_Valor_Total_Custo),
           sum(T006_Valor_Total_Preco),
           sum(T006_Valor_Total_Preco_Sem_Desconto),
           sum(T006_Valor_Total_Custo_Final),
           sum(T006_Valor_Total_Desconto),
           sum(T006_Valor_ICMS),
           sum(T006_Valor_Base_ICMS),
           sum(T006_Valor_Total_Agregados),
           sum(T006_Valor_IPI),
           sum(T006_Valor_Base_IPI),
           sum(T006_Peso_Total),
           sum(T006_Peso_Bruto_Total),
           sum(T006_Valor_Base_ICMS_Substituicao),
           sum(T006_Valor_ICMS_Substituicao),
           sum(T006_Valor_ICMS_Substituicao_Retencao),
           sum(T006_Valor_PIS),
           sum(T006_Valor_COFINS),
           sum(T006_Valor_Preco_Bruto),
           sum(T006_Valor_Comissao),
           sum(T006_Total_Cubagem),
           sum(T006_Valor_Trib_Transparencia)
      INTO xValor_Total_Custo,
           xValor_Total_Preco,
           xValor_Total_Preco_Sem_Desconto,
           xValor_Total_Custo_Final,
           xValor_Total_Desconto,
           xValor_ICMS,
           xValor_Base_ICMS,
           xValor_Total_Agregados,
           xValor_IPI,
           xValor_Base_IPI,
           xPeso_Total,
           xPeso_Bruto_Total,
           xValor_Base_ICMS_Substituicao,
           xValor_ICMS_Substituicao,
           xValor_ICMS_Substituicao_Retencao,
           xValor_Total_PIS,
           xValor_Total_COFINS,
           xValor_Total_Preco_Bruto,
           xValor_Total_Comissao,
           xValor_Total_Cubagem,
           xValor_Trib_Transparencia
           FROM T006
           WHERE T006_T005_Id=xT005_Id and T006_Flag_Status!=3;
    SELECT SUM(T147_Valor_Unitario)
      INTO xValor_Total_Servicos
      FROM T147
     WHERE T147_T005_Id=xT005_Id;           
    SELECT SUM(T138_Valor_Preco_Unitario*T138_Quantidade)
      INTO xValor_Total_Trocas
      FROM T138
     WHERE T138_T005_Id=xT005_Id;           
    UPDATE T005 SET T005_Peso_Total=ifnull(xPeso_Total,0),
                    T005_Peso_Bruto_Total=ifnull(xPeso_Bruto_Total,0),
                    T005_Valor_Total_Servicos=ifnull(xValor_Total_Servicos,0),
                    T005_Valor_Troca=ifnull(xValor_Total_Trocas,0),
                    T005_Valor_Total_Agregados=ifnull(xValor_Total_Agregados,0),
                    T005_Valor_Total_Produtos=ifnull(xValor_Total_Preco,0),
                    T005_Valor_Total_Produtos_Sem_Desconto=ifnull(xValor_Total_Preco_Sem_Desconto,0),
                    T005_Valor_Total_Custo_Final=ifnull(xValor_Total_Custo_Final,0)-T005_Valor_Desconto,
                    T005_Valor_Total_Custo=ifnull(xValor_Total_Custo,0),
                    T005_Valor_Total_Base_ICMS=ifnull(xValor_Base_ICMS,0),
                    T005_Valor_Total_ICMS=ifnull(xValor_ICMS,0),
                    T005_Valor_Total_Base_IPI=ifnull(xValor_Base_IPI,0),
                    T005_Valor_Total_IPI=ifnull(xValor_IPI,0),
                    T005_Valor_Total_PIS=ifnull(xValor_Total_PIS,0),
                    T005_Valor_Total_COFINS=ifnull(xValor_Total_COFINS,0),
                    T005_Valor_ISS=if(T005_Aliquota_ISS>0,T005_Valor_Mao_Obra*(T005_Aliquota_ISS/100),0),
                    T005_Valor_Base_ICMS_Substituicao=ifnull(xValor_Base_ICMS_Substituicao,0),
                    T005_Valor_ICMS_Substituicao=ifnull(xValor_ICMS_Substituicao,0),
                    T005_Valor_ICMS_Substituicao_Retencao=ifnull(xValor_ICMS_Substituicao_Retencao,0),
                    T005_Valor_Total=if(T005_Flag_Status=8,0,
                                     ifnull(round(T005_Valor_Total_Produtos_Sem_Desconto,2),0)+
                                     ifnull(T005_Valor_Mao_Obra,0)+
                                     ifnull(if(xValor_Total_Preco_Bruto>0,0,T005_Valor_Total_Agregados),0)+
                                     ifnull(T005_Valor_Despesas_Acessorias,0)+
                                     ifnull(round(T005_Valor_ICMS_Substituicao_Retencao,2),0)+
                                     ifnull(round(T005_Valor_Total_IPI,2),0)+
                                     ifnull(T005_Valor_Total_Servicos,0)-
                                     ifnull(T005_Valor_Desconto_Manual,0)-
                                     ifnull(T005_Valor_Troca,0)+
                                     ifnull(if(xValor_Total_Preco_Bruto>0,0,T005_Valor_Frete),0)),
                    T005_IPV=ifnull(T005_IPV_Medio(xT005_Id,1),0),
                    T005_IPV_Normal=ifnull(T005_IPV_Medio(xT005_Id,2),0),
                    T005_Valor_Total_Comissao=ifnull(xValor_Total_Comissao,0),
                    T005_Total_Cubagem=IFNULL(xValor_Total_Cubagem,0),
                    T005_Valor_Total_Trib_Transparencia=xValor_Trib_Transparencia
              WHERE T005_Id=xT005_Id;

    UPDATE T005 SET T005_Peso_Liquido=ifnull(xPeso_Total,0),
                    T005_Peso_Bruto=ifnull(xPeso_Bruto_Total,0)
                WHERE T005_Id=xT005_Id AND T005_Flag_Totalizar_Peso = 'S';
END */$$
DELIMITER ;

/* Procedure structure for procedure `T006_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T006_Gravar_Totalizacao`(xT006_Id int(11))
BEGIN

    DECLARE xT005_Id int;

    DECLARE xPercentual_Desconto DECIMAL(20,10) DEFAULT 0;

    DECLARE xPercentual_Desconto_Bruto DECIMAL(20,10) DEFAULT 0;

    DECLARE xMultiplicador_Despesa DECIMAL(20,10) DEFAULT 0;

    DECLARE xMultiplicador_Despesas_Acessorias DECIMAL(20,10) DEFAULT 0;

    DECLARE xMultiplicador_Frete DECIMAL(20,10) DEFAULT 0;

    DECLARE xFlag_Revenda_Consumidor VARCHAR(1);

    DECLARE xFlag_Devolucao VARCHAR(1);

    DECLARE xFlag_Tipo_Devolucao VARCHAR(10);

    DECLARE xValor_Total_Frete DECIMAL(19,2) DEFAULT 0;

    DECLARE xValor_Total_Despesas_Acessorias DECIMAL(10,2) DEFAULT 0;

    DECLARE xValor_Total_Agregados DECIMAL(10,2) DEFAULT 0;

    DECLARE xValor_Total_Desconto DECIMAL(10,2) DEFAULT 0;

    DECLARE xFlag_ST VARCHAR(3);

    DECLARE xFlag_Venda_Compra_Outros VARCHAR(1);

    DECLARE xAliquota_ICMS_1 DECIMAL(5,2);



    DECLARE xT134_Id int(10) default '0';

    DECLARE xT134_Reducao_Base_ICMS decimal(10,2) default '0';



    DECLARE xD006_Flag_Somar_IPI_Base_ICMS ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Somar_Despesas_Base_IPI ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Somar_Despesas_Base_ST ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Isento_PIS ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Situacao_Tributaria_PIS VARCHAR(2) default '01';

    DECLARE xD006_Flag_Isento_COFINS ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Situacao_Tributaria_COFINS VARCHAR(2) default '01';

    DECLARE xD059_Codigo_ST varchar(3);

    DECLARE xC004_Percentual_PIS decimal(6,2) DEFAULT 0;

    DECLARE xC004_Percentual_COFINS decimal(6,2) DEFAULT 0;

    DECLARE xC004_Flag_Rateio_Frete VARCHAR(1) DEFAULT '1';

    DECLARE xTotal_Itens INT(5);

    DECLARE xD049_Flag_Nacional_Importado varchar(1);



    DECLARE xD006_Flag_Forma_Calculo_COFINS varchar(1) default 'V';

    DECLARE xD006_Flag_Forma_Calculo_PIS varchar(1) default 'V';



    DECLARE xC004_Casas_Decimais_Preco int(2);

    DECLARE xC004_Id int(10);

    

    DECLARE xT185_Qtd_Separado DECIMAL(20,2) DEFAULT 0;

    

    -- caso esteja utilizando a tabela T185, a quantidade de itens separados tem que ser pega desta tabela

    SELECT COUNT(T185_Qtd_Separado) INTO xT185_Qtd_Separado FROM T185 WHERE T185_T006_Id = xT006_Id;

    IF xT185_Qtd_Separado > 0 THEN

	SELECT SUM(T185_Qtd_Separado) INTO xT185_Qtd_Separado FROM T185 WHERE T185_T006_Id = xT006_Id;

	UPDATE T006 SET T006_Quantidade_Separacao = xT185_Qtd_Separado WHERE T006_Id = xT006_Id;

    END IF;



    SELECT ifnull(SUM(T204_Valor_Unitario),0) INTO xValor_Total_Agregados FROM T204 WHERE T204_T006_Id=xT006_Id;

    

    -- GRAVA A CFOP POR ITEM PARA OS QUE AINDA NAO TEM CFOP

    update T006 left join T005 on T005_Id=T006_T005_Id set T006_D006_Id=T005_D006_Id where T006_Id=xT006_Id and T006_D006_Id is null;



    SELECT T006_T005_Id,

           D006_Flag_Venda_Compra_Outros,

           D049_Flag_Nacional_Importado,

           D006_Flag_Somar_IPI_Base_ICMS,

           D006_Flag_Somar_Despesas_Base_IPI,

           D006_Flag_Somar_Despesas_Base_ST,

           D006_Flag_Forma_Calculo_COFINS,

           D006_Flag_Forma_Calculo_PIS,

           T006_C004_Id,

           T134_Reducao_Base_ICMS,

           T134_Id,

           T006_Percentual_Desconto_Bruto/100

      INTO xT005_Id,

           xFlag_Venda_Compra_Outros,

           xD049_Flag_Nacional_Importado,

           xD006_Flag_Somar_IPI_Base_ICMS,

           xD006_Flag_Somar_Despesas_Base_IPI,

           xD006_Flag_Somar_Despesas_Base_ST,

           xD006_Flag_Forma_Calculo_COFINS,

           xD006_Flag_Forma_Calculo_PIS,

           xC004_Id,

           xT134_Reducao_Base_ICMS,

           xT134_Id,

           xPercentual_Desconto_Bruto

      FROM T006

      LEFT JOIN T005 ON T005_Id=T006_T005_Id

      LEFT JOIN D006 ON D006_Id=T006_D006_Id

      LEFT JOIN T134 ON T134_Id=T005_T134_Id

      LEFT JOIN D024 ON D024_Id=T005_D024_Id

      LEFT JOIN D020 ON D020_Id=D024_D020_Id

      LEFT JOIN D009 ON D009_Id=T006_D009_Id

      LEFT JOIN D049 ON D049_Id=D009_D049_Id

      LEFT JOIN D001 ON D001_Id=D049_D001_Id

     WHERE T006_Id=xT006_Id

     LIMIT 1;



     SELECT COUNT(*) INTO xTotal_Itens FROM T006 WHERE T006_T005_Id = xT005_Id;

     

     SELECT C004_Casas_Decimais_Preco,

             C004_Flag_Rateio_Frete

        INTO xC004_Casas_Decimais_Preco,

             xC004_Flag_Rateio_Frete

        FROM C004

       WHERE C004_Id=xC004_Id;



    SELECT T005_Percentual_Desconto/100,

           T005_Flag_Devolucao,

           T005_Flag_Tipo_Devolucao

      INTO xPercentual_Desconto,

           xFlag_Devolucao,

           xFlag_Tipo_Devolucao

      FROM T005

      LEFT JOIN C004 ON C004_Id=T005_C004_Id

     WHERE T005_Id=xT005_Id;

     

    IF xPercentual_Desconto IS NULL THEN

       set xPercentual_Desconto = 0;

    END IF;   

    

    UPDATE T006 SET T006_Valor_Desconto_Unitario = if(xPercentual_Desconto>0,T006_Valor_Preco_Sem_Desconto_Unitario*xPercentual_Desconto,0),

    				T006_Valor_Desconto_Unitario_Bruto = if(xPercentual_Desconto_Bruto>0 or xPercentual_Desconto_Bruto<0,T006_Valor_Preco_Original_Bruto*xPercentual_Desconto_Bruto,0),

                    T006_Valor_Total_Desconto = T006_Valor_Desconto_Unitario*T006_Quantidade,

                    T006_Valor_Preco_Unitario = round(T006_Valor_Preco_Sem_Desconto_Unitario - T006_Valor_Desconto_Unitario,xC004_Casas_Decimais_Preco),

                    T006_Valor_Total_Preco = T006_Valor_Preco_Unitario*T006_Quantidade,

                    T006_Valor_Total_Preco_Sem_Desconto = T006_Valor_Preco_Sem_Desconto_Unitario * T006_Quantidade,

                    T006_Valor_Preco_Bruto = round(T006_Valor_Preco_Original_Bruto - T006_Valor_Desconto_Unitario_Bruto,xC004_Casas_Decimais_Preco)

              WHERE T006_Id=xT006_Id;



    IF xFlag_Devolucao='S' AND xFlag_Tipo_Devolucao='EMITIDA' THEN

       UPDATE T006 SET T006_Valor_Total_Frete=T006_Valor_Frete_Unitario*T006_Quantidade,

                       T006_Valor_Total_Despesas_Acessorias=T006_Valor_Despesas_Acessorias_Unitario*T006_Quantidade,

                       T006_Valor_Total_Desconto=T006_Valor_Desconto_Unitario*T006_Quantidade

              WHERE T006_T005_Id=xT005_Id;

       SELECT SUM(T006_Valor_Total_Frete),

              SUM(T006_Valor_Total_Despesas_Acessorias),

              SUM(T006_Valor_Total_Desconto)

         INTO xValor_Total_Frete,

              xValor_Total_Despesas_Acessorias,

              xValor_Total_Desconto

         FROM T006

         WHERE T006_T005_Id=xT005_Id

         GROUP BY T006_T005_Id;

         UPDATE T005

         SET T005_Valor_Frete=xValor_Total_Frete,

              T005_Valor_Despesas_Acessorias=xValor_Total_Despesas_Acessorias

         WHERE T005_Id=xT005_Id;

    ELSE

           SELECT T005_Valor_Frete/sum(T006_Valor_Preco_Unitario*T006_Quantidade),

                  T005_Valor_Frete,

                  T005_Valor_Despesas_Acessorias/sum(T006_Valor_Preco_Unitario*T006_Quantidade)

           INTO xMultiplicador_Frete,

                xValor_Total_Frete,

                xMultiplicador_Despesas_Acessorias

         FROM T005

         LEFT JOIN T006 ON T006_T005_Id=T005_Id

         WHERE T005_Id=xT005_Id

         GROUP BY T005_Id;

        UPDATE T006 SET T006_Valor_Total_Despesas_Acessorias=T006_Valor_Total_Preco*xMultiplicador_Despesas_Acessorias,

                        T006_Valor_Despesas_Acessorias_Unitario=T006_Valor_Total_Despesas_Acessorias/T006_Quantidade,

                        T006_Valor_Total_Frete=IF(xC004_Flag_Rateio_Frete=1,T006_Valor_Total_Preco*xMultiplicador_Frete,xValor_Total_Frete/xTotal_Itens),

                        T006_Valor_Frete_Unitario=T006_Valor_Total_Frete/T006_Quantidade

                  WHERE T006_Id=xT006_Id;

    END IF;

    SELECT (T005_Valor_Frete+T005_Valor_Despesas_Acessorias)/sum(T006_Valor_Preco_Unitario*T006_Quantidade),

           T005_Flag_Revenda_Consumidor

      INTO

        xMultiplicador_Despesa,

        xFlag_Revenda_Consumidor

      FROM T005

      LEFT JOIN T006 ON T006_T005_Id=T005_Id

     WHERE T005_Id=xT005_Id

     GROUP BY T005_Id;

    IF xMultiplicador_Despesa IS NULL THEN

       set xMultiplicador_Despesa = 0;

    END IF;

    UPDATE T006 SET T006_Valor_Total_Custo = T006_Valor_Custo_Unitario*T006_Quantidade,

                    T006_Peso_Total = T006_Peso_Unitario*T006_Quantidade,

                    T006_Peso_Bruto_Total = T006_Peso_Bruto*T006_Quantidade,

                    T006_Valor_Total_Despesas=(T006_Valor_Total_Preco*xMultiplicador_Despesa)+xValor_Total_Agregados,

                    T006_Valor_Despesas_Unitario=T006_Valor_Total_Despesas/T006_Quantidade,

                    T006_Valor_Total_Agregados=xValor_Total_Agregados,

                    T006_Valor_Base_IPI=If(T006_Aliquota_IPI>0,(T006_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_IPI='S',T006_Valor_Total_Frete+T006_Valor_Total_Despesas_Acessorias,0))*If(T006_Percentual_Reducao_IPI>0,(T006_Percentual_Reducao_IPI/100),1),0),

                    T006_Valor_IPI=T006_Valor_Base_IPI*(T006_Aliquota_IPI/100),

                    T006_Valor_Total_Custo_Final=(T006_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T006_Valor_Total_Despesas,0)+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T006_Valor_IPI,0)),

                    T006_Valor_Custo_Final_Unitario=T006_Valor_Total_Custo_Final/T006_Quantidade,

                    T006_Valor_Base_ICMS=If(T006_Aliquota_ICMS>0,T006_Valor_Total_Custo_Final*if(T006_Percentual_Reducao_ICMS>0,(T006_Percentual_Reducao_ICMS/100),1),0),

                    T006_Valor_ICMS=T006_Valor_Base_ICMS*(T006_Aliquota_ICMS/100),

                    T006_IPV=T006_Valor_Preco_Unitario/T006_Valor_Custo_Unitario,

                    T006_Valor_Base_ICMS_Substituicao=IF(T006_Flag_ST='S',(T006_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T006_Valor_Total_Despesas,0)+T006_Valor_IPI)*((T006_ST_VA/100)+1),0),

                    T006_Valor_ICMS_Substituicao=(T006_Valor_Base_ICMS_Substituicao*(T006_ST_ICMS_Interno/100)),

                    T006_Valor_ICMS_Substituicao_Retencao=((T006_Valor_Base_ICMS_Substituicao*if(T006_Percentual_Reducao_ICMS_ST>0,(T006_Percentual_Reducao_ICMS_ST/100),1))*(T006_ST_ICMS_Interno/100))-((T006_Valor_Total_Custo_Final*if(T006_Percentual_Reducao_ICMS>0,(T006_Percentual_Reducao_ICMS/100),1))*(T006_ICMS_Inter_Estadual/100)),

                    T006_Valor_ICMS_Substituicao_Retencao=IF(T006_Valor_ICMS_Substituicao_Retencao<0,0,T006_Valor_ICMS_Substituicao_Retencao),

                    T006_Valor_Base_PIS=if(T006_Flag_Isento_PIS='S',0,if(xD006_Flag_Forma_Calculo_PIS='L',T006_Valor_Total_Preco-T006_Valor_Total_Custo,T006_Valor_Total_Preco)),

                    T006_Aliquota_PIS=if(T006_Flag_Isento_PIS='S',0,T006_Aliquota_PIS),

                    T006_Valor_PIS=if(T006_Aliquota_PIS>0,T006_Valor_Base_PIS*(T006_Aliquota_PIS/100),0),

                    T006_Valor_Base_COFINS=if(T006_Flag_Isento_COFINS='S',0,if(xD006_Flag_Forma_Calculo_COFINS='L',T006_Valor_Total_Preco-T006_Valor_Total_Custo,T006_Valor_Total_Preco)),

                    T006_Aliquota_COFINS=if(T006_Flag_Isento_COFINS='S',0,T006_Aliquota_COFINS),

                    T006_Valor_COFINS=if(T006_Aliquota_COFINS>0,T006_Valor_Base_COFINS*(T006_Aliquota_COFINS/100),0),

                    T006_Valor_ICMS_Credito=if(xT134_Id<=0 or xT134_Id='' or ifnull(xT134_Id,0)<=0,T006_Valor_ICMS_Credito,If(T006_Aliquota_ICMS_Credito>0,(T006_Valor_Total_Custo_Final+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T006_Valor_IPI,0))-((T006_Valor_Total_Custo_Final+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T006_Valor_IPI,0))*if(xT134_Reducao_Base_ICMS>0,(xT134_Reducao_Base_ICMS/100),1)),0)*(T006_Aliquota_ICMS_Credito/100)),

                    T006_Total_Cubagem = IFNULL(T006_Cubagem_Unitaria,0) * IFNULL(T006_Quantidade,0),

                    T006_Valor_Trib_Transparencia=IFNULL(T006_Valor_Total_Preco,0)*(IFNULL(T006_Percentual_Trib_Transparencia,0)/100)

              WHERE T006_Id=xT006_Id;

    CALL T005_Gravar_Totalizacao_3(xT005_Id);

END */$$
DELIMITER ;

/* Procedure structure for procedure `T007_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T007_Gravar_Totalizacao`(xT007_Id int(11))
BEGIN

    DECLARE xValor_Total_Custo DECIMAL(20,2);

    DECLARE xValor_Total_Preco DECIMAL(20,2);

    DECLARE xValor_Total_Custo_Final DECIMAL(20,2);

    DECLARE xValor_Total_Produtos DECIMAL(20,2);

    DECLARE xValor_Total_Produtos_Sem_Desconto DECIMAL(20,2);

    DECLARE xValor_Base_ICMS DECIMAL(20,2);

    DECLARE xValor_Base_ICMS_Sem_Reducao DECIMAL(20,2);

    DECLARE xValor_Base_ICMS_Diferido DECIMAL(20,2);

    DECLARE xValor_ICMS DECIMAL(20,2);

    DECLARE xValor_Base_IPI DECIMAL(20,2);

    DECLARE xValor_IPI DECIMAL(20,2);

    DECLARE xValor_Total_II DECIMAL(19,2) DEFAULT 0;

    DECLARE xValor_Base_ICMS_Impresso DECIMAL(20,2);

    DECLARE xValor_Base_ICMS_Substituicao DECIMAL(20,2) DEFAULT 0;

    DECLARE xValor_ICMS_Substituicao DECIMAL(20,2) DEFAULT 0;

    DECLARE xValor_ICMS_Substituicao_Retencao DECIMAL(20,2) DEFAULT 0;

    DECLARE xValor_PIS DECIMAL(10,2) DEFAULT 0;

    DECLARE xValor_COFINS DECIMAL(10,2) DEFAULT 0;

    DECLARE xPeso_Total DECIMAL(20,3) DEFAULT 0;

    DECLARE xValor_Total_Desconto DECIMAL(15,2) DEFAULT 0;

    DECLARE xValor_Trib_Transparencia DECIMAL(15,6) DEFAULT 0;

    SELECT sum(T008_Valor_Total_Custo),

           sum(T008_Valor_Total_Preco),

           sum(T008_Valor_Total_Preco),

           sum(T008_Valor_Total_Preco_Sem_Desconto),

           sum(T008_Valor_Total_Custo_Final),

           sum(round(T008_Valor_Base_ICMS,2)),

           sum(T008_Valor_Base_ICMS_Sem_Reducao),

           sum(T008_Valor_Base_ICMS_Diferido),

           sum(T008_Valor_ICMS),

           sum(T008_Valor_Base_IPI),

           sum(T008_Valor_IPI),

           sum(T008_Valor_Base_ICMS_Impresso),

           sum(T008_Valor_Base_ICMS_Substituicao),

           sum(T008_Valor_ICMS_Substituicao),

           sum(T008_Valor_ICMS_Substituicao_Retencao),

           sum(T008_Peso_Total),

           sum(T008_Valor_Total_Imposto_Importacao),

           sum(T008_Valor_COFINS),

           sum(T008_Valor_PIS),

           sum(T008_Valor_Total_Desconto),

           sum(T008_Valor_Trib_Transparencia)

      INTO xValor_Total_Custo,

           xValor_Total_Produtos,

           xValor_Total_Preco,

           xValor_Total_Produtos_Sem_Desconto,

           xValor_Total_Custo_Final,

           xValor_Base_ICMS,

           xValor_Base_ICMS_Sem_Reducao,

           xValor_Base_ICMS_Diferido,

           xValor_ICMS,

           xValor_Base_IPI,

           xValor_IPI,

           xValor_Base_ICMS_Impresso,

           xValor_Base_ICMS_Substituicao,

           xValor_ICMS_Substituicao,

           xValor_ICMS_Substituicao_Retencao,

           xPeso_Total,

           xValor_Total_II,

           xValor_COFINS,

           xValor_PIS,

           xValor_Total_Desconto,

           xValor_Trib_Transparencia

           FROM T008

           WHERE T008_T007_Id=xT007_Id;

    UPDATE T007 SET T007_Valor_Total_Custo=xValor_Total_Custo,

                    T007_Valor_Total_Produtos=xValor_Total_Produtos,

                    T007_Valor_Total_Produtos_Sem_Desconto = xValor_Total_Produtos_Sem_Desconto,

                    T007_Valor_Total_Preco=xValor_Total_Preco,

                    T007_Valor_Total_Custo_Final=xValor_Total_Custo_Final-T007_Valor_Desconto,

                    T007_Valor_Total_Base_ICMS_Sem_Reducao=xValor_Base_ICMS_Sem_Reducao,

                    T007_Valor_Total_Base_ICMS=xValor_Base_ICMS,

                    T007_Valor_Total_Base_ICMS_Diferido=xValor_Base_ICMS_Diferido,

                    T007_Valor_Total_Base_ICMS_Impresso=xValor_Base_ICMS_Impresso,

                    T007_Valor_Total_ICMS=xValor_ICMS,

                    T007_Valor_Total_Base_IPI=xValor_Base_IPI,

                    T007_Valor_Total_IPI=xValor_IPI,

                    T007_Valor_Total_Imposto_Importacao=xValor_Total_II,

                    T007_Valor_ISS=if(T007_Aliquota_ISS>0,T007_Valor_Mao_Obra*(T007_Aliquota_ISS/100),0),

                    T007_IPV=T007_IPV_Medio(xT007_Id,1),

                    T007_Total_Peso=xPeso_Total,

                    T007_IPV_sem_icms=T007_IPV_Medio(xT007_Id,2),

                    T007_Valor_Base_ICMS_Substituicao=xValor_Base_ICMS_Substituicao,

                    T007_Valor_ICMS_Substituicao=xValor_ICMS_Substituicao,

                    T007_Valor_ICMS_Substituicao_Retencao=xValor_ICMS_Substituicao_Retencao,

                    T007_Valor_Total_COFINS=xValor_COFINS,

                    T007_Valor_Total_PIS=xValor_PIS,

                    T007_Valor_Desconto=xValor_Total_Desconto,

                    T007_Valor_Total_Trib_Transparencia=xValor_Trib_Transparencia,

                    T007_Valor_Total=T007_Valor_Total_Produtos+

                                     T007_Valor_Mao_Obra+

                                     T007_Valor_Despesas_Acessorias+

                                     T007_Valor_ICMS_Substituicao_Retencao+

                                     T007_Valor_Total_IPI+

                                     T007_Valor_Seguro+

                                     T007_Valor_Frete-

                                     T007_Valor_Desconto

              WHERE T007_Id=xT007_Id and T007_Flag_Calcular='S';

    -- SO FAZ OS CALCULOS DA NOTA SE FOR UMA NOTA NORMAL (T007_Flag_Finalidade_NFe=1)

END */$$
DELIMITER ;

/* Procedure structure for procedure `T007_Gravar_Totalizacao_3` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T007_Gravar_Totalizacao_3`(xT007_Id int(11))
BEGIN

    DECLARE xValor_Total_Custo DECIMAL(20,2);

    DECLARE xValor_Total_Preco DECIMAL(20,2);

    DECLARE xValor_Total_Custo_Final DECIMAL(20,2);

    DECLARE xValor_Total_Produtos DECIMAL(20,2);

    DECLARE xValor_Total_Servicos DECIMAL(20,2);

    DECLARE xValor_Total_Produtos_Sem_Desconto DECIMAL(20,2);

    DECLARE xValor_Base_ICMS DECIMAL(20,2);

    DECLARE xValor_Base_ICMS_Sem_Reducao DECIMAL(20,2);

    DECLARE xValor_Base_ICMS_Diferido DECIMAL(20,2);

    DECLARE xValor_ICMS DECIMAL(20,2);

    DECLARE xValor_Base_IPI DECIMAL(20,2);

    DECLARE xValor_IPI DECIMAL(20,2);

    DECLARE xValor_Total_II DECIMAL(19,2) DEFAULT 0;

    DECLARE xValor_Base_ICMS_Impresso DECIMAL(20,2);

    DECLARE xValor_Base_ICMS_Substituicao DECIMAL(20,2) DEFAULT 0;

    DECLARE xValor_ICMS_Substituicao DECIMAL(20,2) DEFAULT 0;

    DECLARE xValor_ICMS_Substituicao_Retencao DECIMAL(20,2) DEFAULT 0;

    DECLARE xValor_PIS DECIMAL(10,2) DEFAULT 0;

    DECLARE xValor_COFINS DECIMAL(10,2) DEFAULT 0;

    DECLARE xPeso_Total DECIMAL(20,3) DEFAULT 0;

    DECLARE xPeso_Total_Bruto DECIMAL(20,3) DEFAULT 0;

    DECLARE xValor_Total_Desconto DECIMAL(15,2) DEFAULT 0;

    DECLARE xValor_Total_Cubagem DECIMAL(10,3) DEFAULT 0;

    DECLARE xValor_Trib_Transparencia DECIMAL(15,2) DEFAULT 0;

    SELECT sum(T008_Valor_Total_Custo),

           sum(T008_Valor_Total_Preco),

           sum(T008_Valor_Total_Preco),

           sum(T008_Valor_Total_Preco_Sem_Desconto),

           sum(T008_Valor_Total_Custo_Final),

           sum(round(T008_Valor_Base_ICMS,2)),

           sum(T008_Valor_Base_ICMS_Sem_Reducao),

           sum(T008_Valor_Base_ICMS_Diferido),

           sum(T008_Valor_ICMS),

           sum(T008_Valor_Base_IPI),

           sum(T008_Valor_IPI),

           sum(T008_Valor_Base_ICMS_Impresso),

           sum(T008_Valor_Base_ICMS_Substituicao),

           sum(T008_Valor_ICMS_Substituicao),

           sum(T008_Valor_ICMS_Substituicao_Retencao),

           sum(T008_Peso_Total),

           sum(T008_Peso_Bruto_Total),

           sum(T008_Valor_Total_Imposto_Importacao),

           sum(T008_Valor_COFINS),

           sum(T008_Valor_PIS),

           sum(T008_Valor_Total_Desconto),

           sum(T008_Total_Cubagem),

           sum(T008_Valor_Trib_Transparencia)

      INTO xValor_Total_Custo,

           xValor_Total_Produtos,

           xValor_Total_Preco,

           xValor_Total_Produtos_Sem_Desconto,

           xValor_Total_Custo_Final,

           xValor_Base_ICMS,

           xValor_Base_ICMS_Sem_Reducao,

           xValor_Base_ICMS_Diferido,

           xValor_ICMS,

           xValor_Base_IPI,

           xValor_IPI,

           xValor_Base_ICMS_Impresso,

           xValor_Base_ICMS_Substituicao,

           xValor_ICMS_Substituicao,

           xValor_ICMS_Substituicao_Retencao,

           xPeso_Total,

           xPeso_Total_Bruto,

           xValor_Total_II,

           xValor_COFINS,

           xValor_PIS,

           xValor_Total_Desconto,

           xValor_Total_Cubagem,

           xValor_Trib_Transparencia

           FROM T008

           WHERE T008_T007_Id=xT007_Id;

      

      SELECT sum(T203_Valor_Unitario)

      INTO xValor_Total_Servicos

      FROM T203

      WHERE T203_T007_Id=xT007_Id;

       

    UPDATE T007 SET T007_Valor_Total_Custo=xValor_Total_Custo,

                    T007_Valor_Total_Produtos=xValor_Total_Produtos,

                    T007_Valor_Total_Servicos=xValor_Total_Servicos,

                    T007_Valor_Total_Produtos_Sem_Desconto = xValor_Total_Produtos_Sem_Desconto,

                    T007_Valor_Total_Preco=xValor_Total_Preco,

                    T007_Valor_Total_Custo_Final=xValor_Total_Custo_Final-T007_Valor_Desconto,

                    T007_Valor_Total_Base_ICMS_Sem_Reducao=xValor_Base_ICMS_Sem_Reducao,

                    T007_Valor_Total_Base_ICMS=xValor_Base_ICMS,

                    T007_Valor_Total_Base_ICMS_Diferido=xValor_Base_ICMS_Diferido,

                    T007_Valor_Total_Base_ICMS_Impresso=xValor_Base_ICMS_Impresso,

                    T007_Valor_Total_ICMS=xValor_ICMS,

                    T007_Valor_Total_Base_IPI=xValor_Base_IPI,

                    T007_Valor_Total_IPI=xValor_IPI,

                    T007_Valor_Total_Imposto_Importacao=xValor_Total_II,

                    T007_Valor_ISS=if(T007_Aliquota_ISS>0,T007_Valor_Mao_Obra*(T007_Aliquota_ISS/100),0),

                    T007_IPV=T007_IPV_Medio(xT007_Id,1),

                    T007_Total_Peso=xPeso_Total,

                    T007_Total_Peso_Bruto=xPeso_Total_Bruto,

                    T007_IPV_sem_icms=T007_IPV_Medio(xT007_Id,2),

                    T007_Valor_Base_ICMS_Substituicao=xValor_Base_ICMS_Substituicao,

                    T007_Valor_ICMS_Substituicao=xValor_ICMS_Substituicao,

                    T007_Valor_ICMS_Substituicao_Retencao=ifnull(xValor_ICMS_Substituicao_Retencao,0.00),

                    T007_Valor_Total_COFINS=xValor_COFINS,

                    T007_Valor_Total_PIS=xValor_PIS,

                    T007_Valor_Desconto=xValor_Total_Desconto,

                    T007_Valor_Total_Trib_Transparencia=xValor_Trib_Transparencia,

                    T007_Valor_Total=T007_Valor_Total_Produtos+

                                     T007_Valor_Total_Servicos+

                                     T007_Valor_Mao_Obra+

                                     T007_Valor_Despesas_Acessorias+

                                     T007_Valor_ICMS_Substituicao_Retencao+

                                     T007_Valor_Total_IPI+

                                     T007_Valor_Seguro+

                                     T007_Valor_Frete-

                                     T007_Valor_Desconto,

                    T007_Total_Cubagem=IFNULL(xValor_Total_Cubagem,0)

              WHERE T007_Id=xT007_Id and T007_Flag_Calcular='S';

    -- SO FAZ OS CALCULOS DA NOTA SE FOR UMA NOTA NORMAL (T007_Flag_Finalidade_NFe=1)

    UPDATE T007 SET T007_Peso_Bruto = xPeso_Total_Bruto,

                    T007_Peso_Liquido = xPeso_Total

                WHERE T007_Id=xT007_Id AND T007_Flag_Totalizar_Peso = 'S';

END */$$
DELIMITER ;

/* Procedure structure for procedure `T008_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T008_Gravar_Totalizacao`(xT008_Id int(11))
BEGIN

    DECLARE xPercentual_Desconto DECIMAL(19,10) DEFAULT 0;

    DECLARE xMultiplicador_Despesa DECIMAL(19,10) DEFAULT 0;

    DECLARE xMultiplicador_Despesas_Acessorias DECIMAL(19,10) DEFAULT 0;

    DECLARE xMultiplicador_Frete DECIMAL(19,10) DEFAULT 0;

    DECLARE xMultiplicador_Seguro DECIMAL(19,10) DEFAULT 0;

    DECLARE xT007_Id INT(11) DEFAULT 0;

    DECLARE xFlag_Revenda_Consumidor VARCHAR(1);

    DECLARE xFlag_Venda_Compra_Outros VARCHAR(1);

    DECLARE xD006_Flag_Somar_IPI_Base_ICMS ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Somar_Despesas_Base_IPI ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Forma_Calculo_COFINS varchar(1) default 'V';

    DECLARE xD006_Flag_Forma_Calculo_PIS varchar(1) default 'V';

    DECLARE xC004_Casas_Decimais_Preco int(2);

    DECLARE xT007_Casas_Decimais_Preco int(2);

    DECLARE xC004_Id int(10);

    DECLARE xT134_Id int(10) default '0';

    DECLARE xT008_Flag_Calculo_Manual varchar(1) default 'N';

    DECLARE xT134_Reducao_Base_ICMS decimal(10,2) default '0';

  	DECLARE xFlag_ACP char(1);

	

    SELECT T008_T007_Id,

           D006_Flag_Venda_Compra_Outros,

           D006_Flag_Somar_IPI_Base_ICMS,

           D006_Flag_Somar_Despesas_Base_IPI,

           D006_Flag_Forma_Calculo_COFINS,

           D006_Flag_Forma_Calculo_PIS,

           T008_Flag_Calculo_Manual,

           T007_Casas_Decimais_Preco,

           T007_C004_Id,

           T007_Flag_ACP,

           T134_Reducao_Base_ICMS,

           T134_Id

      INTO xT007_Id,

           xFlag_Venda_Compra_Outros,

           xD006_Flag_Somar_IPI_Base_ICMS,

           xD006_Flag_Somar_Despesas_Base_IPI,

           xD006_Flag_Forma_Calculo_COFINS,

           xD006_Flag_Forma_Calculo_PIS,

           xT008_Flag_Calculo_Manual,

           xT007_Casas_Decimais_Preco,

           xC004_Id,

           xFlag_ACP,

           xT134_Reducao_Base_ICMS,

           xT134_Id

      FROM T008

     LEFT JOIN T007 ON T007_Id=T008_T007_Id

     LEFT JOIN D006 ON D006_Id=T008_D006_Id

     LEFT JOIN D024 ON D024_Id=T007_D024_Id

     LEFT JOIN D020 ON D020_Id=D024_D020_Id

     LEFT JOIN T134 ON T134_Id=T007_T134_Id

     LEFT JOIN D053 ON D053_D018_Id=D020_D018_Id AND D053_C004_Id=T007_C004_Id

      WHERE T008_Id=xT008_Id

       LIMIT 1;



      SELECT C004_Casas_Decimais_Preco

        INTO xC004_Casas_Decimais_Preco

        FROM C004

       WHERE C004_Id=xC004_Id;

       

    IF xT007_Casas_Decimais_Preco>0 THEN

       SET xC004_Casas_Decimais_Preco = xT007_Casas_Decimais_Preco;

    END IF;

    

    SELECT (T007_Valor_Desconto/T007_Valor_Total_Produtos)

      INTO xPercentual_Desconto

      FROM T007

    LEFT JOIN T008 ON T008_T007_Id=T007_Id

    WHERE T007_Id=xT007_Id

    GROUP BY T007_Id;

    IF xPercentual_Desconto IS NULL THEN

       SET xPercentual_Desconto = 0;

    END IF;

    SELECT  (T007_Valor_Frete+T007_Valor_Despesas_Acessorias+T007_Valor_Seguro) / sum(T008_Valor_Total_Preco),

             T007_Valor_Despesas_Acessorias / sum(T008_Valor_Total_Preco),

             T007_Valor_Seguro / sum(T008_Valor_Total_Preco),

             T007_Valor_Frete / sum(T008_Valor_Total_Preco),

             T007_Flag_Revenda_Consumidor

    INTO xMultiplicador_Despesa,

             xMultiplicador_Despesas_Acessorias,

             xMultiplicador_Seguro,

             xMultiplicador_Frete,

             xFlag_Revenda_Consumidor

    FROM T007

    LEFT JOIN T008 ON T008_T007_Id=T007_Id

    WHERE T007_Id=xT007_Id

    GROUP BY T007_Id;

    IF xMultiplicador_Despesa IS NULL THEN

       SET xMultiplicador_Despesa = 0;

    END IF;

    IF xMultiplicador_Despesas_Acessorias IS NULL THEN

       SET xMultiplicador_Despesas_Acessorias = 0;

    END IF;

    IF xMultiplicador_Frete IS NULL THEN

       SET xMultiplicador_Frete = 0;

    END IF;

    IF xMultiplicador_Seguro IS NULL THEN

       SET xMultiplicador_Seguro = 0;

    END IF;

    IF (xT008_Flag_Calculo_Manual = 'S') THEN

        UPDATE T008 LEFT JOIN D009 ON D009_Id=T008_D009_Id

        			LEFT JOIN T007 ON T007_Id=T008_T007_Id

                    SET T008_Valor_Preco_Unitario = T008_Valor_Preco_Sem_Desconto_Unitario,

                        T008_Valor_Total_Preco = T008_Valor_Preco_Unitario * T008_Quantidade,

                        T008_Valor_Total_Preco_Sem_Desconto = T008_Valor_Preco_Sem_Desconto_Unitario * T008_Quantidade, 

                        T008_Valor_Total_Custo=T008_Valor_Custo_Unitario*T008_Quantidade,

                        T008_Valor_Total_Despesas=T008_Valor_Total_Preco*xMultiplicador_Despesa,

                        T008_Valor_Total_Despesas_Acessorias=if((T008_Valor_Total_Preco*xMultiplicador_Despesas_Acessorias)<0.01 and xMultiplicador_Despesas_Acessorias>0,0.01,T008_Valor_Total_Preco*xMultiplicador_Despesas_Acessorias),

                        T008_Valor_Total_Frete=if(xMultiplicador_Frete>0 and (T008_Valor_Total_Preco*xMultiplicador_Frete)<=0.01,0.01,T008_Valor_Total_Preco*xMultiplicador_Frete),

                        T008_Valor_Total_Seguro=T008_Valor_Total_Preco*xMultiplicador_Seguro,

                        T008_Valor_Despesas_Unitario=T008_Valor_Total_Despesas/T008_Quantidade,

                        T008_Valor_Despesas_Acessorias_Unitario=T008_Valor_Total_Despesas_Acessorias/T008_Quantidade,

                        T008_Valor_Frete_Unitario=T008_Valor_Total_Frete/T008_Quantidade,

                        T008_Valor_Seguro_Unitario=T008_Valor_Total_Seguro/T008_Quantidade,

                        T008_Peso_Total=T008_Quantidade*T008_Peso_Unitario,

                        T008_Peso_Bruto_Total=T008_Quantidade*T008_Peso_Bruto,

                        T008_Valor_Total_Custo_Final=(T008_Valor_Total_Preco+T008_Valor_Total_Despesas+if(xFlag_Revenda_Consumidor='C',T008_Valor_IPI,0)),

                        T008_Valor_Custo_Final_Unitario=T008_Valor_Total_Custo_Final/T008_Quantidade,

                        T008_Valor_Base_ICMS_Diferido=T008_Valor_Base_ICMS_Sem_Reducao-T008_Valor_Base_ICMS,

                        T008_IPV=T008_Valor_Preco_Unitario/T008_Valor_Custo_Unitario,

                        T008_Aliquota_PIS=if(T008_Flag_Isento_PIS='S',0,T008_Aliquota_PIS),

                        T008_Aliquota_COFINS=if(T008_Flag_Isento_COFINS='S',0,T008_Aliquota_COFINS),

                        T008_Total_Cubagem = IFNULL(T008_Cubagem_Unitaria,0) * IFNULL(T008_Quantidade,0),

                        T008_Valor_Trib_Transparencia=IFNULL(T008_Valor_Total_Preco_Sem_Desconto,0)*(IFNULL(T008_Percentual_Trib_Transparencia,0)/100)

                    WHERE T008_Id=xT008_Id and T007_Flag_Calcular='S';

    ELSE

        UPDATE T008 LEFT JOIN D009 ON D009_Id=T008_D009_Id

        			LEFT JOIN T007 ON T007_Id=T008_T007_Id

                    SET T008_Valor_Preco_Unitario = T008_Valor_Preco_Sem_Desconto_Unitario,

                        T008_Valor_Total_Preco              = if(xFlag_ACP=4,truncate(T008_Valor_Preco_Unitario              * T008_Quantidade,2),T008_Valor_Preco_Unitario              * T008_Quantidade),

                        T008_Valor_Total_Preco_Sem_Desconto = if(xFlag_ACP=4,truncate(T008_Valor_Preco_Sem_Desconto_Unitario * T008_Quantidade,2),T008_Valor_Preco_Sem_Desconto_Unitario * T008_Quantidade), 

                        T008_Valor_Total_Custo=T008_Valor_Custo_Unitario*T008_Quantidade,

                        T008_Valor_Total_Despesas=T008_Valor_Total_Preco*xMultiplicador_Despesa,

                        T008_Valor_Total_Despesas_Acessorias=if((T008_Valor_Total_Preco*xMultiplicador_Despesas_Acessorias)<0.01 and xMultiplicador_Despesas_Acessorias>0,0.01,T008_Valor_Total_Preco*xMultiplicador_Despesas_Acessorias),

                        T008_Valor_Total_Frete=if(xMultiplicador_Frete>0 and (T008_Valor_Total_Preco*xMultiplicador_Frete)<=0.01,0.01,T008_Valor_Total_Preco*xMultiplicador_Frete),

                        T008_Valor_Total_Seguro=T008_Valor_Total_Preco*xMultiplicador_Seguro,

                        T008_Valor_Base_IPI=If(T008_Aliquota_IPI>0,(T008_Valor_Total_Preco+T008_Valor_Total_Imposto_Importacao+if(xD006_Flag_Somar_Despesas_Base_IPI='S',T008_Valor_Total_Frete+T008_Valor_Total_Seguro+T008_Valor_Total_Despesas_Acessorias,0))*If(T008_Percentual_Reducao_IPI>0,(T008_Percentual_Reducao_IPI/100),1),0),

                        T008_Valor_IPI=round(T008_Valor_Base_IPI*(T008_Aliquota_IPI/100),2),

                        T008_Valor_Despesas_Unitario=T008_Valor_Total_Despesas/T008_Quantidade,

                        T008_Valor_Despesas_Acessorias_Unitario=T008_Valor_Total_Despesas_Acessorias/T008_Quantidade,

                        T008_Valor_Frete_Unitario=T008_Valor_Total_Frete/T008_Quantidade,

                        T008_Valor_Seguro_Unitario=T008_Valor_Total_Seguro/T008_Quantidade,

                        T008_Peso_Total=T008_Quantidade*T008_Peso_Unitario,

                        T008_Peso_Bruto_Total=T008_Quantidade*T008_Peso_Bruto,

                        T008_Valor_Total_Custo_Final=(T008_Valor_Total_Preco+T008_Valor_Total_Despesas+if(xFlag_Revenda_Consumidor='C',T008_Valor_IPI,0)),

                        T008_Valor_Custo_Final_Unitario=T008_Valor_Total_Custo_Final/T008_Quantidade,

                        T008_Valor_Base_ICMS_Sem_Reducao=If(T008_Aliquota_ICMS>0,T008_Valor_Total_Custo_Final+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T008_Valor_IPI,0),0),

                        T008_Valor_Base_ICMS=If(T008_Aliquota_ICMS>0,T008_Valor_Base_ICMS_Sem_Reducao*if(T008_Percentual_Reducao_ICMS>0,(T008_Percentual_Reducao_ICMS/100),1),0),

                        T008_Valor_Base_ICMS_Diferido=T008_Valor_Base_ICMS_Sem_Reducao-T008_Valor_Base_ICMS,

                        T008_Valor_ICMS=T008_Valor_Base_ICMS*(T008_Aliquota_ICMS/100),

                        T008_IPV=T008_Valor_Preco_Unitario/T008_Valor_Custo_Unitario,

                        T008_Valor_Base_ICMS_Substituicao=IF(T008_Flag_ST='S',(T008_Valor_Total_Preco+T008_Valor_Total_Despesas+T008_Valor_IPI)*((T008_ST_VA/100)+1),0),

                        T008_Valor_ICMS_Substituicao=(T008_Valor_Base_ICMS_Substituicao*(T008_ST_ICMS_Interno/100)),

                        T008_Valor_ICMS_Substituicao_Retencao=((T008_Valor_Base_ICMS_Substituicao*if(T008_Percentual_Reducao_ICMS_ST>0,(T008_Percentual_Reducao_ICMS_ST/100),1))*(T008_ST_ICMS_Interno/100))-((T008_Valor_Total_Custo_Final*if(T008_Percentual_Reducao_ICMS>0,(T008_Percentual_Reducao_ICMS/100),1))*T008_ICMS_Inter_Estadual/100),

                        T008_Valor_ICMS_Substituicao_Retencao=IF(T008_Valor_ICMS_Substituicao_Retencao<0,0,T008_Valor_ICMS_Substituicao_Retencao),

                        T008_Valor_Base_ICMS_Impresso=if(substring(T008_Flag_Situacao_Tributaria,2,2)='51' or substring(T008_Flag_Situacao_Tributaria,2,2)='90',T008_Valor_Base_ICMS_Sem_Reducao,T008_Valor_Base_ICMS),

                        T008_Valor_Base_PIS=if(T008_Flag_Isento_PIS='S',0,if(xD006_Flag_Forma_Calculo_PIS='L',if(T008_Valor_Total_Custo<T008_Valor_Total_Preco,T008_Valor_Total_Preco-T008_Valor_Total_Custo,0),T008_Valor_Total_Preco)),

                        T008_Aliquota_PIS=if(T008_Flag_Isento_PIS='S',0,T008_Aliquota_PIS),

                        T008_Valor_PIS=if(T008_Aliquota_PIS>0,T008_Valor_Base_PIS*(T008_Aliquota_PIS/100),0),

                        T008_Valor_Base_COFINS=if(T008_Flag_Isento_COFINS='S',0,if(xD006_Flag_Forma_Calculo_COFINS='L',if(T008_Valor_Total_Custo<T008_Valor_Total_Preco,T008_Valor_Total_Preco-T008_Valor_Total_Custo,0),T008_Valor_Total_Preco)),

                        T008_Aliquota_COFINS=if(T008_Flag_Isento_COFINS='S',0,T008_Aliquota_COFINS),

                        T008_Valor_COFINS=if(T008_Aliquota_COFINS>0,T008_Valor_Base_COFINS*(T008_Aliquota_COFINS/100),0),

                        T008_Valor_ICMS_Credito=if(xT134_Id<=0 or xT134_Id='' or ifnull(xT134_Id,0)<=0,T008_Valor_ICMS_Credito,If(T008_Aliquota_ICMS_Credito>0,(T008_Valor_Total_Custo_Final+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T008_Valor_IPI,0))-((T008_Valor_Total_Custo_Final+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T008_Valor_IPI,0))*if(xT134_Reducao_Base_ICMS>0,(xT134_Reducao_Base_ICMS/100),1)),0)*(T008_Aliquota_ICMS_Credito/100)),

                        T008_Total_Cubagem = IFNULL(T008_Cubagem_Unitaria,0) * IFNULL(T008_Quantidade,0),

                        T008_Valor_Trib_Transparencia=IFNULL(T008_Valor_Total_Preco_Sem_Desconto,0)*(IFNULL(T008_Percentual_Trib_Transparencia,0)/100)

                    WHERE T008_Id=xT008_Id and T007_Flag_Calcular='S';

    END IF;

END */$$
DELIMITER ;

/* Procedure structure for procedure `T010_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T010_Gravar_Totalizacao`(xT010_Id int(11))
BEGIN

    UPDATE T010

    SET T010_Valor_Total_Custo=(SELECT sum(T059_Valor_Total_Custo) FROM T059 WHERE T059_T010_Id=T010_Id)

    WHERE T010_Id=xT010_Id;

END */$$
DELIMITER ;

/* Procedure structure for procedure `T011_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T011_Gravar_Totalizacao`(xT011_Id int(11))
BEGIN

    UPDATE T011

    SET T011_Valor_Total_Custo=(SELECT sum(T012_Valor_Total_Custo) FROM T012 WHERE T012_T011_Id=T011_Id),

        T011_Valor_Total_Pendente=(SELECT sum(T012_Quantidade_Falta_Lancar(T012_Id,0)*T012_Valor_Custo_Unitario) FROM T012 WHERE T012_T011_Id=T011_Id)

    WHERE T011_Id=xT011_Id;

END */$$
DELIMITER ;

/* Procedure structure for procedure `T011_Gravar_Totalizacao_3` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T011_Gravar_Totalizacao_3`(xT011_Id int(11))
BEGIN

    UPDATE T011

    SET T011_Valor_Total_Custo=(SELECT SUM(T012_Valor_Total_Custo) FROM T012 WHERE T012_T011_Id=T011_Id)+(SELECT IFNULL(SUM(T210_Valor_Unitario),0) FROM T210 LEFT JOIN T012 ON T012_Id = T210_T012_Id WHERE T012_T011_Id=T011_Id),

        T011_Valor_Total_Pendente=(SELECT SUM(T012_Quantidade_Falta_Lancar(T012_Id,0)*T012_Valor_Custo_Unitario) FROM T012 WHERE T012_T011_Id=T011_Id)

    WHERE T011_Id=xT011_Id;

END */$$
DELIMITER ;

/* Procedure structure for procedure `T012_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T012_Gravar_Totalizacao`(xT012_Id int(11))
BEGIN

    UPDATE T012 SET T012_Valor_Total_Custo=T012_Valor_Custo_Unitario*T012_Quantidade WHERE T012_Id=xT012_Id;

END */$$
DELIMITER ;

/* Procedure structure for procedure `T013_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T013_Gravar_Totalizacao`(xT013_Id int(11))
BEGIN

    DECLARE xT014_Valor_Total_Custo_Final DECIMAL(19,2);

    SELECT sum(T014_Valor_Total_Custo_Final)

      INTO xT014_Valor_Total_Custo_Final

      FROM T014

    WHERE T014_T013_Id=xT013_Id;

    IF xT014_Valor_Total_Custo_Final IS NULL THEN

       SET xT014_Valor_Total_Custo_Final = 0;

    END IF;

    UPDATE T013 SET T013_Valor_Total_Custo_Final = xT014_Valor_Total_Custo_Final

     WHERE T013_Id=xT013_Id and T013_Flag_Travar_Nota!='S' and T013_Flag_Calcular='S';

END */$$
DELIMITER ;

/* Procedure structure for procedure `T014_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T014_Gravar_Totalizacao`(xT014_Id int(11))
BEGIN
    DECLARE xT013_Id INT(11);
    DECLARE xValor_Total_Produtos DECIMAL(14,2);
    DECLARE xValor_Custo_Final_Unitario DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final DECIMAL(10,2);
    DECLARE xValor_Custo_Unitario DECIMAL(10,2);
    DECLARE xValor_Total_Custo DECIMAL(10,2);
    DECLARE xValor_Desconto_Produtos DECIMAL(12,6);
    DECLARE xValor_Frete DECIMAL(10,2);
    DECLARE xValor_Seguro DECIMAL(14,2);
    DECLARE xValor_IPI DECIMAL(14,3);
    DECLARE xValor_Despesas_Acessorias DECIMAL(14,2);
    DECLARE xFlag_Calcular_ICMS_Frete VARCHAR(1);
    DECLARE xFlag_Calcular_ICMS_IPI VARCHAR(1);
    DECLARE xFlag_Calcular_ICMS_Seguro VARCHAR(1);
    DECLARE xFlag_Calcular_ICMS_Despesas_Acessorias VARCHAR(1);
    DECLARE xFlag_Arredondar_Valor_IPI VARCHAR(1);
    DECLARE xFlag_Calcular_IPI_Frete VARCHAR(1);
    DECLARE xFlag_Calcular_IPI_Seguro VARCHAR(1);
    DECLARE xFlag_Calcular_IPI_Despesas_Acessorias VARCHAR(1);
    DECLARE xFlag_Venda_Compra_Outros VARCHAR(1);
    DECLARE xFlag_Credita_IPI VARCHAR(1);
    DECLARE xFlag_Substituicao_Tributaria VARCHAR(1);
    DECLARE xC004_Id INT(11);
    DECLARE xValor_Adicional_Base_ICMS DECIMAL(10,2);
    DECLARE xValor_Adicional_Base_IPI DECIMAL(10,2);
    DECLARE xValor_Desconto_Adicional DECIMAL(14,2);
    DECLARE xValor_Frete_Adicional DECIMAL(14,3);
    DECLARE xValor_Substituicao_Adicional DECIMAL(14,3);    
    DECLARE xValor_Seguro_Adicional DECIMAL(14,2);
    DECLARE xValor_Despesas_Acessorias_Adicional DECIMAL(14,2);
    DECLARE xPercentual_Reducao_ICMS DECIMAL(6,2);
    DECLARE xPercentual_Reducao_IPI DECIMAL(6,2);
    DECLARE xValor_Base_ICMS DECIMAL(10,2);
    DECLARE xValor_Base_IPI DECIMAL(10,2);
    DECLARE xAliquota_ICMS DECIMAL(5,2);
    DECLARE xAliquota_IPI DECIMAL(5,2);
    DECLARE xValor_Total_Desconto DECIMAL(10,5);
    DECLARE xValor_Total_Desp_Nota_Origem DECIMAL(20,2);
    DECLARE xValor_ICMS DECIMAL(12,5);
    DECLARE xValor_ICMS_Substituicao DECIMAL(12,5);
    DECLARE xValor_ICMS_Diferenca_Aliquotas DECIMAL(12,5);
    DECLARE xTotal_Produtos_ST DECIMAL(12,5);
    DECLARE xDecimais_Valor_ICMS INT(1);
    DECLARE xQuantidade DECIMAL(10,2);
    DECLARE xFlag_Devolucao VARCHAR(1);
    DECLARE xSimples INT(1) DEFAULT 0;
    DECLARE xD006_Flag_Deb_Crd_ICMS VARCHAR(1) DEFAULT 'S';
    DECLARE xD006_Flag_Substituicao_Tributaria VARCHAR(1) DEFAULT 'S';
    DECLARE xFlag_Calcular enum('S','N') default 'S';
    SET xDecimais_Valor_ICMS=2;
    SELECT T014_T013_Id,
           T014_Percentual_Reducao_ICMS,
           T014_Percentual_Reducao_IPI,
           T014_Aliquota_ICMS,
           T014_Aliquota_IPI,
           T014_Valor_Custo_Unitario,
           T014_Quantidade*T014_Valor_Custo_Unitario,
           T014_Quantidade*T014_Valor_Desconto_Unitario,
           T014_Quantidade*T014_Valor_Unitario_Desp_Nota_Origem,
           D006_Flag_Substituicao_Tributaria,
           T014_Quantidade
      INTO xT013_Id,
           xPercentual_Reducao_ICMS,
           xPercentual_Reducao_IPI,
           xAliquota_ICMS,
           xAliquota_IPI,
           xValor_Custo_Unitario,
           xValor_Total_Custo,
           xValor_Total_Desconto,
           xValor_Total_Desp_Nota_Origem,
           xD006_Flag_Substituicao_Tributaria,
           xQuantidade
      FROM T014
      LEFT JOIN D006 ON D006_Id=T014_D006_Id
     WHERE T014_Id=xT014_Id;
     
    SELECT sum(T014_Valor_Total_Custo)
      INTO xTotal_Produtos_ST
      FROM T014
      LEFT JOIN D006 ON D006_Id=T014_D006_Id
     WHERE T014_T013_Id=xT013_Id
       AND D006_Flag_Substituicao_Tributaria='S';
           
    SELECT T013_Valor_Total_Produtos+T013_Valor_Desconto_Produtos,
           T013_Valor_Desconto_Produtos+T013_Valor_Desconto,
           T013_Valor_Frete,
           T013_Valor_Seguro,
           T013_Valor_Despesas_Acessorias,
           T013_Flag_Calcular_ICMS_Frete,
           T013_Flag_Calcular_ICMS_IPI,
           T013_Flag_Calcular_ICMS_Seguro,
           T013_Flag_Calcular_ICMS_Despesas_Acessorias,
           T013_Flag_Calcular_IPI_Frete,
           T013_Flag_Calcular_IPI_Seguro,
           T013_Flag_Calcular_IPI_Despesas_Acessorias,
           T013_Flag_Arredondar_Valor_IPI,
           T013_Casas_Decimais_Valor_ICMS,
           D006_Flag_Venda_Compra_Outros,
           D006_Flag_Credita_IPI,
           D006_Flag_Deb_Crd_ICMS,
           D006_Flag_Substituicao_Tributaria,
           T013_C004_Id,	
           T013_Flag_Devolucao,
           T013_Valor_ICMS_Substituicao,
           T013_Valor_ICMS_Diferenca_Aliquotas,
           C004_Flag_Empresa_Simples,
           T013_Flag_Calcular
      INTO xValor_Total_Produtos,
           xValor_Desconto_Produtos,
           xValor_Frete,
           xValor_Seguro,
           xValor_Despesas_Acessorias,
           xFlag_Calcular_ICMS_Frete,
           xFlag_Calcular_ICMS_IPI,
           xFlag_Calcular_ICMS_Seguro,
           xFlag_Calcular_ICMS_Despesas_Acessorias,
           xFlag_Calcular_IPI_Frete,
           xFlag_Calcular_IPI_Seguro,
           xFlag_Calcular_IPI_Despesas_Acessorias,
           xFlag_Arredondar_Valor_IPI,
           xDecimais_Valor_ICMS,
           xFlag_Venda_Compra_Outros,
           xFlag_Credita_IPI,
           xD006_Flag_Deb_Crd_ICMS,
           xFlag_Substituicao_Tributaria,
           xC004_Id,
           xFlag_Devolucao,
           xValor_ICMS_Substituicao,
           xValor_ICMS_Diferenca_Aliquotas,
           xSimples,
           xFlag_Calcular
      FROM T013
 LEFT JOIN D006 on D006_Id=T013_D006_Id
 LEFT JOIN C004 on C004_Id=T013_C004_Id
    WHERE T013_Id=xT013_Id;
    IF xValor_ICMS_Substituicao>0 and xD006_Flag_Substituicao_Tributaria='S' THEN
       SET xValor_Substituicao_Adicional = round((xValor_ICMS_Substituicao / xTotal_Produtos_ST) * xValor_Total_Custo,3);
    ELSE
       SET xValor_Substituicao_Adicional = 0;
    END IF;
    
    IF xValor_Desconto_Produtos>0 THEN
       SET xValor_Total_Desconto= round((xValor_Desconto_Produtos / xValor_Total_Produtos) * xValor_Total_Custo,5);
    ELSE
       SET xValor_Total_Desconto = 0;
    END IF;
    IF xValor_ICMS_Diferenca_Aliquotas>0 THEN
       SET xValor_ICMS_Diferenca_Aliquotas = round((xValor_ICMS_Diferenca_Aliquotas / xValor_Total_Produtos) * xValor_Total_Custo,5);
    ELSE
       SET xValor_Total_Desconto = 0;
    END IF;
    SET xValor_Desconto_Adicional= xValor_Total_Desconto / xQuantidade;
    IF xValor_Frete>0 THEN
       SET xValor_Frete_Adicional = round((xValor_Frete / xValor_Total_Produtos) * xValor_Total_Custo,3);
    ELSE
       SET xValor_Frete_Adicional = 0;
    END IF;
    IF xValor_Seguro>0 THEN
       SET xValor_Seguro_Adicional = round((xValor_Seguro / xValor_Total_Produtos) * xValor_Total_Custo,2);
    ELSE
       SET xValor_Seguro_Adicional = 0;
    END IF;
    IF xValor_Despesas_Acessorias>0 THEN
       SET xValor_Despesas_Acessorias_Adicional = round((xValor_Despesas_Acessorias / xValor_Total_Produtos) * xValor_Total_Custo,2);
    ELSE
       SET xValor_Despesas_Acessorias_Adicional = 0;
    END IF;
    SET xValor_Adicional_Base_ICMS = 0 - xValor_Total_Desconto;
    IF xFlag_Calcular_ICMS_Frete = 'S' THEN
       SET xValor_Adicional_Base_ICMS = xValor_Frete_Adicional;
    END IF;
    IF xFlag_Calcular_ICMS_Seguro='S' THEN
       SET xValor_Adicional_Base_ICMS = xValor_Adicional_Base_ICMS + xValor_Seguro_Adicional;
    END IF;
    IF xFlag_Calcular_ICMS_Despesas_Acessorias='S' THEN
       SET xValor_Adicional_Base_ICMS = xValor_Adicional_Base_ICMS + xValor_Despesas_Acessorias_Adicional;
    END IF;
    SET xValor_Adicional_Base_IPI = 0;
    IF xFlag_Calcular_IPI_Frete='S' THEN
       SET xValor_Adicional_Base_IPI = xValor_Frete_Adicional;
    END IF;
    IF xFlag_Calcular_IPI_Seguro='S' THEN
       SET xValor_Adicional_Base_IPI = xValor_Adicional_Base_IPI + xValor_Seguro_Adicional;
    END IF;
    IF xFlag_Calcular_IPI_Despesas_Acessorias='S' THEN
       SET xValor_Adicional_Base_IPI = xValor_Adicional_Base_IPI + xValor_Despesas_Acessorias_Adicional;
    END IF;
    IF xAliquota_IPI>0 THEN
       SET xValor_Base_IPI = (xValor_Total_Custo + xValor_Adicional_Base_IPI);
       IF xFlag_Devolucao = 'S' THEN
          SET xValor_Base_IPI = xValor_Base_IPI + xValor_Total_Desp_Nota_Origem;
       END IF;
    ELSE
       SET xValor_Base_IPI = 0;
    END IF;
    IF xPercentual_Reducao_IPI>0 and xAliquota_IPI>0 THEN
       SET xValor_Base_IPI = xValor_Base_IPI  * ( xPercentual_Reducao_IPI / 100 );
    END IF;
    SET xValor_IPI=if(xAliquota_IPI>0,xValor_Base_IPI*(xAliquota_IPI/100),0);
    IF xFlag_Arredondar_Valor_IPI='S' THEN
       SET xValor_IPI = ROUND(xValor_IPI,2);
    ELSE
       SET xValor_IPI = TRUNCATE(xValor_IPI,2);
    END IF;
    IF xFlag_Calcular_ICMS_IPI='S' THEN
       SET xValor_Adicional_Base_ICMS = xValor_Adicional_Base_ICMS + xValor_IPI;
    END IF;
    IF xAliquota_ICMS>0 THEN
       SET xValor_Base_ICMS = (xValor_Total_Custo + xValor_Adicional_Base_ICMS);
    ELSE
       SET xValor_Base_ICMS = 0;
    END IF;
    IF xPercentual_Reducao_ICMS>0 and xAliquota_ICMS>0 THEN
       SET xValor_Base_ICMS = (xValor_Total_Custo + xValor_Adicional_Base_ICMS)  * ( xPercentual_Reducao_ICMS / 100 );
    END IF;
    SET xValor_ICMS = 0;
    IF xAliquota_ICMS>0 THEN
       SET xValor_ICMS = round(xValor_Base_ICMS*(xAliquota_ICMS/100),5);
       IF xDecimais_Valor_ICMS = 2 THEN
          SET xValor_ICMS = round(xValor_ICMS,2);
       ELSEIF xDecimais_Valor_ICMS = 3 THEN
          SET xValor_ICMS = round(xValor_ICMS,3);
       ELSEIF xDecimais_Valor_ICMS = 4 THEN
          SET xValor_ICMS = round(xValor_ICMS,4);
       ELSEIF xDecimais_Valor_ICMS = 5 THEN
          SET xValor_ICMS = round(xValor_ICMS,5);
       END IF;
    END IF;
    
    if xFlag_Calcular='S' THEN
    # T014_Valor_ICMS_Substituicao    = xValor_Substituicao_Adicional,
    # T014_Valor_ICMS_Substituicao_Unitario = T014_Valor_ICMS_Substituicao / T014_Quantidade,

    # T014_Valor_Custo_Final_Unitario = ((T014_Valor_Total_Custo + T014_Valor_ICMS_Substituicao + T014_Valor_Frete + if(xFlag_Credita_IPI!='S',T014_Valor_IPI,0) + T014_Valor_Seguro + T014_Valor_Despesas_Acessorias - if(xSimples!=1 and xD006_Flag_Deb_Crd_ICMS='S',T014_Valor_ICMS,0) ) - T014_Valor_Total_Desconto)/T014_Quantidade,
    # T014_Valor_Total_Custo_Final    = T014_Valor_Custo_Final_Unitario * T014_Quantidade
    	UPDATE T014 LEFT JOIN T013 ON T013_Id=T014_T013_Id
                SET T014_Valor_Total_Custo          = xValor_Total_Custo,
                    T014_Valor_Desconto_Unitario    = xValor_Desconto_Adicional,
                    T014_Valor_Total_Desconto       = xValor_Total_Desconto,
                    T014_Valor_Frete                = xValor_Frete_Adicional,
                    T014_Valor_ICMS_Diferenca_Aliquotas = xValor_ICMS_Diferenca_Aliquotas,
                    T014_Valor_Seguro               = xValor_Seguro_Adicional,
                    T014_Valor_Despesas_Acessorias  = xValor_Despesas_Acessorias_Adicional,
                    T014_Valor_Base_ICMS            = xValor_Base_ICMS,
                    T014_Valor_Base_IPI             = xValor_Base_IPI,
                    T014_Valor_ICMS                 = xValor_ICMS,
                    T014_Valor_IPI                  = xValor_IPI,
                    T014_Valor_Total_Desp_Nota_Origem = xValor_Total_Desp_Nota_Origem
        WHERE T014_Id=xT014_Id and T013_Flag_Travar_Nota!='S';
	
	ELSE
	
    # T014_Valor_Custo_Final_Unitario = ((T014_Valor_Total_Custo + T014_Valor_ICMS_Substituicao + T014_Valor_Frete + if(xFlag_Credita_IPI!='S',T014_Valor_IPI,0) + T014_Valor_Seguro + T014_Valor_Despesas_Acessorias - if(xSimples!=1 and xD006_Flag_Deb_Crd_ICMS='S',T014_Valor_ICMS,0)) - T014_Valor_Total_Desconto)/T014_Quantidade,
    # T014_Valor_Total_Custo_Final    = T014_Valor_Custo_Final_Unitario * T014_Quantidade
    	UPDATE T014 LEFT JOIN T013 ON T013_Id=T014_T013_Id
                SET T014_Valor_Total_Custo          = xValor_Total_Custo,
                    T014_Valor_Frete                = xValor_Frete_Adicional,
                    T014_Valor_Seguro               = xValor_Seguro_Adicional,
                    T014_Valor_Despesas_Acessorias  = xValor_Despesas_Acessorias_Adicional,
                    T014_Valor_ICMS_Diferenca_Aliquotas = xValor_ICMS_Diferenca_Aliquotas,
                    T014_Valor_Total_Desp_Nota_Origem = xValor_Total_Desp_Nota_Origem
        WHERE T014_Id=xT014_Id and T013_Flag_Travar_Nota!='S';
	
	END IF;	

END */$$
DELIMITER ;

/* Procedure structure for procedure `T014_Gravar_Totalizacao_Custo` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T014_Gravar_Totalizacao_Custo`(xT014_Id int(11))
BEGIN

    DECLARE xFlag_Substituicao_Tributaria VARCHAR(1);

    DECLARE xFlag_Deb_Crd_ICMS VARCHAR(1);

    DECLARE xFlag_Credita_IPI VARCHAR(1);

    SELECT D006_Flag_Substituicao_Tributaria,

           D006_Flag_Deb_Crd_ICMS,

           D006_Flag_Credita_IPI

      INTO xFlag_Substituicao_Tributaria,

           xFlag_Deb_Crd_ICMS,

           xFlag_Credita_IPI

      FROM T014

 LEFT JOIN D006 ON D006_Id=T014_D006_Id   

     WHERE T014_Id=xT014_Id;



    UPDATE T014 SET 

                    T014_Valor_Custo_Final_Unitario = ((T014_Valor_Total_Custo + IF(xFlag_Substituicao_Tributaria='S',T014_Valor_ICMS_Substituicao,0) - T014_Valor_ICMS_Diferenca_Aliquotas + T014_Valor_Frete + IF(xFlag_Credita_IPI='N',T014_Valor_IPI,0) + T014_Valor_Seguro + T014_Valor_Despesas_Acessorias - IF(xFlag_Deb_Crd_ICMS='S', T014_Valor_ICMS, 0)) - T014_Valor_Total_Desconto)/T014_Quantidade,

                    T014_Valor_Total_Custo_Final    = T014_Valor_Custo_Final_Unitario * T014_Quantidade

    WHERE T014_Id=xT014_Id;

END */$$
DELIMITER ;

/* Procedure structure for procedure `T015_Baixar_Titulo` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T015_Baixar_Titulo`(xT015_Id int(11),xData date)
BEGIN
     DECLARE xT015_Valor_Saldo decimal(10,2);
     UPDATE T015
        SET T015_Valor_Comissao=T015_Valor_Base_Comissao*(T015_Percentual_Comissao/100),
            T015_Valor_Juros=(select sum(T033_Valor) from T033 where T033_T015_Id=T015_Id and T033_Flag_Deb_Cred='C' group by T033_T015_Id),
            T015_Valor_Desconto=(select sum(T033_Valor) from T033 where T033_T015_Id=T015_Id and T033_Flag_Deb_Cred='D' group by T033_T015_Id),
            T015_Valor_Pago=(select sum(T019_Valor_Lancamento*-1) from T019 where T019_T015_Id=T015_Id and T019_Flag_Excluido!='S'),
            T015_Valor_Total=ifnull(T015_Valor_Duplicata,0)+ifnull(T015_Valor_Juros,0)-ifnull(T015_Valor_Desconto,0),
            T015_Valor_Saldo=ifnull(T015_Valor_Duplicata,0)+ifnull(T015_Valor_Juros,0)-ifnull(T015_Valor_Desconto,0)-ifnull(T015_Valor_Pago,0)
      WHERE T015_Id=xT015_Id;
     SELECT T015_Valor_Saldo
       INTO xT015_Valor_Saldo
       FROM T015
      WHERE T015_Id=xT015_Id;
     IF xT015_Valor_Saldo<=0 THEN
        UPDATE T015
           SET T015_Data_Pagamento=(select T019_Data_Lancamento from T019 where T019_T015_Id=T015_Id order by T019_Data_Lancamento desc limit 1),
               T015_Data_Baixa=xData
         WHERE T015_Id=xT015_Id
           AND ifnull(T015_Data_Pagamento,'0000-00-00')='0000-00-00';
     ELSE
        UPDATE T015
           SET T015_Data_Pagamento='0000-00-00',
               T015_Data_Baixa='0000-00-00'
         WHERE T015_Id=xT015_Id;
     END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `T015_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T015_Gravar_Totalizacao`(xT015_Id int(11))
BEGIN
     UPDATE T015
        SET T015_Valor_Comissao=T015_Valor_Base_Comissao*(T015_Percentual_Comissao/100),
            T015_Valor_Juros=ifnull((select sum(T033_Valor) from T033 where T033_T015_Id=T015_Id and T033_Flag_Deb_Cred='C' group by T033_T015_Id),0),
            T015_Valor_Desconto=ifnull((select sum(T033_Valor) from T033 where T033_T015_Id=T015_Id and T033_Flag_Deb_Cred='D' group by T033_T015_Id),0),
            T015_Valor_Total=ifnull(T015_Valor_Duplicata,0)+ifnull(T015_Valor_Juros,0)-ifnull(T015_Valor_Desconto,0)
      WHERE T015_Id=xT015_Id;
END */$$
DELIMITER ;

/* Procedure structure for procedure `T054_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T054_Gravar_Totalizacao`(xT054_Id int(11))
BEGIN

    DECLARE xValor_Total DECIMAL(19,2);

    DECLARE xValor_Total_Custo_Original DECIMAL(19,2);

    DECLARE xValor_Total_Produtos DECIMAL(19,2);

    DECLARE xValor_IPI DECIMAL(19,2);

    DECLARE xValor_Base_IPI DECIMAL(19,2);

    DECLARE xValor_Imposto_Importacao DECIMAL(19,2);

    DECLARE xValor_Base_Imposto_Importacao DECIMAL(19,2);

    DECLARE xValor_COFINS DECIMAL(19,2);

    DECLARE xValor_Base_COFINS DECIMAL(19,2);

    DECLARE xValor_PIS DECIMAL(19,2);

    DECLARE xValor_Base_PIS DECIMAL(19,2);

    DECLARE xValor_Extra DECIMAL(19,2);

    DECLARE xValor_Base_Extra DECIMAL(19,2);

    DECLARE xValor_Total_Despesas DECIMAL(19,2);

    DECLARE xValor_Total_Despesas_Real DECIMAL(19,2);

    DECLARE xValor_Total_Despesas_Fatura DECIMAL(19,2);

    DECLARE xValor_Total_Frete_Real DECIMAL(19,2);

    DECLARE xValor_Total_Frete DECIMAL(19,2);

    DECLARE xValor_Despesas_Aduaneira DECIMAL(19,2);

    DECLARE xValor_Despesas_Aduaneira_Real DECIMAL(19,2);

    DECLARE xValor_Despesas_ICMS DECIMAL(19,2);

    DECLARE xValor_Despesas_PIS_COFINS DECIMAL(19,2);

    DECLARE xValor_Despesas_IPI DECIMAL(19,2);

    DECLARE xValor_Despesas_Imposto_Importacao DECIMAL(19,2);

    DECLARE xValor_Total_Base_ICMS_Normal DECIMAL(19,2);

    DECLARE xValor_Total_Base_ICMS_Presumido DECIMAL(19,2);

    DECLARE xValor_Total_ICMS_Normal DECIMAL(19,2);

    DECLARE xValor_Total_ICMS_Presumido DECIMAL(19,2);

    DECLARE xValor_Total_ICMS_Pagar DECIMAL(19,2);

    DECLARE xFlag_Fechado VARCHAR(1);

    DECLARE xPeso_Kg_Liquido_Total DECIMAL(19,3);

    DECLARE xPeso_Kg_Liquido_Fatura_Total DECIMAL(19,6);

    DECLARE xPeso_Lb_Liquido_Total DECIMAL(19,3);

    SELECT T054_Flag_Fechado

      INTO xFlag_Fechado

      FROM T054

     WHERE T054_Id=xT054_Id;

    IF xFlag_Fechado!='X' THEN

       SELECT sum(T055_Valor_Total_Custo),

              sum(T055_Valor_Total_Custo_Original),

              sum(T055_Valor_Total_IPI),

              sum(T055_Valor_Total_Base_IPI),

              sum(T055_Valor_Total_Imposto_Importacao),

              sum(T055_Valor_Total_Base_Imposto_Importacao),

              sum(T055_Valor_Total_COFINS),

              sum(T055_Valor_Total_Base_COFINS),

              sum(T055_Valor_Total_PIS),

              sum(T055_Valor_Total_Base_PIS),

              sum(T055_Valor_Total_Extra),

              sum(T055_Valor_Total_Base_Extra),

              sum(T055_Valor_Total_Despesas),

              sum(T055_Valor_Total_Despesas_Fatura),

              sum(T055_Valor_Total_Frete),

              sum(T055_Valor_Total_Base_ICMS_Sem_Reducao),

              sum(T055_Valor_Total_Base_ICMS_Presumido),

              sum(T055_Valor_Total_ICMS),

              sum(T055_Valor_Total_ICMS_Presumido),

              sum(T055_Valor_Total_ICMS_Pagar),

              sum(T055_Peso_Kg_Liquido_Total),

              sum(T055_Peso_Kg_Liquido_Total_Fatura),

              sum(T055_Peso_Lb_Liquido_Total),

              sum(T055_Valor_Despesas_Aduaneira*T055_Quantidade)

         INTO xValor_Total_Produtos,

              xValor_Total_Custo_Original,

              xValor_IPI,

              xValor_Base_IPI,

              xValor_Imposto_Importacao,

              xValor_Base_Imposto_Importacao,

              xValor_COFINS,

              xValor_Base_COFINS,

              xValor_PIS,

              xValor_Base_PIS,

              xValor_Extra,

              xValor_Base_Extra,

              xValor_Total_Despesas,

              xValor_Total_Despesas_Fatura,

              xValor_Total_Frete,

              xValor_Total_Base_ICMS_Normal,

              xValor_Total_Base_ICMS_Presumido,

              xValor_Total_ICMS_Normal,

              xValor_Total_ICMS_Presumido,

              xValor_Total_ICMS_Pagar,

              xPeso_Kg_Liquido_Total,

              xPeso_Kg_Liquido_Fatura_Total,

              xPeso_Lb_Liquido_Total,

              xValor_Despesas_Aduaneira

              FROM T055

              WHERE T055_T054_Id=xT054_Id;

        SELECT sum(T056_Valor_Total_Despesa_Real)

          INTO xValor_Total_Despesas_Real

              FROM T056

              WHERE T056_T054_Id=xT054_Id

                AND T056_Flag_Calcular_Aduaneira!='S'

                AND T056_Flag_Frete!='S'

                AND T056_T060_Id=0;

        SELECT sum(T056_Valor_Total_Despesa_Real)

          INTO xValor_Total_Frete_Real

              FROM T056

              WHERE T056_T054_Id=xT054_Id

                AND T056_Flag_Frete='S'

                AND T056_T060_Id=0;

        SELECT sum(T056_Valor_Total_Despesa)

          INTO xValor_Despesas_ICMS

              FROM T056

              WHERE T056_T054_Id=xT054_Id

                AND T056_Flag_Calcular_ICMS='S'

                AND T056_T060_Id=0;

        SELECT sum(T056_Valor_Total_Despesa)

          INTO xValor_Despesas_PIS_COFINS

              FROM T056

              WHERE T056_T054_Id=xT054_Id

                AND T056_Flag_Calcular_PIS_COFINS='S'

                AND T056_T060_Id=0;

        SELECT sum(T056_Valor_Total_Despesa)

          INTO xValor_Despesas_IPI

              FROM T056

              WHERE T056_T054_Id=xT054_Id

                AND T056_Flag_Calcular_IPI='S'

                AND T056_T060_Id=0;

        SELECT sum(T056_Valor_Total_Despesa)

          INTO xValor_Despesas_Imposto_Importacao

              FROM T056

              WHERE T056_T054_Id=xT054_Id

                AND T056_Flag_Calcular_Imposto_Importacao='S'

                AND T056_T060_Id=0;

        IF xValor_Total_Produtos IS NULL THEN

            SET xValor_Total_Produtos=0;

        END IF;

        IF xValor_Total_Custo_Original IS NULL THEN

            SET xValor_Total_Custo_Original=0;

        END IF;

        IF xValor_Total_Frete IS NULL THEN

            SET xValor_Total_Frete=0;

        END IF;

        IF xValor_Despesas_Aduaneira IS NULL THEN

            SET xValor_Despesas_Aduaneira=0;

        END IF;

        IF xValor_Despesas_Aduaneira_Real IS NULL THEN

            SET xValor_Despesas_Aduaneira_Real=0;

        END IF;

        IF xValor_Despesas_ICMS IS NULL THEN

            SET xValor_Despesas_ICMS=0;

        END IF;

        IF xValor_Despesas_PIS_COFINS IS NULL THEN

            SET xValor_Despesas_PIS_COFINS=0;

        END IF;

        IF xValor_Despesas_IPI IS NULL THEN

            SET xValor_Despesas_IPI=0;

        END IF;

        IF xValor_Despesas_Imposto_Importacao IS NULL THEN

            SET xValor_Despesas_Imposto_Importacao=0;

        END IF;

        IF xPeso_Kg_Liquido_Total IS NULL THEN

            SET xPeso_Kg_Liquido_Total=0;

        END IF;

        IF xPeso_Kg_Liquido_Fatura_Total IS NULL THEN

            SET xPeso_Kg_Liquido_Fatura_Total=0;

        END IF;

        IF xPeso_Lb_Liquido_Total IS NULL THEN

            SET xPeso_Lb_Liquido_Total=0;

        END IF;

        UPDATE T054 SET T054_Valor_Total_Produtos                    = xValor_Total_Produtos,

                        T054_Valor_Total_Produtos_Real               = if(T054_D044_Id=2,T054_Valor_Total_Produtos*T054_Valor_Cambio_Dolar,if(T054_D044_Id=3,T054_Valor_Total_Produtos*T054_Valor_Cambio_Euro,0)),

                        T054_Valor_Total_Custo_Original              = xValor_Total_Custo_Original,

                        T054_Valor_Total_IPI                         = xValor_IPI,

                        T054_Valor_Total_IPI_Real                    = if(T054_D044_Id=2,T054_Valor_Total_IPI*T054_Valor_Cambio_Dolar,if(T054_D044_Id=3,T054_Valor_Total_IPI*T054_Valor_Cambio_Euro,0)),

                        T054_Valor_Total_Base_IPI                    = xValor_Base_IPI,

                        T054_Valor_Total_Imposto_Importacao          = xValor_Imposto_Importacao,

                        T054_Valor_Total_Imposto_Importacao_Real     = if(T054_D044_Id=2,T054_Valor_Total_Imposto_Importacao*T054_Valor_Cambio_Dolar,if(T054_D044_Id=3,T054_Valor_Total_Imposto_Importacao*T054_Valor_Cambio_Euro,0)),

                        T054_Valor_Total_Base_Imposto_Importacao     = xValor_Base_Imposto_Importacao,

                        T054_Valor_Total_COFINS                      = xValor_COFINS,

                        T054_Valor_Total_COFINS_Real                 = if(T054_D044_Id=2,T054_Valor_Total_COFINS*T054_Valor_Cambio_Dolar,if(T054_D044_Id=3,T054_Valor_Total_COFINS*T054_Valor_Cambio_Euro,0)),

                        T054_Valor_Total_Base_COFINS                 = xValor_Base_COFINS,

                        T054_Valor_Total_PIS                         = xValor_PIS,

                        T054_Valor_Total_PIS_Real                    = if(T054_D044_Id=2,T054_Valor_Total_PIS*T054_Valor_Cambio_Dolar,if(T054_D044_Id=3,T054_Valor_Total_PIS*T054_Valor_Cambio_Euro,0)),

                        T054_Valor_Total_Base_PIS                    = xValor_Base_PIS,

                        T054_Valor_Total_Extra                       = xValor_Extra,

                        T054_Valor_Total_Extra_Real                  = if(T054_D044_Id=2,T054_Valor_Total_Extra*T054_Valor_Cambio_Dolar,if(T054_D044_Id=3,T054_Valor_Total_Extra*T054_Valor_Cambio_Euro,0)),

                        T054_Valor_Total_Base_Extra                  = xValor_Base_Extra,

                        T054_Valor_Total_Despesas                    = xValor_Total_Despesas,

                        T054_Valor_Total_Despesas_Real               = xValor_Total_Despesas_Real,

                        T054_Valor_Total_Despesas_Fatura             = xValor_Total_Despesas_Fatura,

                        T054_Peso_Kg_Liquido                         = xPeso_Kg_Liquido_Total,

                        T054_Peso_Kg_Liquido_Fatura             = xPeso_Kg_Liquido_Fatura_Total,

                        T054_Peso_Lb_Liquido                         = xPeso_Lb_Liquido_Total,

                        T054_Valor_Total_Frete                       = xValor_Total_Frete,

                        T054_Valor_Total_Frete_Real                  = if(T054_D044_Id=2,T054_Valor_Total_Frete*T054_Valor_Cambio_Dolar,if(T054_D044_Id=3,T054_Valor_Total_Frete*T054_Valor_Cambio_Euro,0)),

                        T054_Valor_Total_Despesas_Aduaneira          = xValor_Despesas_Aduaneira,

                        T054_Valor_Total_Despesas_Aduaneira_Real     = if(T054_D044_Id=2,xValor_Despesas_Aduaneira*T054_Valor_Cambio_Dolar,if(T054_D044_Id=3,xValor_Despesas_Aduaneira*T054_Valor_Cambio_Euro,0)),

                        T054_Valor_Total_Despesas_Imposto_Importacao = xValor_Despesas_Imposto_Importacao,

                        T054_Valor_Total_Despesas_IPI                = xValor_Despesas_IPI,

                        T054_Valor_Total_Despesas_PIS_COFINS         = xValor_Despesas_PIS_COFINS,

                        T054_Valor_Total_Despesas_ICMS               = xValor_Despesas_ICMS,

                        T054_Valor_Total_Aduaneiro                   = T054_Valor_Total_Produtos + T054_Valor_Total_Frete + T054_Valor_Total_Despesas_Aduaneira,

                        T054_Valor_Total_Aduaneiro_Real              = if(T054_D044_Id=2,T054_Valor_Total_Aduaneiro*T054_Valor_Cambio_Dolar,if(T054_D044_Id=3,T054_Valor_Total_Aduaneiro*T054_Valor_Cambio_Euro,0)),

                        T054_Valor_Total_Base_ICMS                   = xValor_Total_Base_ICMS_Normal,

                        T054_Valor_Total_Base_ICMS_Presumido         = xValor_Total_Base_ICMS_Presumido,

                        T054_Valor_Total_ICMS                        = xValor_Total_ICMS_Normal,

                        T054_Valor_Total_ICMS_Real                   = if(T054_D044_Id=2,T054_Valor_Total_ICMS*T054_Valor_Cambio_Dolar,if(T054_D044_Id=3,T054_Valor_Total_ICMS*T054_Valor_Cambio_Euro,0)),

                        T054_Valor_Total_ICMS_Presumido              = xValor_Total_ICMS_Presumido,

                        T054_Valor_Total_ICMS_Presumido_Real         = if(T054_D044_Id=2,T054_Valor_Total_ICMS_Presumido*T054_Valor_Cambio_Dolar,if(T054_D044_Id=3,T054_Valor_Total_ICMS_Presumido*T054_Valor_Cambio_Euro,0)),

                        T054_Valor_Total_ICMS_Pagar                  = xValor_Total_ICMS_Pagar,

                        T054_Valor_Total_ICMS_Pagar_Real             = if(T054_D044_Id=2,T054_Valor_Total_ICMS_Pagar*T054_Valor_Cambio_Dolar,if(T054_D044_Id=3,T054_Valor_Total_ICMS_Pagar*T054_Valor_Cambio_Euro,0)),

                        T054_Valor_Total_DI                          = T054_Valor_Total_Aduaneiro+T054_Valor_Total_Imposto_Importacao+T054_Valor_Total_PIS+T054_Valor_Total_COFINS+T054_Valor_Total_IPI+T054_Valor_Total_ICMS,

                        T054_Valor_Total_DI_Real                     = T054_Valor_Total_Aduaneiro_Real+T054_Valor_Total_Imposto_Importacao_Real+T054_Valor_Total_PIS_Real+T054_Valor_Total_COFINS_Real+T054_Valor_Total_IPI_Real+T054_Valor_Total_ICMS_Real,

                        T054_Valor_Total                             = T054_Valor_Total_Aduaneiro+T054_Valor_Total_Imposto_Importacao+T054_Valor_Total_PIS+T054_Valor_Total_COFINS+T054_Valor_Total_IPI+T054_Valor_Total_ICMS+T054_Valor_Total_Extra+T054_Valor_Total_Despesas,

                        T054_Valor_Total_Real                        = T054_Valor_Total_Aduaneiro_Real+T054_Valor_Total_Imposto_Importacao_Real+T054_Valor_Total_PIS_Real+T054_Valor_Total_COFINS_Real+T054_Valor_Total_IPI_Real+T054_Valor_Total_ICMS_Real+ifnull(T054_Valor_Total_Extra_Real,0)+ifnull(T054_Valor_Total_Despesas_Real,0),

                        T054_Valor_Total2_Real                       = T054_Valor_Total_Produtos_Real+xValor_Total_Frete_Real+T054_Valor_Total_Despesas_Aduaneira_Real+T054_Valor_Total_Imposto_Importacao_Real+T054_Valor_Total_PIS_Real+T054_Valor_Total_COFINS_Real+T054_Valor_Total_IPI_Real+T054_Valor_Total_ICMS_Real+ifnull(T054_Valor_Total_Extra_Real,0)+ifnull(T054_Valor_Total_Despesas_Real,0),

                        T054_Valor_Total_Diferenca                   = T054_Valor_Total2_Real-T054_Valor_Total_Real,

                        T054_Valor_Cambio_Real                       = T054_Valor_Total2_Real/T054_Valor_Total,

                        T054_Valor_Total_CIF                         = T054_Valor_Total_Produtos + T054_Valor_Total_Frete,

                        T054_Valor_Total_CIF_Real                    = if(T054_D044_Id=2,T054_Valor_Total_CIF*T054_Valor_Cambio_Dolar,if(T054_D044_Id=3,T054_Valor_Total_CIF*T054_Valor_Cambio_Euro,0))

                  WHERE T054_Id=xT054_Id;

    END IF;

END */$$
DELIMITER ;

/* Procedure structure for procedure `T055_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T055_Gravar_Totalizacao`(xT055_Id int(11))
BEGIN
    DECLARE xT075_Valor_SISCOMEX DECIMAL(16,6);
    DECLARE xT075_Valor_Imposto_Importacao DECIMAL(16,6);
    DECLARE xT075_Valor_IPI DECIMAL(16,6);
    DECLARE xT075_Valor_PIS DECIMAL(16,6);
    DECLARE xT075_Valor_COFINS DECIMAL(16,6);
    DECLARE xT075_Valor_ICMS DECIMAL(16,6);
    DECLARE xT075_Valor_THC DECIMAL(16,6);
    DECLARE xT075_Valor_Frete_Incluso DECIMAL(16,6);
    DECLARE xT075_Valor_Frete DECIMAL(16,6);
    DECLARE xT055_Valor_Frete DECIMAL(16,6);
    DECLARE xT075_Valor_Seguro DECIMAL(16,6);
    DECLARE xT075_Valor_Despesa DECIMAL(16,6);
    DECLARE xT075_Valor_Total_Custo DECIMAL(16,6);
    DECLARE xT075_Valor_VMLE DECIMAL(16,6);
    DECLARE xT055_Valor_Total_Custo DECIMAL(16,6);
    DECLARE xPeso_Total DECIMAL(16,6);
    DECLARE xPeso_Item DECIMAL(16,6);
    DECLARE xT075_Id INT(10);
    DECLARE xAliquota_ICMS DECIMAL(5,2);
    DECLARE xAliquota_ICMS_Normal DECIMAL(5,2);
    DECLARE xAliquota_ICMS_Presumido DECIMAL(5,2);
    DECLARE xT075_Aliquota_ICMS_PIS_COFINS DECIMAL(5,2);
    DECLARE xValor_Base_IPI DECIMAL(19,6);
    DECLARE xValor_Base_II DECIMAL(19,6);
    DECLARE xValor_Base_PIS_COFINS DECIMAL(19,6);
    DECLARE xValor_Base_ICMS DECIMAL(19,6);
    DECLARE xPercentual_Reducao_ICMS DECIMAL(19,4);
    DECLARE xPercentual_Reducao_ICMS_Presumido DECIMAL(19,4);
    DECLARE xValor_Despesas_Acessorias DECIMAL(19,4) DEFAULT 0;
    DECLARE xT075_Cotacao_ME DECIMAL(10,4);
    DECLARE xFlag_Frete VARCHAR(1);
    DECLARE xT075_Valor_AFRMM DECIMAL(16,6);
    
    SELECT T055_T075_Id,
           T055_Valor_Custo_Unitario * T055_Quantidade ,
           T055_Peso_Kg_Liquido_Total,
           T055_Flag_Frete
      INTO xT075_Id,
           xT055_Valor_Total_Custo,
           xPeso_Item,
           xFlag_Frete
      FROM T055
     WHERE T055_Id=xT055_Id;

    SELECT sum(T055_Peso_Kg_Liquido_Total)
      INTO xPeso_Total
      FROM T055
     WHERE T055_T075_Id=xT075_Id
       AND T055_Flag_Frete = 'S';
       
    SELECT IF(SUM(T168_Valor)=0 OR SUM(T168_Valor) IS NULL,0,SUM(T168_Valor)) 
      INTO xT075_Valor_Despesa
      FROM T168
     WHERE T168_T075_Id=xT075_Id;

    SELECT (T075_Aliquota_ICMS/100),
           (100-T075_Aliquota_ICMS),
           (T075_Aliquota_ICMS_Presumido/100),
           if(T075_Percentual_Reducao_ICMS>0,(T075_Percentual_Reducao_ICMS/100),1),
           if(ifnull(T075_Percentual_Reducao_ICMS_Presumido,0)>0,(T075_Percentual_Reducao_ICMS_Presumido/100),0),
           (T075_Aliquota_ICMS_PIS_COFINS/100),
           T075_Valor_SISCOMEX,
           T075_Valor_Imposto_Importacao,
           T075_Valor_IPI,
           T075_Valor_PIS,
           T075_Valor_Cofins,
           T075_Valor_ICMS,
           T075_Valor_THC,
           T075_Valor_Frete_Incluso,
           T075_Valor_Frete,
           T075_Valor_Seguro,
           T075_Valor_AFRMM,
           T075_Valor_VMLE,
           T075_Cotacao_ME
      INTO xAliquota_ICMS,
           xAliquota_ICMS_Normal,
           xAliquota_ICMS_Presumido,
           xPercentual_Reducao_ICMS,
           xPercentual_Reducao_ICMS_Presumido,
           xT075_Aliquota_ICMS_PIS_COFINS,
           xT075_Valor_SISCOMEX,
           xT075_Valor_Imposto_Importacao,
           xT075_Valor_IPI,
           xT075_Valor_PIS,
           xT075_Valor_Cofins,
           xT075_Valor_ICMS,
           xT075_Valor_THC,
           xT075_Valor_Frete_Incluso,
           xT075_Valor_Frete,
           xT075_Valor_Seguro,
           xT075_Valor_AFRMM,
           xT075_Valor_VMLE,
           xT075_Cotacao_ME
      FROM T075
      WHERE T075_Id=xT075_Id;
      
      SET xT055_Valor_Total_Custo = xT055_Valor_Total_Custo * xT075_Cotacao_ME;
      SET xT075_Valor_VMLE = xT075_Valor_VMLE * xT075_Cotacao_ME;
      SET xT075_Valor_Frete = xT075_Valor_Frete * xT075_Cotacao_ME;
      
      IF xFlag_Frete = 'S' THEN
         SET xT055_Valor_Frete      = (xT075_Valor_Frete)*(xPeso_Item/xPeso_Total);
      ELSE
         SET xT055_Valor_Frete      = 0;
      END IF;
      
      SET xValor_Base_II         = ((xT075_Valor_Seguro+xT075_Valor_THC)*(xT055_Valor_Total_Custo/xT075_Valor_VMLE))+xT055_Valor_Frete;
      SET xValor_Base_IPI        = ((xT075_Valor_Seguro+xT075_Valor_THC)*(xT055_Valor_Total_Custo/xT075_Valor_VMLE))+xT055_Valor_Frete;
      SET xValor_Base_PIS_COFINS = ((xT075_Valor_Seguro+xT075_Valor_THC)*(xT055_Valor_Total_Custo/xT075_Valor_VMLE))+xT055_Valor_Frete;
      SET xValor_Base_ICMS       = ((xT075_Valor_Seguro+xT075_Valor_THC+xT075_Valor_SISCOMEX)*(xT055_Valor_Total_Custo/xT075_Valor_VMLE))+xT055_Valor_Frete;
      SET xT075_Valor_SISCOMEX   = (xT075_Valor_SISCOMEX)*(xT055_Valor_Total_Custo/xT075_Valor_VMLE);
      SET xT075_Valor_THC        = (xT075_Valor_THC)*(xT055_Valor_Total_Custo/xT075_Valor_VMLE);
      SET xT075_Valor_Seguro     = (xT075_Valor_Seguro)*(xT055_Valor_Total_Custo/xT075_Valor_VMLE);
      SET xT075_Valor_Despesa    = (xT075_Valor_Despesa)*(xT055_Valor_Total_Custo/xT075_Valor_VMLE);
      SET xT075_Valor_AFRMM      = (xT075_Valor_AFRMM)*(xT055_Valor_Total_Custo/xT075_Valor_VMLE);
      
        UPDATE T055 SET T055_Valor_Total_Custo                   = T055_Valor_Custo_Unitario * T055_Quantidade,
                        T055_Valor_Total_Despesas_Aduaneira      = xT075_Valor_SISCOMEX,
                        T055_Valor_Despesas_Aduaneira            = T055_Valor_Total_Despesas_Aduaneira / T055_Quantidade,
                        T055_Valor_Total_Despesas                = xT075_Valor_Despesa,
                        T055_Valor_Despesas                      = T055_Valor_Total_Despesas / T055_Quantidade,
                        T055_Valor_Total_Frete                   = xT055_Valor_Frete,
                        T055_Valor_Frete                         = T055_Valor_Total_Frete  / T055_Quantidade,
                        T055_Valor_Total_Aduaneira               = xT055_Valor_Total_Custo+T055_Valor_Total_Frete+T055_Valor_Total_Despesas_Aduaneira,
                        T055_Valor_Aduaneira                     = xT075_Valor_THC,
                        T055_Valor_Total_AFRMM                   = xT075_Valor_AFRMM,
                        T055_Valor_AFRMM                         = T055_Valor_Total_AFRMM / T055_Quantidade,
                        T055_Valor_Base_Imposto_Importacao       = xT055_Valor_Total_Custo+xValor_Base_II,
                        T055_Valor_Imposto_Importacao            = T055_Valor_Base_Imposto_Importacao*(T055_Aliquota_Imposto_Importacao/100),
                        T055_Valor_Base_IPI                      = xT055_Valor_Total_Custo+xValor_Base_IPI+T055_Valor_Imposto_Importacao,
                        T055_Valor_IPI                           = T055_Valor_Base_IPI * ( T055_Aliquota_IPI / 100 ),
                        T055_Multiplicador_X                     = ( 1 + xT075_Aliquota_ICMS_PIS_COFINS * ( (T055_Aliquota_Imposto_Importacao/100) + (T055_Aliquota_IPI/100) * ( 1 + (T055_Aliquota_Imposto_Importacao/100) ) ) ) / ( ( 1 - (T055_Aliquota_PIS/100) - (T055_Aliquota_COFINS/100) ) * ( 1 - xT075_Aliquota_ICMS_PIS_COFINS ) ),
                        T055_Valor_Base_PIS                      = xT055_Valor_Total_Custo + xValor_Base_PIS_COFINS,
                        T055_Valor_PIS                           = ( T055_Aliquota_PIS/100 ) *  T055_Valor_Base_PIS * T055_Multiplicador_X,
                        T055_Valor_Base_COFINS                   = xT055_Valor_Total_Custo + xValor_Base_PIS_COFINS,
                        T055_Valor_COFINS                        = ( T055_Aliquota_COFINS/100 ) *  T055_Valor_Base_COFINS * T055_Multiplicador_X,
                        T055_Valor_Base_ICMS_Sem_Reducao         = xT055_Valor_Total_Custo + xValor_Base_ICMS + T055_Valor_PIS + T055_Valor_COFINS + T055_Valor_IPI + T055_Valor_Imposto_Importacao + T055_Valor_Total_AFRMM,
                        T055_Valor_Base_ICMS_Normal              = round( ( T055_Valor_Base_ICMS_Sem_Reducao * 100 ) / xAliquota_ICMS_Normal , 2),                                                                                                                           
                        T055_Valor_Base_ICMS_Presumido           = round( ( ( T055_Valor_Base_ICMS_Sem_Reducao * 100 ) / xAliquota_ICMS_Normal ) * IF(xPercentual_Reducao_ICMS_Presumido>0, xPercentual_Reducao_ICMS_Presumido, 1) , 2 ),
                        T055_Valor_ICMS                          = (T055_Valor_Base_ICMS_Normal * xAliquota_ICMS) - ((T055_Valor_Base_ICMS_Normal * xAliquota_ICMS) * xPercentual_Reducao_ICMS_Presumido),
                        T055_Valor_ICMS_Presumido                = T055_Valor_Base_ICMS_Presumido * xAliquota_ICMS_Presumido,
                        T055_Valor_ICMS_Pagar                    = T055_Valor_ICMS - T055_Valor_ICMS_Presumido,
                        T055_Peso_Kg_Liquido_Total               = T055_Peso_Kg_Liquido_Unitario * T055_Quantidade,
                        T055_Peso_Kg_Liquido_Total_Fatura        = T055_Peso_Kg_Liquido_Unitario_Fatura * T055_Quantidade,
                        T055_Peso_Lb_Liquido_Unitario            = T055_Peso_Kg_Liquido_Unitario * 2.2,
                        T055_Peso_Lb_Liquido_Total               = T055_Peso_Lb_Liquido_Unitario * T055_Quantidade,
                        T055_Aliquota_Extra                      = 0.00,
                        T055_Valor_Total_ICMS                    = T055_Valor_ICMS,
                        T055_Valor_Total_ICMS_Presumido          = T055_Valor_ICMS_Presumido,
                        T055_Valor_Total_ICMS_Pagar              = T055_Valor_ICMS_Pagar,
                        T055_Valor_Total_IPI                     = T055_Valor_IPI,
                        T055_Valor_Total_Imposto_Importacao      = T055_Valor_Imposto_Importacao,
                        T055_Valor_Total_COFINS                  = T055_Valor_COFINS,
                        T055_Valor_Total_PIS                     = T055_Valor_PIS,
                        T055_Valor_Total_Extra                   = T055_Valor_Extra,
                        T055_Valor_Total_Base_IPI                = T055_Valor_Base_IPI,
                        T055_Valor_Total_Base_ICMS_Sem_Reducao   = T055_Valor_Base_ICMS_Sem_Reducao,
                        T055_Valor_Total_Base_ICMS_Normal        = T055_Valor_Base_ICMS_Normal,
                        T055_Valor_Total_Base_ICMS_Presumido     = T055_Valor_Base_ICMS_Presumido,
                        T055_Valor_Total_Base_COFINS             = T055_Valor_Base_COFINS,
                        T055_Valor_Total_Base_PIS                = T055_Valor_Base_PIS,
                        T055_Valor_Total_Base_Imposto_Importacao = T055_Valor_Base_Imposto_Importacao,
                        T055_Valor_Total_Preco_Nota_Fiscal       = xT055_Valor_Total_Custo + xValor_Base_II + T055_Valor_Imposto_Importacao + T055_Valor_PIS + T055_Valor_COFINS,
                        T055_Valor_Preco_Unitario_Nota_Fiscal    = T055_Valor_Total_Preco_Nota_Fiscal / T055_Quantidade,
                        T055_Valor_Total_Despesas_Acessorias_Nota_Fiscal = xValor_Despesas_Acessorias,
                        T055_Valor_Total_Custo_Final             = xT055_Valor_Total_Custo +
                                                                   T055_Valor_Total_Despesas_Aduaneira +
                                                                   T055_Valor_Imposto_Importacao +
                                                                   T055_Valor_PIS +
                                                                   T055_Valor_COFINS +
                                                                   T055_Valor_Aduaneira +
                                                                   T055_Valor_Total_Despesas +
                                                                   T055_Valor_Total_Frete +
                                                                   T055_Valor_Total_AFRMM +
                                                                   xT075_Valor_Seguro, 
                        T055_Valor_Custo_Final_Unitario          = T055_Valor_Total_Custo_Final / T055_Quantidade
                  WHERE T055_Id=xT055_Id;
END */$$
DELIMITER ;

/* Procedure structure for procedure `T056_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T056_Gravar_Totalizacao`(xT056_Id int(11))
BEGIN

    UPDATE T056 SET T056_Valor_Total_Despesa = if(T056_D044_Id=1,T056_Valor_Total_Despesa_Real/T056_Valor_Cambio,T056_Valor_Total_Despesa),

                    T056_Valor_Total_Despesa_Real  = if(T056_D044_Id!=1,T056_Valor_Total_Despesa * T056_Valor_Cambio,T056_Valor_Total_Despesa_Real),

T056_Valor_Total_Despesa_Pagamento = if(T056_D044_Id=1,T056_Valor_Total_Despesa_Real_Pagamento/T056_Valor_Cambio_Pagamento,T056_Valor_Total_Despesa_Pagamento),

                    T056_Valor_Total_Despesa_Real_Pagamento  = if(T056_D044_Id!=1,T056_Valor_Total_Despesa_Pagamento * T056_Valor_Cambio_Pagamento,T056_Valor_Total_Despesa_Real_Pagamento) WHERE T056_Id=xT056_Id;

END */$$
DELIMITER ;

/* Procedure structure for procedure `T059_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T059_Gravar_Totalizacao`(xT059_Id int(11))
BEGIN

    UPDATE T059 SET T059_Valor_Total_Custo=T059_Valor_Custo_Unitario*T059_Quantidade WHERE T059_Id=xT059_Id;

END */$$
DELIMITER ;

/* Procedure structure for procedure `T128_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T128_Gravar_Totalizacao`(xT128_Id int(11))
BEGIN

    UPDATE T128

    SET T128_Valor_Total_Custo=(SELECT sum(T129_Valor_Total_Custo) FROM T129 WHERE T129_T128_Id=T128_Id),

        T128_Valor_Total_Pendente=(SELECT sum(T129_Quantidade_Falta_Lancar(T129_Id,0)*T129_Valor_Custo_Unitario) FROM T129 WHERE T129_T128_Id=T128_Id)

    WHERE T128_Id=xT128_Id;

END */$$
DELIMITER ;

/* Procedure structure for procedure `T129_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T129_Gravar_Totalizacao`(xT129_Id int(11))
BEGIN

    UPDATE T129 SET T129_Valor_Total_Custo=T129_Valor_Custo_Unitario*T129_Quantidade WHERE T129_Id=xT129_Id;

END */$$
DELIMITER ;

/* Procedure structure for procedure `T218_Gravar_Totalizacao_3` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T218_Gravar_Totalizacao_3`(xT218_Id int(11))
BEGIN
    DECLARE xValor_Total_Custo DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Preco DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Produtos DECIMAL(10,2);
    DECLARE xValor_Total_Produtos_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Agregados DECIMAL(10,2);
    DECLARE xValor_Total_Servicos DECIMAL(10,2);
    DECLARE xValor_Total_Trocas DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Bruto DECIMAL(10,2);
    DECLARE xValor_ICMS DECIMAL(10,2);
    DECLARE xValor_ICMS_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_ICMS DECIMAL(10,2);
    DECLARE xValor_Base_ICMS_Confirmado DECIMAL(10,2);
    DECLARE xValor_IPI DECIMAL(10,2);
    DECLARE xValor_IPI_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_IPI DECIMAL(10,2);
    DECLARE xValor_Base_IPI_Confirmado DECIMAL(10,2);
    DECLARE xIPV DECIMAL(10,4);
    DECLARE xIPV_Confirmado DECIMAL(10,4);
    DECLARE xPeso_Total DECIMAL(10,3);
    DECLARE xPeso_Bruto_Total DECIMAL(10,3);
    DECLARE xPeso_Total_Confirmado DECIMAL(10,3);
    DECLARE xValor_Total_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Desconto_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_ST DECIMAL(10,2);
    DECLARE xValor_ST DECIMAL(10,2);
    DECLARE xValor_Base_ST_Confirmado DECIMAL(10,2);
    DECLARE xValor_ST_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Cubagem DECIMAL(10,3) default 0;
    DECLARE xValor_Trib_Transparencia DECIMAL(15,2) DEFAULT 0;
    SELECT sum(T219_Valor_Total_Custo),
           sum(T219_Valor_Total_Custo_Confirmado),
           sum(T219_Valor_Total_Preco),
           sum(T219_Valor_Total_Preco_Confirmado),
           sum(T219_Valor_Total_Preco_Sem_Desconto),
           sum(T219_Valor_Total_Preco_Sem_Desconto_Confirmado),
           sum(T219_Valor_Total_Custo_Final),
           sum(T219_Valor_Total_Custo_Final_Confirmado),
           sum(T219_Valor_ICMS),
           sum(T219_Valor_ICMS_Confirmado),
           sum(T219_Valor_Total_Agregados),
           sum(T219_Valor_Base_ICMS),
           sum(T219_Valor_Base_ICMS_Confirmado),
           sum(T219_Valor_IPI),
           sum(T219_Valor_IPI_Confirmado),
           sum(T219_Valor_Base_IPI),
           sum(T219_Valor_Base_IPI_Confirmado),
           sum(T219_Peso_Total),
           sum(T219_Peso_Bruto_Total),
           sum(T219_Peso_Total_Confirmado),
           sum(T219_Valor_Total_Desconto),
           sum(T219_Valor_Total_Desconto_Confirmado),
           sum(T219_Valor_Base_ST),
           sum(T219_Valor_ST),
           sum(T219_Valor_Base_ST_Confirmado),
           sum(T219_Valor_ST_Confirmado),
           sum(T219_Valor_Preco_Bruto),
           sum(T219_Total_Cubagem),
           sum(T219_Valor_Trib_Transparencia)
      INTO xValor_Total_Custo,
           xValor_Total_Custo_Confirmado,
           xValor_Total_Preco,
           xValor_Total_Preco_Confirmado,
           xValor_Total_Preco_Sem_Desconto,
           xValor_Total_Preco_Sem_Desconto_Confirmado,
           xValor_Total_Custo_Final,
           xValor_Total_Custo_Final_Confirmado,
           xValor_ICMS,
           xValor_ICMS_Confirmado,
           xValor_Total_Agregados,
           xValor_Base_ICMS,
           xValor_Base_ICMS_Confirmado,
           xValor_IPI,
           xValor_IPI_Confirmado,
           xValor_Base_IPI,
           xValor_Base_IPI_Confirmado,
           xPeso_Total,
           xPeso_Bruto_Total,
           xPeso_Total_Confirmado,
           xValor_Total_Desconto,
           xValor_Total_Desconto_Confirmado,
           xValor_Base_ST,
           xValor_ST,
           xValor_Base_ST_Confirmado,
           xValor_ST_Confirmado,
           xValor_Total_Preco_Bruto,
           xValor_Total_Cubagem,
           xValor_Trib_Transparencia
           FROM T219
           WHERE T219_T218_Id=xT218_Id
             AND T219_Flag_Cancelado!='S';
    SELECT SUM(T223_Valor_Unitario)
      INTO xValor_Total_Servicos
      FROM T223
     WHERE T223_T218_Id=xT218_Id;           
    SELECT SUM(T222_Valor_Preco_Unitario*T222_Quantidade)
      INTO xValor_Total_Trocas
      FROM T222
     WHERE T222_T218_Id=xT218_Id;           
    UPDATE T218 SET T218_Valor_Total_Servicos=ifnull(xValor_Total_Servicos,0),
                    T218_Valor_Troca=ifnull(xValor_Total_Trocas,0),
                    T218_Valor_Total_Produtos=xValor_Total_Preco,
                    T218_Valor_Total_Produtos_Confirmado=xValor_Total_Preco_Confirmado,
                    T218_Valor_Total_Produtos_Sem_Desconto=xValor_Total_Preco_Sem_Desconto,
                    T218_Valor_Total_Produtos_Sem_Desconto_Confirmado=xValor_Total_Preco_Sem_Desconto_Confirmado,
                    T218_Valor_Total_Custo_Final=xValor_Total_Custo_Final,
                    T218_Valor_Total_Custo_Final_Confirmado=xValor_Total_Custo_Final_Confirmado,
                    T218_Valor_Total_Custo=xValor_Total_Custo,
                    T218_Valor_Total_Custo_Confirmado=xValor_Total_Custo_Confirmado,
                    T218_Valor_Total_Agregados=ifnull(xValor_Total_Agregados,0),
                    T218_Valor_Total_Base_ICMS=xValor_Base_ICMS,
                    T218_Valor_Total_Base_ICMS_Confirmado=xValor_Base_ICMS_Confirmado,
                    T218_Valor_Total_ICMS=xValor_ICMS,
                    T218_Valor_Total_ICMS_Confirmado=xValor_ICMS_Confirmado,
                    T218_Valor_Total_Base_IPI=xValor_Base_IPI,
                    T218_Valor_Total_Base_IPI_Confirmado=xValor_Base_IPI_Confirmado,
                    T218_Valor_Total_IPI=xValor_IPI,
                    T218_Valor_Total_IPI_Confirmado=xValor_IPI_Confirmado,
                    T218_Valor_ISS=if(T218_Aliquota_ISS>0,T218_Valor_Mao_Obra*(T218_Aliquota_ISS/100),0),
                    T218_Valor_Base_ST=xValor_Base_ST,
                    T218_Valor_ST=xValor_ST,
                    T218_Valor_Base_ST_Confirmado=xValor_Base_ST_Confirmado,
                    T218_Valor_Desconto=xValor_Total_Desconto,
                    T218_Valor_Desconto_Confirmado=xValor_Total_Desconto_Confirmado,
                    T218_Valor_ST_Confirmado=xValor_ST_Confirmado,
                    T218_Valor_Total=ifnull(T218_Valor_Total_Produtos,0)+
                                     ifnull(T218_Valor_Mao_Obra,0)+
                                     ifnull(if(xValor_Total_Preco_Bruto>0,0,T218_Valor_Total_Agregados),0)+
                                     ifnull(T218_Valor_Despesas_Acessorias,0)+
                                     ifnull(T218_Valor_Total_IPI,0)+
                                     ifnull(T218_Valor_ST,0)+
                                     ifnull(T218_Valor_Total_Servicos,0)-
                                     ifnull(T218_Valor_Desconto_Manual,0)-
                                     ifnull(T218_Valor_Troca,0)+
                                     ifnull(T218_Valor_Frete,0),
                    T218_Valor_Total_Confirmado=if(T218_Flag_Confirmar_Mao_Obra='S' or ifnull(xValor_Total_Preco_Confirmado,0)>0,
                                     ifnull(T218_Valor_Total_Produtos_Confirmado,0)+
                                     ifnull(T218_Valor_Mao_Obra,0)+
                                     ifnull(T218_Valor_Despesas_Acessorias,0)+
                                     ifnull(T218_Valor_Total_IPI_Confirmado,0)+
                                     ifnull(T218_Valor_ST_Confirmado,0)+
                                     ifnull(T218_Valor_Total_Servicos,0)-
                                     ifnull(T218_Valor_Desconto_Manual_Confirmado,0)-
                                     ifnull(T218_Valor_Troca,0)+
                                     ifnull(T218_Valor_Frete,0),0),
                    T218_IPV=if(T218_Valor_Total_Custo>0,T218_Valor_Total/T218_Valor_Total_Custo,0),
                    T218_IPV_Confirmado=if(T218_Valor_Total_Custo_Confirmado>0,T218_Valor_Total_Confirmado/T218_Valor_Total_Custo_Confirmado,0),
                    T218_IPV_Normal=ifnull(T218_IPV_Medio(xT218_Id,3),0),
                    T218_IPV_Normal_Confirmado=T218_IPV_Medio(xT218_Id,4),
                    T218_Peso_Total=ifnull(xPeso_Total,0),
                    T218_Peso_Bruto_Total=ifnull(xPeso_Bruto_Total,0),
                    T218_Peso_Total_Confirmado=ifnull(xPeso_Total_Confirmado,0),
                    T218_Total_Cubagem=IFNULL(xValor_Total_Cubagem,0),
                    T218_Valor_Total_Trib_Transparencia=xValor_Trib_Transparencia
              WHERE T218_Id=xT218_Id;
END */$$
DELIMITER ;

/* Procedure structure for procedure `T219_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T219_Gravar_Totalizacao`(xT219_Id int(11))
BEGIN

    DECLARE xT218_Id INT;

    DECLARE xPercentual_Desconto DECIMAL(30,20) DEFAULT 0;

    DECLARE xPercentual_Desconto_Bruto DECIMAL(30,20) DEFAULT 0;

    DECLARE xPercentual_Desconto_Confirmado DECIMAL(30,20) DEFAULT 0;

    DECLARE xMultiplicador_Despesa DECIMAL(10,6) DEFAULT 0;

    DECLARE xMultiplicador_Despesa_Confirmado DECIMAL(10,6) DEFAULT 0;

    DECLARE xMultiplicador_Despesas_Acessorias DECIMAL(20,10) DEFAULT 0;

    DECLARE xFlag_Revenda_Consumidor VARCHAR(1);

    DECLARE xD006_Flag_Forma_Calculo_COFINS varchar(1) default 'V';

    DECLARE xD006_Flag_Forma_Calculo_PIS varchar(1) default 'V';

    DECLARE xD006_Flag_Somar_Despesas_Base_ST ENUM('S','N') DEFAULT 'N';

    DECLARE xValor_Total_Agregados DECIMAL(10,2) DEFAULT 0;

    DECLARE xC004_Casas_Decimais_Preco int(2);

    DECLARE xC004_Id int(10);

    DECLARE xD006_Flag_Somar_IPI_Base_ICMS varchar(1);

    DECLARE xValor_Total_Frete DECIMAL(19,2) DEFAULT 0;

    DECLARE xMultiplicador_Frete DECIMAL(20,10) DEFAULT 0;

    DECLARE xTotal_Itens INT(5);

    DECLARE xC004_Flag_Rateio_Frete VARCHAR(1) DEFAULT '1';



      SELECT T219_T218_Id,

           D006_Flag_Forma_Calculo_COFINS,

           D006_Flag_Forma_Calculo_PIS,

           D006_Flag_Somar_IPI_Base_ICMS,

           D006_Flag_Somar_Despesas_Base_ST,

           T219_Percentual_Desconto/100,

           T219_Percentual_Desconto/100,

           T219_Percentual_Desconto_Bruto/100,

           T219_C004_Id

      INTO xT218_Id,

           xD006_Flag_Forma_Calculo_COFINS,

           xD006_Flag_Forma_Calculo_PIS,

           xD006_Flag_Somar_IPI_Base_ICMS,

           xD006_Flag_Somar_Despesas_Base_ST,

           xPercentual_Desconto,

           xPercentual_Desconto_Confirmado,

           xPercentual_Desconto_Bruto,

           xC004_Id

      FROM T219

      LEFT JOIN D006 ON D006_Id=T219_D006_Id

      WHERE T219_Id=xT219_Id;



      SELECT C004_Casas_Decimais_Preco,

      		 C004_Flag_Rateio_Frete

        INTO xC004_Casas_Decimais_Preco,

        	 xC004_Flag_Rateio_Frete

        FROM C004

       WHERE C004_Id=xC004_Id;



      if !(xPercentual_Desconto>0 OR xPercentual_Desconto<0) THEN

         SELECT T218_Percentual_Desconto/100,

                T218_Percentual_Desconto_Confirmado/100

           INTO xPercentual_Desconto,

                xPercentual_Desconto_Confirmado

         FROM T218

         LEFT JOIN C004 ON C004_Id=T218_C004_Id

         WHERE T218_Id=xT218_Id;

      END IF;



      SELECT SUM(T202_Valor_Unitario) INTO xValor_Total_Agregados FROM T202 WHERE T202_T219_Id=xT219_Id;



      IF xPercentual_Desconto IS NULL THEN

         set xPercentual_Desconto = 0;

      END IF;

      IF xPercentual_Desconto_Bruto IS NULL THEN

         set xPercentual_Desconto_Bruto = 0;

      END IF;

       IF xPercentual_Desconto_Confirmado IS NULL THEN

         set xPercentual_Desconto_Confirmado = 0;

      END IF;



      UPDATE T219

                SET T219_Valor_Desconto_Unitario = if(xPercentual_Desconto>0 or xPercentual_Desconto<0,T219_Valor_Preco_Original*xPercentual_Desconto,0),

                	  T219_Valor_Desconto_Unitario_Bruto = if(xPercentual_Desconto_Bruto>0 or xPercentual_Desconto_Bruto<0,T219_Valor_Preco_Original_Bruto*xPercentual_Desconto_Bruto,0),

                    T219_Valor_Desconto_Unitario_Confirmado = if(xPercentual_Desconto_Confirmado>0 or xPercentual_Desconto_Confirmado<0,T219_Valor_Preco_Original*xPercentual_Desconto_Confirmado,0),

                    T219_Valor_Total_Desconto = T219_Valor_Desconto_Unitario*T219_Quantidade,

                    T219_Valor_Total_Desconto_Confirmado = T219_Valor_Desconto_Unitario_Confirmado*T219_Quantidade_Confirmada,

                    T219_Valor_Preco_Unitario = round(T219_Valor_Preco_Original - T219_Valor_Desconto_Unitario,xC004_Casas_Decimais_Preco),

                    T219_Valor_Preco_Bruto = round(T219_Valor_Preco_Original_Bruto - T219_Valor_Desconto_Unitario_Bruto,xC004_Casas_Decimais_Preco),

                    T219_Valor_Preco_Unitario_Confirmado = round(T219_Valor_Preco_Original - T219_Valor_Desconto_Unitario_Confirmado,xC004_Casas_Decimais_Preco),

                    T219_Valor_Total_Preco = T219_Valor_Preco_Unitario*T219_Quantidade,

                    T219_Valor_Total_Preco_Confirmado = T219_Valor_Preco_Unitario_Confirmado * T219_Quantidade_Confirmada,

                    T219_Valor_Total_Preco_Sem_Desconto = T219_Valor_Preco_Original * T219_Quantidade,

                    T219_Valor_Total_Preco_Sem_Desconto_Confirmado = T219_Valor_Preco_Original * T219_Quantidade_Confirmada,

                    T219_Valor_Total_Agregados=xValor_Total_Agregados,

                    T219_Aliquota_PIS=if(T219_Flag_Isento_PIS='S',0,T219_Aliquota_PIS),

                    T219_Aliquota_COFINS=if(T219_Flag_Isento_COFINS='S',0,T219_Aliquota_COFINS),

                    T219_Valor_Base_PIS=if(T219_Flag_Isento_PIS='S',0,if(xD006_Flag_Forma_Calculo_PIS='L',if(T219_Quantidade_Confirmada>0,T219_Valor_Total_Preco_Confirmado-T219_Valor_Total_Custo_Confirmado,T219_Valor_Total_Preco-T219_Valor_Total_Custo),if(T219_Quantidade_Confirmada>0,T219_Valor_Total_Preco_Confirmado,T219_Valor_Total_Preco))),

                    T219_Valor_PIS=if(T219_Aliquota_PIS>0,T219_Valor_Base_PIS*(T219_Aliquota_PIS/100),0),

                    T219_Valor_Base_COFINS=if(T219_Flag_Isento_COFINS='S',0,if(xD006_Flag_Forma_Calculo_COFINS='L',if(T219_Quantidade_Confirmada>0,T219_Valor_Total_Preco_Confirmado-T219_Valor_Total_Custo_Confirmado,T219_Valor_Total_Preco-T219_Valor_Total_Custo),if(T219_Quantidade_Confirmada>0,T219_Valor_Total_Preco_Confirmado,T219_Valor_Total_Preco))),

                    T219_Valor_COFINS=if(T219_Aliquota_COFINS>0,T219_Valor_Base_COFINS*(T219_Aliquota_COFINS/100),0),

                    T219_Valor_Trib_Transparencia=IFNULL(T219_Valor_Total_Preco,0)*(IFNULL(T219_Percentual_Trib_Transparencia,0)/100)

                 WHERE T219_Id=xT219_Id;

                 SELECT (if (T218_Flag_Frete=1,T218_Valor_Frete,0)+T218_Valor_Despesas_Acessorias)/sum(T219_Valor_Preco_Unitario*T219_Quantidade),

                           (if (T218_Flag_Frete=1,T218_Valor_Frete,0)+T218_Valor_Despesas_Acessorias)/sum(T219_Valor_Preco_Unitario*T219_Quantidade_Confirmada),

                           T218_Flag_Revenda_Consumidor

                  INTO xMultiplicador_Despesa,

                        xMultiplicador_Despesa_Confirmado,

                        xFlag_Revenda_Consumidor

                  FROM T218

                  LEFT JOIN T219 ON T219_T218_Id=T218_Id

                 WHERE T218_Id=xT218_Id

                 GROUP BY T218_Id;

       IF xMultiplicador_Despesa IS NULL THEN

           set xMultiplicador_Despesa = 0;

       END IF;

       IF xMultiplicador_Despesa_Confirmado IS NULL THEN

           set xMultiplicador_Despesa_Confirmado = 0;

       END IF;

       

       	SELECT COUNT(*) INTO xTotal_Itens FROM T219 WHERE T219_T218_Id = xT218_Id;



		SELECT T218_Valor_Frete/SUM(T219_Valor_Preco_Unitario*T219_Quantidade),

				T218_Valor_Frete,

				T218_Valor_Despesas_Acessorias/SUM(T219_Valor_Preco_Unitario*T219_Quantidade)

		INTO xMultiplicador_Frete,

			xValor_Total_Frete,

			xMultiplicador_Despesas_Acessorias

		FROM T218

		LEFT JOIN T219 ON T219_T218_Id=T218_Id

		WHERE T218_Id=xT218_Id

		GROUP BY T218_Id;



		UPDATE T219 SET T219_Valor_Total_Despesas_Acessorias=T219_Valor_Total_Preco*xMultiplicador_Despesas_Acessorias,

				T219_Valor_Despesas_Acessorias_Unitario=T219_Valor_Total_Despesas_Acessorias/T219_Quantidade,

				T219_Valor_Frete_Total=IF(xC004_Flag_Rateio_Frete=1,T219_Valor_Total_Preco*xMultiplicador_Frete,xValor_Total_Frete/xTotal_Itens),

				T219_Valor_Frete_Unitario=T219_Valor_Frete_Total/T219_Quantidade

		WHERE T219_Id=xT219_Id;

       

		UPDATE T219

    LEFT JOIN D009 ON D009_Id=T219_D009_Id

		            SET T219_Peso_Total=T219_Peso_Unitario*T219_Quantidade,

                    T219_Peso_Bruto_Total=T219_Peso_Bruto*T219_Quantidade,

                    T219_Peso_Total_Confirmado=T219_Peso_Unitario*T219_Quantidade_Confirmada,

                    T219_Valor_Total_Despesas=(T219_Valor_Total_Preco*xMultiplicador_Despesa)+xValor_Total_Agregados,

                    T219_Valor_Total_Despesas_Confirmado=T219_Valor_Total_Preco_Confirmado*xMultiplicador_Despesa_Confirmado,

                    T219_Valor_Despesas_Unitario=T219_Valor_Total_Despesas/T219_Quantidade,

                    T219_Valor_Despesas_Unitario_Confirmado=T219_Valor_Total_Despesas_Confirmado/T219_Quantidade_Confirmada,

                    T219_Valor_Base_IPI=IF(T219_Aliquota_IPI>0,(T219_Valor_Total_Preco)*IF(T219_Percentual_Reducao_IPI>0,(T219_Percentual_Reducao_IPI/100),1),0),

                    T219_Valor_Base_IPI_Confirmado=IF(T219_Aliquota_IPI>0,(T219_Valor_Total_Preco_Confirmado)*IF(T219_Percentual_Reducao_IPI,(T219_Percentual_Reducao_IPI/100),1),0),

                    T219_Valor_IPI=T219_Valor_Base_IPI*(T219_Aliquota_IPI/100),

                    T219_Valor_IPI_Confirmado=T219_Valor_Base_IPI_Confirmado*(T219_Aliquota_IPI/100),

                    T219_Valor_Total_Custo_Final=(T219_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T219_Valor_Total_Despesas,0)+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T219_Valor_IPI,0)),

                    T219_Valor_Total_Custo_Final_Confirmado=(T219_Valor_Total_Preco_Confirmado+if(xD006_Flag_Somar_Despesas_Base_ST='S',T219_Valor_Total_Despesas_Confirmado,0)+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T219_Valor_IPI,0)),

                    T219_Valor_Custo_Final_Unitario=T219_Valor_Total_Custo_Final/T219_Quantidade,

                    T219_Valor_Custo_Final_Unitario_Confirmado=T219_Valor_Total_Custo_Final_Confirmado/T219_Quantidade_Confirmada,

                    T219_Valor_Base_ICMS=IF(T219_Aliquota_ICMS>0,T219_Valor_Total_Custo_Final*IF(T219_Percentual_Reducao_ICMS>0,(T219_Percentual_Reducao_ICMS/100),1),0),

                    T219_Valor_Base_ICMS_Confirmado=IF(T219_Aliquota_ICMS>0,T219_Valor_Total_Custo_Final_Confirmado*IF(T219_Percentual_Reducao_ICMS>0,(T219_Percentual_Reducao_ICMS/100),1),0),

                    T219_Valor_ICMS=T219_Valor_Base_ICMS*(T219_Aliquota_ICMS/100),

                    T219_Valor_ICMS_Confirmado=T219_Valor_Base_ICMS_Confirmado*(T219_Aliquota_ICMS/100),

                    T219_ST_VA_Ajustada = ( ( (1+(T219_ST_VA/100)) *   ( ( 1 - ( T219_ICMS_Inter_Estadual / 100 ) ) / ( 1 - ( T219_ST_ICMS_Interno / 100 ) ) ) ) - 1 ) * 100,

                    T219_Valor_Base_ST=IF(T219_Flag_ST='S',(T219_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T219_Valor_Total_Despesas,0)+T219_Valor_IPI)*((T219_ST_VA_Ajustada/100)+1),0),

                    T219_Valor_ST=IF(T219_Flag_ST='S',((T219_Valor_Base_ST*IF(T219_Percentual_Reducao_ICMS_ST>0,(T219_Percentual_Reducao_ICMS_ST/100),1))*(T219_ST_ICMS_Interno/100))-((T219_Valor_Total_Custo_Final*IF(T219_Percentual_Reducao_ICMS>0,(T219_Percentual_Reducao_ICMS/100),1))*(T219_ICMS_Inter_Estadual/100)),0),

                    T219_Valor_ST=IF(T219_Valor_ST<0,0,T219_Valor_ST),

                    T219_Valor_Base_ST_Confirmado=IF(T219_Flag_ST='S',(T219_Valor_Total_Custo_Final_Confirmado+T219_Valor_Despesas_Unitario_Confirmado+T219_Valor_IPI_Confirmado)*((T219_ST_VA_Ajustada/100)+1),0),

                    T219_Valor_ST_Confirmado=IF(T219_Flag_ST='S',(T219_Valor_Base_ST_Confirmado*(T219_ST_ICMS_Interno/100))-((T219_Valor_Total_Custo_Final_Confirmado*IF(T219_Percentual_Reducao_ICMS>0,(T219_Percentual_Reducao_ICMS/100),1))*(T219_ICMS_Inter_Estadual/100)),0),

                    T219_Valor_ST_Confirmado=IF(T219_Valor_ST_Confirmado<0,0,T219_Valor_ST_Confirmado),

                    T219_IPV=D009_IPV_1,

                    T219_Total_Cubagem = IFNULL(T219_Cubagem_Unitaria, 0) * IFNULL(T219_Quantidade,0),

                    T219_Valor_Trib_Transparencia=IFNULL(T219_Valor_Total_Preco,0)*(IFNULL(T219_Percentual_Trib_Transparencia,0)/100),

                    T219_Valor_Frete=T219_Valor_Total_Preco * (T219_Percentual_Frete/100),

                    T219_Valor_Financeiro=T219_Valor_Total_Preco * (T219_Percentual_Financeiro/100),

                    T219_Valor_Total_Custo=T219_Valor_Total_Preco+T219_Valor_IPI+T219_Valor_ST+T219_Valor_Frete+T219_Valor_Financeiro,

                    T219_Valor_Custo_Unitario=T219_Valor_Total_Custo/T219_Quantidade,

                    T219_Valor_Preco_Venda=T219_Valor_Custo_Unitario*T219_IPV,

                    T219_Valor_Total_Custo_Confirmado=T219_Valor_Custo_Unitario*T219_Quantidade_Confirmada

                    WHERE T219_Id=xT219_Id;

       CALL T218_Gravar_Totalizacao_3(xT218_Id);

END */$$
DELIMITER ;

/* Procedure structure for procedure `T224_Gravar_Totalizacao_3` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T224_Gravar_Totalizacao_3`(xT224_Id int(11))
BEGIN
    DECLARE xValor_Total_Custo DECIMAL(10,2);
    DECLARE xValor_Total_Preco DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final DECIMAL(10,2);
    DECLARE xValor_Total_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Servicos DECIMAL(10,2);
    DECLARE xValor_Total_Trocas DECIMAL(10,2);
    DECLARE xValor_ICMS DECIMAL(10,2);
    DECLARE xValor_Base_ICMS DECIMAL(10,2);
    DECLARE xValor_Total_Agregados DECIMAL(10,2);
    DECLARE xValor_IPI DECIMAL(10,2);
    DECLARE xValor_Base_IPI DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Bruto DECIMAL(10,2);
    DECLARE xIPV DECIMAL(10,4);
    DECLARE xPeso_Total DECIMAL(10,3);
    DECLARE xPeso_Bruto_Total DECIMAL(10,3);
    DECLARE xValor_Base_ICMS_Substituicao DECIMAL(10,2) DEFAULT 0;
    DECLARE xValor_ICMS_Substituicao DECIMAL(10,2) DEFAULT 0;
    DECLARE xValor_ICMS_Substituicao_Retencao DECIMAL(10,2) DEFAULT 0;
    DECLARE xValor_Total_PIS decimal(10,2) DEFAULT 0;
    DECLARE xValor_Total_COFINS decimal(10,2) default 0;
    DECLARE xValor_Total_Comissao decimal(14,5) default 0;
    DECLARE xValor_Total_Cubagem DECIMAL(10,3) default 0;
    DECLARE xValor_Trib_Transparencia DECIMAL(15,2) DEFAULT 0;
    SELECT sum(T225_Valor_Total_Custo),
           sum(T225_Valor_Total_Preco),
           sum(T225_Valor_Total_Preco_Sem_Desconto),
           sum(T225_Valor_Total_Custo_Final),
           sum(T225_Valor_Total_Desconto),
           sum(T225_Valor_ICMS),
           sum(T225_Valor_Base_ICMS),
           sum(T225_Valor_Total_Agregados),
           sum(T225_Valor_IPI),
           sum(T225_Valor_Base_IPI),
           sum(T225_Peso_Total),
           sum(T225_Peso_Bruto_Total),
           sum(T225_Valor_Base_ICMS_Substituicao),
           sum(T225_Valor_ICMS_Substituicao),
           sum(T225_Valor_ICMS_Substituicao_Retencao),
           sum(T225_Valor_PIS),
           sum(T225_Valor_COFINS),
           sum(T225_Valor_Preco_Bruto),
           sum(T225_Valor_Comissao),
           sum(T225_Total_Cubagem),
           sum(T225_Valor_Trib_Transparencia)
      INTO xValor_Total_Custo,
           xValor_Total_Preco,
           xValor_Total_Preco_Sem_Desconto,
           xValor_Total_Custo_Final,
           xValor_Total_Desconto,
           xValor_ICMS,
           xValor_Base_ICMS,
           xValor_Total_Agregados,
           xValor_IPI,
           xValor_Base_IPI,
           xPeso_Total,
           xPeso_Bruto_Total,
           xValor_Base_ICMS_Substituicao,
           xValor_ICMS_Substituicao,
           xValor_ICMS_Substituicao_Retencao,
           xValor_Total_PIS,
           xValor_Total_COFINS,
           xValor_Total_Preco_Bruto,
           xValor_Total_Comissao,
           xValor_Total_Cubagem,
           xValor_Trib_Transparencia
           FROM T225
           WHERE T225_T224_Id=xT224_Id and T225_Flag_Status!=3;
    SELECT SUM(T230_Valor_Unitario)
      INTO xValor_Total_Servicos
      FROM T230
     WHERE T230_T224_Id=xT224_Id;           
    SELECT SUM(T222_Valor_Preco_Unitario*T222_Quantidade)
      INTO xValor_Total_Trocas
      FROM T222
     WHERE T222_T224_Id=xT224_Id;           
    UPDATE T224 SET T224_Peso_Total=ifnull(xPeso_Total,0),
                    T224_Peso_Bruto_Total=ifnull(xPeso_Bruto_Total,0),
                    T224_Valor_Total_Servicos=ifnull(xValor_Total_Servicos,0),
                    T224_Valor_Troca=ifnull(xValor_Total_Trocas,0),
                    T224_Valor_Total_Agregados=ifnull(xValor_Total_Agregados,0),
                    T224_Valor_Total_Produtos=ifnull(xValor_Total_Preco,0),
                    T224_Valor_Total_Produtos_Sem_Desconto=ifnull(xValor_Total_Preco_Sem_Desconto,0),
                    T224_Valor_Total_Custo_Final=ifnull(xValor_Total_Custo_Final,0)-T224_Valor_Desconto,
                    T224_Valor_Total_Custo=ifnull(xValor_Total_Custo,0),
                    T224_Valor_Total_Base_ICMS=ifnull(xValor_Base_ICMS,0),
                    T224_Valor_Total_ICMS=ifnull(xValor_ICMS,0),
                    T224_Valor_Total_Base_IPI=ifnull(xValor_Base_IPI,0),
                    T224_Valor_Total_IPI=ifnull(xValor_IPI,0),
                    T224_Valor_Total_PIS=ifnull(xValor_Total_PIS,0),
                    T224_Valor_Total_COFINS=ifnull(xValor_Total_COFINS,0),
                    T224_Valor_ISS=if(T224_Aliquota_ISS>0,T224_Valor_Mao_Obra*(T224_Aliquota_ISS/100),0),
                    T224_Valor_Base_ICMS_Substituicao=ifnull(xValor_Base_ICMS_Substituicao,0),
                    T224_Valor_ICMS_Substituicao=ifnull(xValor_ICMS_Substituicao,0),
                    T224_Valor_ICMS_Substituicao_Retencao=ifnull(xValor_ICMS_Substituicao_Retencao,0),
                    T224_Valor_Total=if(T224_Flag_Status=8,0,
                                     ifnull(round(T224_Valor_Total_Produtos_Sem_Desconto,2),0)+
                                     ifnull(T224_Valor_Mao_Obra,0)+
                                     ifnull(if(xValor_Total_Preco_Bruto>0,0,T224_Valor_Total_Agregados),0)+
                                     ifnull(T224_Valor_Despesas_Acessorias,0)+
                                     ifnull(round(T224_Valor_ICMS_Substituicao_Retencao,2),0)+
                                     ifnull(round(T224_Valor_Total_IPI,2),0)+
                                     ifnull(T224_Valor_Total_Servicos,0)-
                                     ifnull(T224_Valor_Desconto_Manual,0)-
                                     ifnull(T224_Valor_Troca,0)+
                                     ifnull(if(xValor_Total_Preco_Bruto>0,0,T224_Valor_Frete),0)),
                    T224_IPV=ifnull(T224_IPV_Medio(xT224_Id,1),0),
                    T224_IPV_Normal=ifnull(T224_IPV_Medio(xT224_Id,2),0),
                    T224_Valor_Total_Comissao=ifnull(xValor_Total_Comissao,0),
                    T224_Total_Cubagem=IFNULL(xValor_Total_Cubagem,0),
                    T224_Valor_Total_Trib_Transparencia=xValor_Trib_Transparencia
              WHERE T224_Id=xT224_Id;

    UPDATE T224 SET T224_Peso_Liquido=ifnull(xPeso_Total,0),
                    T224_Peso_Bruto=ifnull(xPeso_Bruto_Total,0)
                WHERE T224_Id=xT224_Id AND T224_Flag_Totalizar_Peso = 'S';
END */$$
DELIMITER ;

/* Procedure structure for procedure `T225_Gravar_Totalizacao` */

DELIMITER $$

/*!50003 CREATE DEFINER=`e230`@`%` PROCEDURE `T225_Gravar_Totalizacao`(xT225_Id int(11))
BEGIN

    DECLARE xT224_Id int;

    DECLARE xPercentual_Desconto DECIMAL(20,10) DEFAULT 0;

    DECLARE xPercentual_Desconto_Bruto DECIMAL(20,10) DEFAULT 0;

    DECLARE xMultiplicador_Despesa DECIMAL(20,10) DEFAULT 0;

    DECLARE xMultiplicador_Despesas_Acessorias DECIMAL(20,10) DEFAULT 0;

    DECLARE xMultiplicador_Frete DECIMAL(20,10) DEFAULT 0;

    DECLARE xFlag_Revenda_Consumidor VARCHAR(1);

    DECLARE xFlag_Devolucao VARCHAR(1);

    DECLARE xFlag_Tipo_Devolucao VARCHAR(10);

    DECLARE xValor_Total_Frete DECIMAL(19,2) DEFAULT 0;

    DECLARE xValor_Total_Despesas_Acessorias DECIMAL(10,2) DEFAULT 0;

    DECLARE xValor_Total_Agregados DECIMAL(10,2) DEFAULT 0;

    DECLARE xValor_Total_Desconto DECIMAL(10,2) DEFAULT 0;

    DECLARE xFlag_ST VARCHAR(3);

    DECLARE xFlag_Venda_Compra_Outros VARCHAR(1);

    DECLARE xAliquota_ICMS_1 DECIMAL(5,2);



    DECLARE xT134_Id int(10) default '0';

    DECLARE xT134_Reducao_Base_ICMS decimal(10,2) default '0';



    DECLARE xD006_Flag_Somar_IPI_Base_ICMS ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Somar_Despesas_Base_IPI ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Somar_Despesas_Base_ST ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Isento_PIS ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Situacao_Tributaria_PIS VARCHAR(2) default '01';

    DECLARE xD006_Flag_Isento_COFINS ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Situacao_Tributaria_COFINS VARCHAR(2) default '01';

    DECLARE xD059_Codigo_ST varchar(3);

    DECLARE xC004_Percentual_PIS decimal(6,2) DEFAULT 0;

    DECLARE xC004_Percentual_COFINS decimal(6,2) DEFAULT 0;

    DECLARE xC004_Flag_Rateio_Frete VARCHAR(1) DEFAULT '1';

    DECLARE xTotal_Itens INT(5);

    DECLARE xD049_Flag_Nacional_Importado varchar(1);



    DECLARE xD006_Flag_Forma_Calculo_COFINS varchar(1) default 'V';

    DECLARE xD006_Flag_Forma_Calculo_PIS varchar(1) default 'V';



    DECLARE xC004_Casas_Decimais_Preco int(2);

    DECLARE xC004_Id int(10);

    

    DECLARE xT185_Qtd_Separado DECIMAL(20,2) DEFAULT 0;

    

    -- caso esteja utilizando a tabela T185, a quantidade de itens separados tem que ser pega desta tabela

    SELECT COUNT(T185_Qtd_Separado) INTO xT185_Qtd_Separado FROM T185 WHERE T185_T225_Id = xT225_Id;

    IF xT185_Qtd_Separado > 0 THEN

	SELECT SUM(T185_Qtd_Separado) INTO xT185_Qtd_Separado FROM T185 WHERE T185_T225_Id = xT225_Id;

	UPDATE T225 SET T225_Quantidade_Separacao = xT185_Qtd_Separado WHERE T225_Id = xT225_Id;

    END IF;



    SELECT ifnull(SUM(T204_Valor_Unitario),0) INTO xValor_Total_Agregados FROM T204 WHERE T204_T225_Id=xT225_Id;

    

    -- GRAVA A CFOP POR ITEM PARA OS QUE AINDA NAO TEM CFOP

    update T225 left join T224 on T224_Id=T225_T224_Id set T225_D006_Id=T224_D006_Id where T225_Id=xT225_Id and T225_D006_Id is null;



    SELECT T225_T224_Id,

           D006_Flag_Venda_Compra_Outros,

           D049_Flag_Nacional_Importado,

           D006_Flag_Somar_IPI_Base_ICMS,

           D006_Flag_Somar_Despesas_Base_IPI,

           D006_Flag_Somar_Despesas_Base_ST,

           D006_Flag_Forma_Calculo_COFINS,

           D006_Flag_Forma_Calculo_PIS,

           T225_C004_Id,

           T134_Reducao_Base_ICMS,

           T134_Id,

           T225_Percentual_Desconto_Bruto/100

      INTO xT224_Id,

           xFlag_Venda_Compra_Outros,

           xD049_Flag_Nacional_Importado,

           xD006_Flag_Somar_IPI_Base_ICMS,

           xD006_Flag_Somar_Despesas_Base_IPI,

           xD006_Flag_Somar_Despesas_Base_ST,

           xD006_Flag_Forma_Calculo_COFINS,

           xD006_Flag_Forma_Calculo_PIS,

           xC004_Id,

           xT134_Reducao_Base_ICMS,

           xT134_Id,

           xPercentual_Desconto_Bruto

      FROM T225

      LEFT JOIN T224 ON T224_Id=T225_T224_Id

      LEFT JOIN D006 ON D006_Id=T225_D006_Id

      LEFT JOIN T134 ON T134_Id=T224_T134_Id

      LEFT JOIN D024 ON D024_Id=T224_D024_Id

      LEFT JOIN D020 ON D020_Id=D024_D020_Id

      LEFT JOIN D009 ON D009_Id=T225_D009_Id

      LEFT JOIN D049 ON D049_Id=D009_D049_Id

      LEFT JOIN D001 ON D001_Id=D049_D001_Id

     WHERE T225_Id=xT225_Id

     LIMIT 1;



     SELECT COUNT(*) INTO xTotal_Itens FROM T225 WHERE T225_T224_Id = xT224_Id;

     

     SELECT C004_Casas_Decimais_Preco,

             C004_Flag_Rateio_Frete

        INTO xC004_Casas_Decimais_Preco,

             xC004_Flag_Rateio_Frete

        FROM C004

       WHERE C004_Id=xC004_Id;



    SELECT T224_Percentual_Desconto/100,

           T224_Flag_Devolucao,

           T224_Flag_Tipo_Devolucao

      INTO xPercentual_Desconto,

           xFlag_Devolucao,

           xFlag_Tipo_Devolucao

      FROM T224

      LEFT JOIN C004 ON C004_Id=T224_C004_Id

     WHERE T224_Id=xT224_Id;

     

    IF xPercentual_Desconto IS NULL THEN

       set xPercentual_Desconto = 0;

    END IF;   

    

    UPDATE T225 SET T225_Valor_Desconto_Unitario = if(xPercentual_Desconto>0,T225_Valor_Preco_Sem_Desconto_Unitario*xPercentual_Desconto,0),

    				T225_Valor_Desconto_Unitario_Bruto = if(xPercentual_Desconto_Bruto>0 or xPercentual_Desconto_Bruto<0,T225_Valor_Preco_Original_Bruto*xPercentual_Desconto_Bruto,0),

                    T225_Valor_Total_Desconto = T225_Valor_Desconto_Unitario*T225_Quantidade,

                    T225_Valor_Preco_Unitario = round(T225_Valor_Preco_Sem_Desconto_Unitario - T225_Valor_Desconto_Unitario,xC004_Casas_Decimais_Preco),

                    T225_Valor_Total_Preco = T225_Valor_Preco_Unitario*T225_Quantidade,

                    T225_Valor_Total_Preco_Sem_Desconto = T225_Valor_Preco_Sem_Desconto_Unitario * T225_Quantidade,

                    T225_Valor_Preco_Bruto = round(T225_Valor_Preco_Original_Bruto - T225_Valor_Desconto_Unitario_Bruto,xC004_Casas_Decimais_Preco)

              WHERE T225_Id=xT225_Id;



    IF xFlag_Devolucao='S' AND xFlag_Tipo_Devolucao='EMITIDA' THEN

       UPDATE T225 SET T225_Valor_Total_Frete=T225_Valor_Frete_Unitario*T225_Quantidade,

                       T225_Valor_Total_Despesas_Acessorias=T225_Valor_Despesas_Acessorias_Unitario*T225_Quantidade,

                       T225_Valor_Total_Desconto=T225_Valor_Desconto_Unitario*T225_Quantidade

              WHERE T225_T224_Id=xT224_Id;

       SELECT SUM(T225_Valor_Total_Frete),

              SUM(T225_Valor_Total_Despesas_Acessorias),

              SUM(T225_Valor_Total_Desconto)

         INTO xValor_Total_Frete,

              xValor_Total_Despesas_Acessorias,

              xValor_Total_Desconto

         FROM T225

         WHERE T225_T224_Id=xT224_Id

         GROUP BY T225_T224_Id;

         UPDATE T224

         SET T224_Valor_Frete=xValor_Total_Frete,

              T224_Valor_Despesas_Acessorias=xValor_Total_Despesas_Acessorias

         WHERE T224_Id=xT224_Id;

    ELSE

           SELECT T224_Valor_Frete/sum(T225_Valor_Preco_Unitario*T225_Quantidade),

                  T224_Valor_Frete,

                  T224_Valor_Despesas_Acessorias/sum(T225_Valor_Preco_Unitario*T225_Quantidade)

           INTO xMultiplicador_Frete,

                xValor_Total_Frete,

                xMultiplicador_Despesas_Acessorias

         FROM T224

         LEFT JOIN T225 ON T225_T224_Id=T224_Id

         WHERE T224_Id=xT224_Id

         GROUP BY T224_Id;

        UPDATE T225 SET T225_Valor_Total_Despesas_Acessorias=T225_Valor_Total_Preco*xMultiplicador_Despesas_Acessorias,

                        T225_Valor_Despesas_Acessorias_Unitario=T225_Valor_Total_Despesas_Acessorias/T225_Quantidade,

                        T225_Valor_Total_Frete=IF(xC004_Flag_Rateio_Frete=1,T225_Valor_Total_Preco*xMultiplicador_Frete,xValor_Total_Frete/xTotal_Itens),

                        T225_Valor_Frete_Unitario=T225_Valor_Total_Frete/T225_Quantidade

                  WHERE T225_Id=xT225_Id;

    END IF;

    SELECT (T224_Valor_Frete+T224_Valor_Despesas_Acessorias)/sum(T225_Valor_Preco_Unitario*T225_Quantidade),

           T224_Flag_Revenda_Consumidor

      INTO

        xMultiplicador_Despesa,

        xFlag_Revenda_Consumidor

      FROM T224

      LEFT JOIN T225 ON T225_T224_Id=T224_Id

     WHERE T224_Id=xT224_Id

     GROUP BY T224_Id;

    IF xMultiplicador_Despesa IS NULL THEN

       set xMultiplicador_Despesa = 0;

    END IF;

    UPDATE T225 SET T225_Valor_Total_Custo = T225_Valor_Custo_Unitario*T225_Quantidade,

                    T225_Peso_Total = T225_Peso_Unitario*T225_Quantidade,

                    T225_Peso_Bruto_Total = T225_Peso_Bruto*T225_Quantidade,

                    T225_Valor_Total_Despesas=(T225_Valor_Total_Preco*xMultiplicador_Despesa)+xValor_Total_Agregados,

                    T225_Valor_Despesas_Unitario=T225_Valor_Total_Despesas/T225_Quantidade,

                    T225_Valor_Total_Agregados=xValor_Total_Agregados,

                    T225_Valor_Base_IPI=If(T225_Aliquota_IPI>0,(T225_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_IPI='S',T225_Valor_Total_Frete+T225_Valor_Total_Despesas_Acessorias,0))*If(T225_Percentual_Reducao_IPI>0,(T225_Percentual_Reducao_IPI/100),1),0),

                    T225_Valor_IPI=T225_Valor_Base_IPI*(T225_Aliquota_IPI/100),

                    T225_Valor_Total_Custo_Final=(T225_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T225_Valor_Total_Despesas,0)+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T225_Valor_IPI,0)),

                    T225_Valor_Custo_Final_Unitario=T225_Valor_Total_Custo_Final/T225_Quantidade,

                    T225_Valor_Base_ICMS=If(T225_Aliquota_ICMS>0,T225_Valor_Total_Custo_Final*if(T225_Percentual_Reducao_ICMS>0,(T225_Percentual_Reducao_ICMS/100),1),0),

                    T225_Valor_ICMS=T225_Valor_Base_ICMS*(T225_Aliquota_ICMS/100),

                    T225_IPV=T225_Valor_Preco_Unitario/T225_Valor_Custo_Unitario,

                    T225_Valor_Base_ICMS_Substituicao=IF(T225_Flag_ST='S',(T225_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T225_Valor_Total_Despesas,0)+T225_Valor_IPI)*((T225_ST_VA/100)+1),0),

                    T225_Valor_ICMS_Substituicao=(T225_Valor_Base_ICMS_Substituicao*(T225_ST_ICMS_Interno/100)),

                    T225_Valor_ICMS_Substituicao_Retencao=((T225_Valor_Base_ICMS_Substituicao*if(T225_Percentual_Reducao_ICMS_ST>0,(T225_Percentual_Reducao_ICMS_ST/100),1))*(T225_ST_ICMS_Interno/100))-((T225_Valor_Total_Custo_Final*if(T225_Percentual_Reducao_ICMS>0,(T225_Percentual_Reducao_ICMS/100),1))*(T225_ICMS_Inter_Estadual/100)),

                    T225_Valor_ICMS_Substituicao_Retencao=IF(T225_Valor_ICMS_Substituicao_Retencao<0,0,T225_Valor_ICMS_Substituicao_Retencao),

                    T225_Valor_Base_PIS=if(T225_Flag_Isento_PIS='S',0,if(xD006_Flag_Forma_Calculo_PIS='L',T225_Valor_Total_Preco-T225_Valor_Total_Custo,T225_Valor_Total_Preco)),

                    T225_Aliquota_PIS=if(T225_Flag_Isento_PIS='S',0,T225_Aliquota_PIS),

                    T225_Valor_PIS=if(T225_Aliquota_PIS>0,T225_Valor_Base_PIS*(T225_Aliquota_PIS/100),0),

                    T225_Valor_Base_COFINS=if(T225_Flag_Isento_COFINS='S',0,if(xD006_Flag_Forma_Calculo_COFINS='L',T225_Valor_Total_Preco-T225_Valor_Total_Custo,T225_Valor_Total_Preco)),

                    T225_Aliquota_COFINS=if(T225_Flag_Isento_COFINS='S',0,T225_Aliquota_COFINS),

                    T225_Valor_COFINS=if(T225_Aliquota_COFINS>0,T225_Valor_Base_COFINS*(T225_Aliquota_COFINS/100),0),

                    T225_Valor_ICMS_Credito=if(xT134_Id<=0 or xT134_Id='' or ifnull(xT134_Id,0)<=0,T225_Valor_ICMS_Credito,If(T225_Aliquota_ICMS_Credito>0,(T225_Valor_Total_Custo_Final+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T225_Valor_IPI,0))-((T225_Valor_Total_Custo_Final+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T225_Valor_IPI,0))*if(xT134_Reducao_Base_ICMS>0,(xT134_Reducao_Base_ICMS/100),1)),0)*(T225_Aliquota_ICMS_Credito/100)),

                    T225_Total_Cubagem = IFNULL(T225_Cubagem_Unitaria,0) * IFNULL(T225_Quantidade,0),

                    T225_Valor_Trib_Transparencia=IFNULL(T225_Valor_Total_Preco,0)*(IFNULL(T225_Percentual_Trib_Transparencia,0)/100)

              WHERE T225_Id=xT225_Id;

    CALL T224_Gravar_Totalizacao_3(xT224_Id);

END */$$
DELIMITER ;

/*!40101 SET SQL_MODE=@OLD_SQL_MODE */;
/*!40014 SET UNIQUE_CHECKS=@OLD_UNIQUE_CHECKS */;
/*!40111 SET SQL_NOTES=@OLD_SQL_NOTES */;
